begin;

insert into hadith (id, collection_id, chapter_id, number_in_book, kind, arabic, translation_en, narrator_ar, narrator_en, grade_ar, reference_ar, reference_en, reference_ur, full_ref_ar, explanation_ar, benefits_ar, word_meanings_ar, source, source_ref, daily_ok, review_note, deleted) values
(20961, 2, 208, 961, 'hadith', 'عن ابن عباس رضي الله عنهما عن النبي صلى الله عليه وسلم قال: «خير الصحابة أربعة وخير السرايا أربعمائة وخير الجيوش أربعة آلاف ولن يغلب اثنا عشر ألفاً عن قلة».', 'The Prophet (ﷺ) said, "The best number of companions is four; the best detachment is four hundred and the best army is four thousand; and twelve thousand men will not be defeated as a result of smallness of number.".', 'ابن عباس رضي الله عنهما', 'Ibn ''Abbas (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 961', 'Riyad as-Salihin 961', 'ریاض الصالحین 961', 'رواه أبو داود والترمذي وقال: حديث حسن', 'المعنى: هو أن أحسن الصُّحْبة أربعة، وأن أفضل سرية هي الـمُكوَّنة من أربعمائة، وأن أنفع الجنود الذين بلغوا أربعة آلاف، وأن الجيش إذا بلغ عدده اثنا عشر ألف جندي، والمراد فصاعدا، فإنه لا يُهْزم، وإذا هُزِم فإنه لا يُهْزم بسبب قلة عدده، وإنما قد يهزم لأسباب أخرى: مثل قلة الدين، أو الإعجاب بالكثرة، أو الوقوع في المعاصي، أو عدم الإخلاص لله تعالى ، ونحو ذلك.', 'أن في الجماعة تعاونا على الخير.
أن الهزيمة قد تكون لقلة الدين، أو الإعجاب بالكثرة وعدم التوكل على الله، ونحو ذلك.', 'خير : أحسن، وأفضل، وأنفع.
الصحابة : جمع صاحب، أو بمعنى: صُحْبَة.
السرايا : جمع سرية، وهي القطعة من الجيش.
من قلة : أي: بسبب قلة عددهم.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5956', false),
(20962, 2, 208, 962, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : "إذا سافرتم في الخصب فأعطوا الإبل حظها من الأرض وإذا سافرتم في الجدب فأسرعوا عليها السير وبادروا بها نقيها، وإذا عرستم، فاجتنبوا الطريق، فإن طرق الدواب، ومأوي الهوام بالليل" ((رواه مسلم)). معنى: "أعطوا الإبل حظها من الأرض" أي: ارفقوا بها في السير لترعي في حال سيرها وقوله: نقيها وهو بكسر النون، وإسكان القاف، وبالياء المثناة من تحت وهو: المخ، معناه: أسرعوا بها حتي تصلوا المقصد قبل أن يذهب مخها من ضنك السير. و التعريس النزول في الليل.', 'The Messenger of Allah (ﷺ) said: "When you travel through green and lush land, give the camels their due from the ground, and when you travel through a dry and barren land, make them walk quickly lest their strength falters. When you encamp at night, keep away from the roads, for beasts pass there and they are the resort of insects at night.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 962', 'Riyad as-Salihin 962', 'ریاض الصالحین 962', null, 'في الحديث مراعاة مصالح الإنسان والبهائم، حيث أرشد صلى الله عليه وسلم المسافرين إلى هذه الآداب: 
فأمر المسافر إذا سافر على راحلة بهيمة: من الإبل، أو الحمر أو البغال، أو الخيل؛ فإن عليه أن يراعي مصلحتها في الرعي والسير؛ لأنه مسؤول عنها: فإذا سافر في أيام كثرة الزرع والعلف؛ فإن عليه أن يتأنى ولا يسرع في السير حتى يعطي الدوابَّ حقها من الرعي، وأنه إذا سافر في أيام قلة الزرع والعلف؛ فإن عليه أن يُسرع في حدود طاقة الدابة؛ حتى لا يُجْهِد الدابَّة ويُتْعِبها. 
وكذلك أمر صلى الله عليه وسلم المسافر: إذا نزل في الليل ليستريح وينام؛ فإنه لا يفعل ذلك في الطريق، لأنها طرق دوابِّ المسافرين، يترددون عليها، فلا يمنعها عن طُرُقها ويُسَبِّب لها الضرر، وكذلك لأنها مأوى الحشرات ودواب الأرض من ذوات السموم والسباع، تمشي في الليل على الطرق؛ لسهولتها، ولأنها تلتقط منها ما يسقط من مأكول ونحوه.', 'إعطاء الدواب حقها في الأكل والمرعى، وعدم منعها منه.
اجتناب الأماكن التي يتوقع الإنسان فيها الأذى، وعدم النوم فيها.
حض الإسلام على الرفق بالحيوان، ومراعاة مصالحه في السير.
حرص النبي -صلى الله عليه وسلم- على مصالح المسلمين، وإرشادهم إليها.', 'في الخصب : في وقت كثرة الزرع والعَلَف والخير.
حظها من الأرض : نصيبها وحقَّها من نبات الأرض؛ يعني: دعوها ساعة فساعة ترعى.
الجدب : انقطاع المطر، ويُبْس الأرض.
فأسرعوا عليها السير : المعنى: فأسرعوا راكبين عليها، ولا توقفوها في الطريق لتُبَلِّغَكم المنزل قبل أن تَضْعُف.
وبادروا بها نقبها : النقي: المخ، والمعنى: أسرعوا بها حتى تصلوا إلى المكان الذي تقصدونه قبل أن يذهب مُخُّها مِن تَعَب السَّيْر، والنقب: المخ.
نِقيها : بكسر النون وإسكان القاف: المخ.
عرستم : التعريس: هو النزول في الليل للنوم والراحة.
فاجتنبوا الطريق : أي: أعرضوا عنها، وانزلوا يَمْنَة أو يَسْرَة.
طرق الدواب : أي: دواب المسافرين، أو دواب الأرض من السباع وغيرها.
ومأوى الهوام : المأوى: الملجأ. والهوام: هي الحشرات والحيوانات السامة كالأفاعي ونحوها.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5961', false),
(20963, 2, 208, 963, 'hadith', 'عن أبي قتادة، رضي الله عنه، قال: كان رسول الله صلى الله عليه وسلم ، إذا كان في سفر، فعرس بليل اضطجع علي يمينه وإذا عرس قبيل الصبح نصب ذراعه، ووضع رأسه علي كفه" ((رواه مسلم)). قال العلماء: إنما نصب ذراعه لئلا يستغرق في النوم، فتفوته صلاة الصبح عن وقتها أو عن أول وقتها.', 'When the Messenger of Allah (ﷺ) encamped at night during a journey, he would lie down on his right side, and when he stayed a little before dawn he would raise his forearm and place his head on the palm of his hand..', 'أبي قتادة رضي الله عنه', 'Abu Qatadah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 963', 'Riyad as-Salihin 963', 'ریاض الصالحین 963', null, 'كان من هديه صلى الله عليه وسلم أنه إذا نزل في أول الليل لينام وليستريح وضع جنبه على الأرض على يمينه، وإذا نزل قُرْب طُلُوع الفجر اتكأ ونصب يده واتكأ عليها؛ لأنه إذا كان في أول الليل ينام على اليمين؛ ليعطي النفس حظها من النوم، وأما إذا كان قُرْب الفجر فكان ينصب يده صلى الله عليه وسلم وينام عليها؛ لئلا يستغرق في النوم فتَفُوته صلاة الفجر.', 'استحباب النوم على الجنب الأيمن.
تشريف الجنب الأيمن على غيره.
الاحتياط للصلاة إذا احتاج الإنسان النوم قبلها، والحرص على أدائها في وقتها.
جواز النوم قبل دخول وقت الصلاة، إذا أمن فوات الصلاة.
إعطاء الإنسان نفسه حظها من الراحة مع عدم نسيان العبادة أو التفريط فيها.', 'عرّس : التعريس: هو النزول في الليل للنوم والراحة.
اضطجع : وضع جنبه على الأرض أو نحوها.
نصَب ذراعه : مَدَّ يده.
قبيل الصبح : قبل طلوع الصبح بقليل.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5968', false),
(20964, 2, 208, 964, 'hadith', 'عن أنس، رضي الله عنه، قال: قال رسول الله صلى الله عليه وسلم : «عليكم بالدلجة، فإن الأرض تطوي بالليل» ((رواه أبو داود بإسناد حسن)) الدلجة : السير في الليل', 'The Messenger of Allah (ﷺ) said, "Keep to travelling by night because the earth is folded (traversed more easily) during the night.".', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him)', null, 'رياض الصالحين 964', 'Riyad as-Salihin 964', 'ریاض الصالحین 964', null, null, null, null, 'sunnah.com', null, false, null, false),
(20965, 2, 208, 965, 'hadith', 'عن أبي ثعلبة الخشني، رضي الله عنه، قال: كان الناس إذا نزلوا منزلاً تفرقوا في الشعاب والأودية. فقال رسول الله، صلى الله عليه وسلم : «إن تفرقكم في هذه الشعاب والأودية إنما ذلكم من الشيطان!» فلم ينزلوا بعد ذلك منزلا إلا انضم بعضهم إلي بعض.', 'Whenever the people encamped during the journey, they would disperse in the mountain passes and valleys. (When) the Messenger of Allah (ﷺ) noticed this he said, "Your act of scattering in the mountain passes and valleys is from Satan." Afterwards the Companions kept close together whenever they encamped..', 'أبي ثعلبة الخشني رضي الله عنه', 'Abu Tha''labah Al-Khushani (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 965', 'Riyad as-Salihin 965', 'ریاض الصالحین 965', 'رواه أبو داود بإسناد حسن', 'كان الناس إذا نزلوا مكانا أثناء السفر تفرقوا في الشعاب والأودية، فأخبرهم النبي صلى الله عليه وسلم أن تفرقهم هذا من الشيطان؛ ليخوف أولياء الله ويحرك أعداءه، فلم ينزلوا بعد ذلك في مكان إلا انضم بعضهم إلى بعض، حتى لو بُسط عليهم كساء لوسعهم من شدة تقاربهم.', 'كراهية الانفراد في المنزل في السفر.
استحباب الاجتماع في السفر لحصول التعاون والأنس.
أن الفرقة من الشيطان.
سرعة استجابة الصحابة لأمر النبي -صلى الله عليه وسلم-.', 'منزلاً : مكانا ًفي أثناء السفر.
الشعاب : جمع شِعْب: وهو الطريق في الجبل.
الأودية : جمع واد: وهو مُنْفَرَج بين جبال أو تِلال أو آكام يكون مَنْفَذًا للسَّيْل ومَسْلَكًا.
من الشيطان : من وسوسته وإغوائه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5948', false),
(20966, 2, 208, 966, 'hadith', 'عن سهل بن عمرو -وقيل سهل بن الربيع بن عمرو الأنصاري المعروف بابن الحنظلية، وهو من أهل بيعة الرضوان، رضي الله عنه، قال: مر رسول الله صلى الله عليه وسلم ببعير قد لحق ظهره بطنه، فقال: «اتقوا الله في هذه البهائهم المعجمة، فاركبوها صالحة وكلوها صالحة».', 'The Messenger of Allah (ﷺ) happened to pass by a camel whose belly was sticking to its back (because of hunger), whereupon he said, "Fear Allah in respect of these dumb (animals). Ride them while they are fit, and slaughter them and eat their meat when they are fit.".', 'سهل بن عمرو -وقيل سهل بن الربيع بن عمرو الأنصاري المعروف بابن الحنظلية، وهو من أهل بيعة الرضوان رضي الله عنه', 'Sahl bin ''Amr known as Ibn Al-Hanzaliyyah', 'صحيح', 'رياض الصالحين 966', 'Riyad as-Salihin 966', 'ریاض الصالحین 966', 'رواه أبو داود بإسناد صحيح', null, null, null, 'sunnah.com', null, false, null, false),
(20967, 2, 208, 967, 'hadith', 'عن أبي جعفر عبد الله بن جعفر، رضي الله عنهما، قال: أردفني رسول الله صلى الله عليه وسلم ، ذات يوم خلفه، وأسر إلي حديثاً لا أحدث به أحداً من الناس وكان أحب ما أستتر به رسول الله صلى الله عليه وسلم لحاجته هدف أو حائش نخل. يعنى: حائط نخل" ((رواه هكذا مختصراً)). وزاد فيه البرقاني بإسناد مسلم بعد قوله: حائش نخل: فدخل حائطاً لرجل من الأنصار، فإذا فيه جمل، فلما رأي رسول الله صلى الله عليه وسلم جرجر وذرفت عيناه، فأتاه النبي صلى الله عليه وسلمى الله عليه وسلم الله عليه وسلم ، فمسح سراته -أى: سنامه- وذفراه فسكن؛ فقال: من رب هذا الجمل، لمن هذا الجمل؟ فجاء فتى من الأنصار، فقال: هذا لي يا رسول الله، فقال: أفلا تتقي الله في هذه البهيمة التي ملكك الله إياها؟ فإنه يشكو إلي أنك تجيعه وتدئبه ((رواه أبو داود كرواية البرقاني)). قوله: ذفراه وهو بكسر الذال المعجمة وإسكان الفاء، وهو لفظ مفرد مؤنث. قال أهل اللغة: الذفري: الموضع الذي يعرق من البعير خلف الأذن، وقوله: تذئبه أي: تتعبه.', 'The Messenger of Allah (ﷺ) made me ride behind him one day and confided something to me which I shall never disclose to anyone. (''Abdullah added:) He ((ﷺ) preferred to screen himself from others when responding to the call of nature, either behind a wall or the trunk of a date-palm..', 'أبي جعفر عبد الله بن جعفر رضي الله عنهما', 'Abu Ja''far ''Abdullah bin Ja''far (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 967', 'Riyad as-Salihin 967', 'ریاض الصالحین 967', null, 'عن عبد الله بن جعفر رضي الله عنه أن النبي صلى الله عليه وسلم أركبه خلفه ذات ليلة على الدابة، وكتم إليه بشيء من القول لا يحب رضي الله عنه أن يحدث به الناس، لأنه سر النبي صلى الله عليه وسلم، وأخبر أن النبي صلى الله عليه وسلم كان يحب إذا أراد قضاء حاجته أن يستتر إما بشيء مرتفع، أو ببستان يجتمع فيه النخل حتى لا يراه أحد، وهذا البستان مكان فيه زرع مرتفع لكنه لا يصلح لجلوس الناس فيه، وأن النبي صلى الله عليه وسلم دخل بستانا لرجل من الأنصار فوجد جملا، فلما رأى الجملُ رسولَ الله صلى الله عليه وسلم بكى؛ فمسح النبي صلى الله عليه وسلم سنامه وخلف أذنه، ثم سأل عن صاحب الجمل، فجاء فتى من الأنصار وأخبر أنه صاحبه، فقال له النبي صلى الله عليه وسلم: أفلا تتقي الله الذي جعلك مالكا لهذا الجمل، فإنه شكى لي أنك تجيعه وتتعبه.', 'جواز الإرداف على الدابة إن كانت الدابة قوية وتستطيع ذلك.
كتمان سر رسول الله صلى الله عليه وسلم، والمحافظة عليه، في شيء لا ينبني عليه حكم شرعي.
المبالغة في ستر العورة عند قضاء الحاجة.
بيان آية من آيات رسول الله صلى الله عليه وسلم حيث اشتكى إليه الجمل.
مشروعية الأمر بالمعرف والنهي عن المنكر.
تحريم ظلم الدواب: بإتعابها وتجويعها ونحو ذلك.
قيام الشرع على العدل والإنصاف.', 'أردفني : أركبني خلفه.
أَسَرّ : كتَم وأخفى.
لحاجته : أي: عند قضاء حاجته.
استَتَر به : احتجب عن أعين الناس.
هدف : كل شيء مرتفع.
حائشُ نَخْل : هو البستان الذي يجتمع فيه النخل.
جَرْجَر : ردَّد صوتًا في حلقه.
ذَرَفَتْ عيناه : سال منها الدمع.
ذِفْرَاه : الموضع الذي يعرق من البعير خلف أذنه.
تُدْئِبه : تتعبه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8842', false),
(20968, 2, 208, 968, 'hadith', 'عن أنس، رضي الله عنه، قال: كنا إذا نزلنا منزلا لا نسبح حتي نحل الرحال. ((رواه أبو داود بإسناد علي شرط مسلم)). وقوله: لا نسبح : أي لا نصلي النافلة، ومعناه: أنا -مع حرصنا علي الصلاة- لا نقدمها على حط الرحال وإراحة الدواب', 'When we encamped, we would not offer (voluntary) prayers until we had unsaddled our beasts..', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 968', 'Riyad as-Salihin 968', 'ریاض الصالحین 968', null, 'يخبر أنس رضي الله عنه أن الصحابة رضي الله عنهم كانوا إذا سافروا، ثم وقفوا في مكان للراحة ونحوها أو وصلوا لوجهتهم، لم يبادروا لصلاة النافلة -مع حرصهم على الصلاة- حتى يريحوا الدواب التي تحمل أمتعة المسافرين، وذلك بسرعة إنزال الأمتعة عنها، تخفيفًا عنها ورحمةً بها.', 'استحباب إراحة البهائم بالحط عنها قبل الاشتغال بعبادة أو غيرها لما لحقها من التعب.
استحباب التنفل المطلق في السفر.
حرص الصحابة على تنفيذ وصايا رسول الله -صلى الله عليه وسلم- عمومًا، ومنها الوصية بالإحسان إلى الدواب.
يشرع للمصلي ألا يدخل الصلاة, وباله مشغول بغيرها, حتى يصفي ذهنه من الشواغل.
حرص الصحابة -رضي الله عنهم- على الرفق بالحيوان.', 'لا نسبح : لا نصلي النافلة.
نحل الرحال : نضعها عن ظهر الدواب.
الرِّحال : ما يُعد للرحيل -السفر- من أمتعة ومركب وغيره.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8844', false),
(20969, 2, 208, 969, 'hadith', 'عن أبي سعيد الخدري، رضي الله عنه، قال: بينما نحن في سفر إذ جاء رجل علي راحلة له، فجعل يصرف بصره يميناً وشمالاً، فقال رسول الله صلى الله عليه وسلم : "من كان معه فضل ظهر؛ فليعد به علي من لا ظهر له، ومن كان له فضل زاد فليعد به علي من لا زاد له" فذكر من أصناف المال ما ذكره، حتي رأينا: أنه لا حق لأحد منا في فضل".', 'While we were travelling with the Messenger of Allah (ﷺ), a rider came and began to stare on the right and on the left. The Messenger of Allah (ﷺ) said, "He who has an extra mount should hand it over to one who has none, and he who possesses surplus provision, should give it to him who is without provision." He named various kinds of possessions until we began to think (realize) that none of us had any right to anything surplus..', 'أبي سعيد الخدري رضي الله عنه', 'Abu Sa''id Al-Khudri (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 969', 'Riyad as-Salihin 969', 'ریاض الصالحین 969', 'رواه مسلم', 'ذكر أبو سعيد الخدري رضي الله عنه أنهم كانوا في سفر مع النبي صلى الله عليه وسلم ، فجاء رجل على ناقة ينظر يمينا وشمالا ليجد شيئا يدفع به حاجته، فقال النبي صلى الله عليه وسلم : من كان معه زيادة في المركوب فليتصدق به على من ليس معه، ومن كان معه زيادة في الطعام فليتصدق به على من ليس معه.
يقول الراوي: حتى ظننا أنه لا حق لأحدنا فيما هو زائد عن حاجته.', 'الحض على التعاون والتكافل في الأزمات.
الأمر بالمواساة من الفاضل.
الإمام يرعى رعيته ويرشدها إلى أرشد أمرها.', 'راحلة : المركب من الإبل.
يصرف : يجول.
فضل ظهر : مركوب فاضل وزائد عن حاجته.
زاد : طعام.
فليعد به : فليتصدق به.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5906', false),
(20970, 2, 208, 970, 'hadith', 'عن جابر رضي الله عنه، عن رسول الله صلى الله عليه وسلم ، أنه أراد أن يغزو، فقال: يا معشر المهاجرين والأنصار! إن من إخوانكم قوماً، ليس لهم مال، ولا عشيرة، فليضم أحدكم إليه الرجلين، أو الثلاثة، فما لأحدنا من ظهر يحمله إلا كعقبة، يعني أحدهم. قال: فضممت إلي اثنين أو ثلاثة مالي إلا عقبة كعقبة أحدهم من جملي.', 'When the Messenger of Allah (ﷺ) made up his mind to go in an expedition, he would say to us, "O Muhajirin and the Ansar! There are among you such people who have no property and no kinsfolk. Let everyone of you take along with him two or three men. None of us had a spare animal we took rides by turn." So I took two or three men with me and I rode my camel by turn equally with them..', 'جابر رضي الله عنه', 'Jabir (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 970', 'Riyad as-Salihin 970', 'ریاض الصالحین 970', 'رواه أبو داود', 'المعنى: أن النبي صلى الله عليه وسلم أمر أصحابه رضي الله عنهم أن يَتَنَاوَب الرجلان والثلاثة على البعير الواحد حتى يكون الناس كلهم سواء.', 'الحث على المساعدة في فعل الخير كالجهاد وغيره.
استجابة الصحابة -رضي الله عنهم- لتعليمات النبي -صلى الله عليه وسلم-.
إعانة الرفيق في السفر.', 'يَغْزو : يذهب إلى قتال العدو في أرضه.
عشيرة : قبيلة تُعَاوِنُه.
يا معشر : المعشر: الجماعة.
فلْيَضُمَّ أحدكم إليه الرَّجُلَيْنِ أو الثلاثة : أي: أحدكم يَضُمُّ الاثنين، وأحدكم يَضُمُّ ثلاثة، على حَسَب الحال من اليَسَار والإِعْسار.
ظهر : الإبل التي يُحْمَل عليها وتُرْكَب.
عُقْبَة : التَّنَاوُب في ركوب البعير والمشي.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6005', false),
(20971, 2, 208, 971, 'hadith', 'وعنه قال: كان رسول الله صلى الله عليه وسلم يتخلف في المسير، فيزجي الضعيف ويردف ويدعو له.', 'The Messenger of Allah (ﷺ) used to lag behind while travelling and urge the weak to walk quickly. He used to take up someone behind him and make supplication for him..', null, 'Jabir (May Allah be pleased with him)', 'حسن', 'رياض الصالحين 971', 'Riyad as-Salihin 971', 'ریاض الصالحین 971', 'رواه أبو داود بإسناد حسن', null, null, null, 'sunnah.com', null, false, null, false),
(20972, 2, 208, 972, 'hadith', 'عن ابن عمر، رضي الله عنهما، أن رسول الله صلى الله عليه وسلم كان إذا استوى علي بعيره خارجاً إلى سفر، كبر ثلاثاً، ثم قال: "سبحان الذي سخر لنا هذا وما كنا له مقرنين، وإنا إلي ربنا لمنقلبون. اللهم إنا نسألك في سفرنا هذا البر والتقوى، ومن العمل ما ترضي. اللهم هون علينا سفرنا هذا واطو عنا بعده. اللهم أنت الصاحب في السفر والخليفة في الأهل. اللهم إني أعوذ بك من وعثاء السفر وكآبة المنظر وسوء المنقلب في الأهل والمال والولد" وإذا رجع قالهن وزاد فيهن: "آيبون تائبون عابدون لربنا حامدون" ((رواه مسلم)). معنى مقرنين : مطيقين. والوعثاء بفتح الواو وإسكان العين المهملة وبالثاء المثلثة وبالمد، وهي: الشدة. و الكآبة بالمد، وهي: تغير النفس من حزن ونحوه. والمنقلب : المرجع.', 'Whenever the Messenger of Allah (ﷺ) mounted his camel for setting out on a journey, he would recite: "Allahu Akbar (Allah is Greatest)," thrice. Then he (ﷺ) would supplicate: "Subhanal-ladhi sakh-khara lana hadha, wa ma kunna lahu muqrinin, wa inna ila Rabbina lamunqalibun. Allahumma inna nas''aluka fi safarina hadh al-birra wat-taqwa, wa minal-''amali ma tarda. Allahumma hawwin ''alaina safarana hadha, watwi ''anna bu''dahu. Allahumma Antas-Sahibu fissafari, wal-Khalifatu fil- ahli. Allahumma inni a''udhu bika min wa''ta''is-safari, wa kaabatil- manzari, wa su''il-munqalabi fil-mali wal-ahli wal-waladi (Far removed from imperfection is the One Who has made this subservient to us, for we have no power to subjugate it, and certainly to our Rubb shall we return. O Allah, we ask You during this journey of ours for righteousness, piety and such deeds as are pleasing to You. O Allah, make easy for us this journey of ours and make the distance short for us. O Allah, You are our Companion during the journey and the Guardian of the family and the property in our absence. O Allah, I seek refuge in You from the hardships of travelling, unhappiness connected with ghastly scenes and evil turns in property and family)." When he returned, he recited this supplication making addition of these words: "Ayibuna, ta''ibuna, ''abiduna, li-Rabbina hamidun (We are those who return; those who repent; those who worship and those who praise our Rubb).".', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 972', 'Riyad as-Salihin 972', 'ریاض الصالحین 972', null, 'يبين ابن عمر رضي الله عنهما في هذا الحديث أن النبي صلى الله عليه وسلم كان إذا أراد أن يسافر، وركب بعيره قال: الله أكبر ثلاث مرات، ثم قال هذا الدعاء العظيم، الذي يتضمن الكثير من المعاني الجليلة، ففيه تنزيه الله عز وجل عن الحاجة والنقص، واستشعار نعمة الله تعالى على العبد، وفيه البراءة من الحول والقوة، والإقرار بالرجوع إلى الله تعالى ، ثم سؤاله سبحانه الخير والفضل والتقوى والتوفيق للعمل الذي يحبه ويتقبله، كما أن فيه التوكل على الله تعالى وتفويض الأمور إليه، كما اشتمل على طلب الحفظ في النفس والأهل، وتهوين مشقة السفر، والاستعاذة من شروره ومضاره، كأن يرجع المسافر فيرى ما يسوؤه في أهله أو ماله أو ولده.
وذكر ابن عمر رضي الله عنهما في الرواية الأخرى أن النبي صلى الله عليه وسلم كان إذا رجع من سفره قال هذا الدعاء، وزاد قوله: (آيبون) أي نحن معشر الرفقاء راجعون (تائبون) أي من المعاصي، (عابدون) من العبادة (لربنا حامدون) شاكرون على السلامة والرجوع، وأنه كان إذا كان بمكان عالٍ، قال: الله أكبر؛ فيتواضع أمام كبرياء الله عز وجل ، ثم قال: «لا إله إلا الله وحده لا شريك له..» إقرارًا بأنه تعالى المتفرد في إلهيته وربوبيته وأسمائه وصفاته، وأنه جل وعلا الناصر لأوليائه وجنده.', 'استحباب هذا الدعاء عند ركوب المسافر.
محل هذا الدعاء هو عند الركوب لمن أراد سفرًا.
استحباب التكبير إذا صعد المسافر مرتفعًا.
ينبغي على العبد أن يشكر مولاه على ما وفقه عليه من نعم لا يحصيها إلا مسديها.
استحباب ذكر هذا الدعاء عند العودة من السفر بالزيادة المذكورة في آخره, وفيه أن الإياب بالسلامة غنيمة ونعمة ينبغي أن يجدد العبد الشكر عندها.
يستحب للعبد تجديد العهد على الطاعة والعبادة والتوبة.', 'كبّر : قال: الله أكبر.
مُقْرِنِين : مُطِيقِين.
البر : الخير والفضل.
هون علينا سفرنا : خفف عنا مشقته.
واطوِ عنا بعده : هيء لنا أسباب قطعه بزمن قصير.
الصاحب : الملازم بالعناية والحفظ.
الخليفة : المعتمد عليه والمفوض إليه.
أعوذ : أعتصم وأستجير.
وعْثَاء : شدة.
كآبة المنظر : من كل منظر يسبب الكآبة.
المنقلب : المرجع.
آيبون : راجعون.
قفل : رجع.
أوفى : ارتفع.
ثنية : مكان مرتفع.
فَدْفَد : هو بفتح الفائين بينهما دال مهملة ساكنة: الغليظ المرتفع من الأرض.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6003', false),
(20973, 2, 208, 973, 'hadith', 'عن عبد الله بن سرجس، رضي الله عنه قال: كان رسول الله صلى الله عليه وسلم إذا سافر يتعوذ من وعثاء السفر، وكآبة المنقلب، والحور بعد الكون، ودعوة المظلوم. وسوء المنظر في الأهل والمال. ((رواه مسلم)) هكذا هو في صحيح مسلم: الحور بعد الكون، بالنون، وكذا رواه الترمذي والنسائي. قال الترمذي: يروي :الكور بالراء، وكلاهما له وجه. قال العلماء: ومعناه بالنون والراء جميعاً: الرجوع من الاستقامة أو الزيادة إلي النقص. قالوا: ورواية الراء مأخوذة من تكوير العمامة، وهو لفها وجمعها، ورواية النون، من الكون، مصدراً كان يكون كوناً إذا وجد واستقر.', 'Whenever the Messenger of Allah (ﷺ) proceeded on a journey, he would seek refuge in Allah from the hardships of the journey, and against deviation after guidance, and against the supplication of the oppressed, and occurrences of unpleasant events in the family and property. He would say: "Allahumma inni a''udhu bika min wa''tha''is- safari, wa kaabatil-munqalabi, wal-hauri ba''dal-kauni, wa da''watil- mazlumi, wa su''il-manzari fil-ahli wal- mal.".', 'عبد الله بن سرجس رضي الله عنه', '''Abdullah bin Sarjis (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 973', 'Riyad as-Salihin 973', 'ریاض الصالحین 973', null, 'كان النبي صلى الله عليه وسلم يتعوذ بالله من شِدَّة السَّفَرِ، أو أن يعود من سفره حزينًا قد أصابه مكروهٌ في أهله أو ماله، ويتعوذ بالله كذلك من فساد الأحوال، ويدعو الله أن يُنَجِّيَهُ الله من دعوة المظلوم.', 'استحباب التعوُّذ بالله من هذه الأمور.
الحث على رَدِّ المظالم إلى أهلها قبل السفر.
عدم ظلم أحد في السفر: كمنع إعانة، أو نقص أجرة.', 'يتعوذ : يقول: أعوذ بالله.
وعثاء السفر : شِدَّته ومَشَقَّته.
كآبة المنظر : هو أن يعود من سفره إلى أهله كئيبًا حزينًا، أو مُبْتَلًى ذهب ماله، أو أَصَابَتْه آفةٌ في سفره، أو أن يأتي إلى أهله فيجدهم مرضى، أو يَفْقِد بعضهم، وما أشبه ذلك من المكروه.
الحور بعد الكون : يتعوذ من النقصان بعد الزيادة، أو فساد الأمور بعد صلاحها، ويروى بالراء والنون، "الكون" و"الكور".
سوء المنقلب في الأهل والمال : وهو كل ما يَسُوءُ النظر إليه، وسماعه في أهله وماله.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5937', false),
(20974, 2, 208, 974, 'hadith', 'عن علي بن ربيعة قال: شهدت علي بن أبي طالب رضي الله عنه أتي بدابة ليركبها، فلما وضع رجله في الركاب قال: بسم الله، فلما استوي علي ظهرها قال: الحمد لله الذي سخر لنا هذا، وما كنا له مقرنين، وإنا إلي ربنا لمنقلبون، ثم قال: الحمد الله، ثلاث مرات، ثم قال: الله اكبر ثلاث مرات، ثم قال: سبحانك إني ظلمت نفسي فاغفر لي فإنه لا يغفر الذنوب إلا أنت، ثم ضحك، فقيل: يا أمير المؤمنين من أي شئ ضحكت؟ قال: رأيت النبي صلى الله عليه وسلم فعل كما فعلت، ثم ضحك، فقلت: يا رسول الله من أي شئ ضحكت؟ قال: «إن ربك سبحانه يعجب من عبده إذا قال: اغفر لي ذنوبي، يعلم أنه لا يغفر الذنوب غيره» ((رواه أبو داود والترمذي وقال: حديث حسن)) وفي بعض النسخ: حديث صحيح. وهذا لفظ أبي داود', 'In my presence, a beast was brought to ''Ali bin Abu Talib (May Allah be pleased with him) for riding. When he put his foot in the stirrup, he said: "Bismillah (With the Name of Allah)." When he had settled himself on its back he recited: "Al-hamdu lillahil-ladhi sakh-khara lana hadha, wa ma kunna lahu muqrinin, wa inna ila Rabbina lamunqalibun. (All praise belongs to Allah Who has made this subservient to us, for we had not the strength to overpower it; and to our Rubb shall we return)." He then recited thrice: "Alhamdu lillah (Praise be to Allah)," and then three times: "Allahu Abkar (Allah is Greatest)." Then he said: "Subhanaka inni zalamtu nafsi faghfir li, innahu la yaghfirudh-dhunuba illa Anta (You are far removed from imperfection I have wronged myself, so forgive me, because none but You can forgive sins)." Then he smiled. It was asked: "Why have you smiled, O Amir Al-Mu''minin (Leader of the Believers)?" He replied: "I saw the Messenger of Allah (ﷺ) doing as I have done. I (i.e., Ali) asked him (the Messenger of Allah (ﷺ)) the reason for smiling. He (ﷺ) said, ''Your Rubb, Glorious is He, is pleased when His slave seeks His forgiveness. He (the slave) has firm faith that none except Allah Alone can forgive sins)''.".', 'علي بن ربيعة قال: شهدت علي بن أبي طالب رضي الله عنه', '''Ali bin Rabi''ah', 'صحيح', 'رياض الصالحين 974', 'Riyad as-Salihin 974', 'ریاض الصالحین 974', null, 'عن عليّ بن ربيعة وهو من كبار التابعين قال شهدت أي حضرت عليّ بن أبي طالب أتي بدابته، والدابة في أصل اللغة ما يدبّ على وجه الأرض، ثم خصها العرف بذات الأربع، ليركبها فلما وضع رجله في الركاب قال (بسم الله) أي أركب (فلما استوى) أي استقرّ على ظهرها قال (الحمد لله) أي على هذه النعمة العظيمة، وهي تذليل الوحش النافر وإطاعته لنا على ركوبه محفوظين من شره كما صرح به بقوله (الذي سخر) أي ذلل لنا أي لأجلنا هذا المركوب وما كنا له أي لتسخيره مقرنين أي مطيقين (وإنا إلى ربنا لمنقلبون، ثم قال) أي بعد حمده المقيد بالثناء بما أنعم عليه (الحمد لله) حمداً غير مقيد بشىء (ثلاث مرات) وفي التكرير إشعار بعظم جلال الله سبحانه وأن العبد لا يقدر الله حق قدره وهو مأمور بالدأب في طاعته حسب استطاعته، (الله أكبر ثلاث مرات) والتكرير للمبالغة في ذلك، (ثم قال سبحانك) أي أقدسك تقديساً مطلقاً، (إني ظلمت نفسي) بعدم القيام بحقك لشهود التقصير في شكر هذه النعمة العظمى ولو بغفلة أو خطرة أو نظرة (فاغفر لي) أي استر ذنوبي بعدم المؤاخذة بالعقاب عليها (إنه لا يغفر الذنوب إلا أنت) وفيه إشارة بالاعتراف بتقصيره مع إنعام الله وتكثيره (ثم ضحك فقيل) أي: فقال ابن ربيعة، وفي نسخة مصححة من «الشمائل» «فقلت» (يا أمير المؤمنين من أي شيء ضحكت) لما لم يظهر ما يتعجب منه مما ينشأ عنه الضحك استفهمه عن سببه وقدم نداءه على سؤاله كما هو الأدب في الخطاب، (قال: رأيت) أي أبصرت (النبي صنع كما صنعت) من الركوب والذكر في أماكنه (ثم ضحك فقلت: يا رسول الله من أي شيء ضحكت) (قال: إن ربك سبحانه يعجب من عبده) إضافة تشريف (إذا قال رب اغفر لي ذنوبي يعلم): أي قال ذلك عالماً غير غافل (أنه لا يغفر الذنوب غيري).', 'استحباب التسمية عند الركوب.
الإكثار من الاستغفار، وخاصة عند مقارنة التقصير بعظيم فضل الله تعالى.
استحباب هذا الذكر الذي في الحديث عند ركوب الدابة.
دعاء السفر محله عند الاستقرار في وسيلة السفر.
تأسي الصحابة بالنبي -صلى الله عليه وسلم- في أحواله وأفعاله.', 'الركاب : ما يضع الراكب رجله فيه من السرج؛ ليستعين به على الركوب.
استوى : استقر.
مقرنين : مطيقين.
لمنقلبون : لراجعون.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5271', false),
(20975, 2, 208, 975, 'hadith', 'عن جابر رضي الله عنه قال: كنا إذا صعدنا كبرنا، وإذا نزلنا سبحنا.', 'When we ascended (a height) we would proclaim: "Allahu Akbar (Allah is Greatest)," and when we descended (from the height) we would proclaim: "Subhan Allah (Allah is free from imperfection)."''.', 'جابر رضي الله عنه', 'Jabir (May Allah be pleased with him)', 'صحيحان', 'رياض الصالحين 975', 'Riyad as-Salihin 975', 'ریاض الصالحین 975', 'رواه البخاري', 'مناسبة التكبير عند الصعود إلى المكان المرتفع أن الاستعلاء والارتفاع محبوب للنفوس لما فيه من استشعار الكبرياء، فيستعظم نفسه فلذا يقول: الله أكبر، يعني: يرد نفسه إلى الاستصغار، أما كبرياء الله عز وجل ، فشرع لمن تلبس بالارتفاع أن يذكر كبرياء الله تعالى، وأنه أكبر من كل شيء، فيكبره ليشكر له ذلك، فيزيده من فضله، ومناسبة التسبيح عند الهبوط لكون المكان المنخفض محل ضيق فيشرع فيه التسبيح؛ لأنه من أسباب الفرج، كما وقع في قصة يونس -عليه السلام- حين سبح في الظلمات فنجي من الغم، والنزول أيضاً سفول ودنو وذل، فيقول: سبحان الله، يعني: أنزه الله سبحانه وتعالى عن السفول والنزول؛ لأنه سبحانه وتعالى فوق كل شيء.
كذلك الطائرة عند ارتفاعها تكبر، وعند نزولها المطار تسبح؛ لأنه لا فرق بين الصعود في الهواء، والنزول منه، أو على الأرض، والله الموفق.', 'استحباب التكبير عند الصعود، والتسبيح عند النزول في السفر.
استحباب ذكر الله -تعالى- في كل الأحوال.', 'الثنايا : جمع ثنية، وهو الطريق في الجبل.', 'sunnah.com', null, false, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6206', false),
(20976, 2, 208, 976, 'hadith', 'عن ابن عمر رضي الله عنهما قال: كان النبي صلى الله عليه وسلم وجيوشه إذا علو الثنايا كبروا، وإذا هبطوا سبحوا. ((رواه أبو داود بإسناد صحيح.', 'Whenever the Prophet (ﷺ) and his army ascended a height, they would proclaim: "Allahu Akbar (Allah is Greatest)," and when they climbed down, they would proclaim: "Subhan Allah (Allah is free from imperfection).".', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them)', null, 'رياض الصالحين 976', 'Riyad as-Salihin 976', 'ریاض الصالحین 976', null, null, null, null, 'sunnah.com', null, false, null, false),
(20977, 2, 208, 977, 'hadith', 'وعنه قال كان النبي صلى الله عليه وسلم إذا قفل من الحج أو العمرة كلما أوفى علي ثنيه أو فدفد كبر ثلاثاً، ثم قال: « لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو علي كل شئ قدير آيبون تائبون عابدون ساجدون لربنا حامدون. صدق الله وعده، ونصر عبده، وهزم الأحزاب وحده» ((متفق عليه)) وفي رواية لمسلم: إذا قفل من الجيوش أو السرايا أو الحج أو العمرة قوله: أوفى أي: ارتفع، وقوله: فدفد هو بفتح الفاءين بينهما دال مهملة ساكنة وآخره دال أخرى وهو : الغليظ المرتفع من الأرض.', 'Whenever the Prophet (ﷺ) returned from Hajj or ''Umrah and ascended a height or hill, he would recite thrice: "Allahu Akbar (Allah is Greatest)." Then he would say, "La ilaha ill-allahu wahdahu la sharika lahu, lahul- mulku, wa lahul-hamdu, wa Huwa ''ala kulli shay''in Qadeer. Ayibuna ta''ibuna ''abiduna li-Rabbina hamidun. Sadaq-Allahu wa''dahu, wa nasara ''abdahu, wa hazamal-ahzaba wahdahu .', null, 'Ibn ''Umar (May Allah be pleased with them)', null, 'رياض الصالحين 977', 'Riyad as-Salihin 977', 'ریاض الصالحین 977', null, null, null, null, 'sunnah.com', null, false, null, false),
(20978, 2, 208, 978, 'hadith', 'عن أبي هريرة رضي الله عنه أن رجلاً قال: يا رسول الله ، إني أريد أن أسافر فأوصني، قال: "عليك بتقوى الله، والتكبيرعلي كل شرف" فلما ولى الرجل قال: " اللهم اطو له البعد، وهون عليه السفر".', 'A man said: "O Messenger of Allah (ﷺ), I intend to set out on a journey, so counsel me." He (ﷺ) said, "Fear Allah, and ascending towards the raised ground, you should recite: "Allahu Akbar (Allah is Greatest)." When the man turned away, he (ﷺ) said, "O Allah! Shorten the distance for him and make the journey easy for him."', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'حسن', 'رياض الصالحين 978', 'Riyad as-Salihin 978', 'ریاض الصالحین 978', 'رواه الترمذي وقال حديث حسن', 'أراد رجل أن يسافر فقال: يا رسول الله أوصني، فأوصاه النبي صلى الله عليه وسلم أن يلتزم تقوى الله عز وجل ، وأن يكبر الله عز وجل في كل علوّ ومرتفع، فلما أدبر الرجل دعا له النبي صلى الله عليه وسلم بأن يتيسر له من النشاط، وحسن الدواب ما يصل به مستريحًا، وأن يُسَهل عليه السفر بدفع مؤذياته عنه.', 'استحباب طلب النصح من أهل العلم والفضل والتقوى عند إنشاء السفر.
وصية المسافر بتقوى الله، وتعليمه آداب السفر.
الدعاء للمسافر بما يفيده في سفره، ويبعد عنه المشقة.', 'عليك : الزم.
شرف : مكان عال.
ولى : أدبر وذهب.
اطو له : قربه له، وسهل له.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6102', false),
(20979, 2, 208, 979, 'hadith', 'عن أبي موسي الأشعري رضي الله عنه قال: كنا مع النبي صلى الله عليه وسلم في سفر، فكنا إذا أشرفنا على واد هللنا وكبرنا وارتفعت أصواتنا، فقال النبي صلى الله عليه وسلم :"يا أيها الناس أربعوا عل أنفسكم فإنكم لا تدعون أصم ولا غائباً. إنه معكم ، إنه سميع قريب" ((متفق عليه)) أربعوا" بفتح الباء الموحدة أي : أرفقوا بأنفسكم.', 'We accompanied the Prophet (ﷺ) in a journey, and when we climbed up a height, we proclaimed aloud: "La ilaha illallah (There is no true god except Allah)" and "Allahu Akbar (Allah is Greatest)." The Prophet (ﷺ) admonished us saying, "O people, take it easy. He Whom you are calling is not deaf or absent. He is with you (i.e., by His Knowledge), He is Hearing and He is Near.".', 'أبي موسي الأشعري رضي الله عنه', 'Abu Musa Al-Ash''ari (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 979', 'Riyad as-Salihin 979', 'ریاض الصالحین 979', null, 'حديث أبي موسى الأشعري رضي الله عنه أنهم كانوا مع النبي صلى الله عليه وسلم في سفر، فكانوا يهللون ويكبرون ويرفعون أصواتهم، فقال النبي صلى الله عليه وسلم : "أيها الناس اربعوا على أنفسكم" -يعني: هونوا عليها، ولا تشقوا على أنفسكم في رفع الصوت؟- "فإنكم لا تدعو أصم ولا غائباً"، إنما تدعون سميعاً مجيباً قريباً"، وهو الله عز وجل لا يحتاج أن تجهدوا أنفسكم في رفع الصوت عند التسبيح والتحميد والتكبير؛ لأن الله تعالى يسمع ويبصر وهو قريب جل وعلا، مع أنه فوق السماوات لكنه محيط بكل شيء جل وعلا .
قوله: "تدعون سميعاً بصيراً قريباً"، وهذه صيغ مبالغة لله؛ لأن له تعالى تمام الكمال من هذه الصفات، فلا يفوت سمعه أي حركة وإن خفيت، فيسمع دبيب النملة على الصفاة الصماء في ظلمة الليل، وأخفى من ذلك، كما أنه تعالى لا يحجب بصره شيء من الحوائل، فهو يسمع نغماتكم وأصوات أنفاسكم وجميع ما تتلفظون به من كلمات، ويبصر حركاتكم، وهو معكم قريب من داعيه، وهو أيضاً مع جميع خلقه باطلاعه وإحاطته، وهم في قبضته، ومع ذلك هو على عرشه عال فوق جميع مخلوقاته، ولا يخفى عليه خافية في جميع مخلوقاته مهما كانت.
والسمع والبصر والقرب صفات ثابتة لله عز وجل على الوجه اللائق به، من غير تكييف ولا تمثيل ولا تحريف ولا تأويل.', 'كراهية رفع الصوت بالذكر والدعاء.
إثبات السمع والبصر والقرب لله تعالى بلا تحريف ولا تمثيل، ولا تكييف ولا تعطيل.
تفسير معية الله، وأنها معية علم بكافة الخلق، ورعاية وقرب للمؤمنين.
إشفاق النبي -صلى الله عليه وسلم- على أصحابه.', 'أشرفنا على وادٍ : اطّلَعنا عليه من فوق، أي: أقبلنا عليه.
هللنا : قلنا: لا إله إلا الله.
اربعوا : ارفقوا.
كبر : قال الله أكبر.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6207', false),
(20980, 2, 208, 980, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال : رسول الله صلى الله عليه وسلم : " ثلاث دعوات مستجابات لا شك فيهن: دعوة المظلوم، ودعوة المسافر، ودعوة الوالد على ولده" ((رواه أبو داود، والترمذي وقال: حديث حسن)) وليس في رواية أبي داود: "على ولده"', 'The Messenger of Allah (ﷺ) said, "Three supplications are answered without doubt. The supplication of the oppressed, the supplication of the traveller, and the supplication of the parent for his son.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'حسن', 'رياض الصالحين 980', 'Riyad as-Salihin 980', 'ریاض الصالحین 980', null, 'ثلاث دعوات من ثلاثة أصناف من الداعين لا شك أن الله يستجيب لها: دعوة من مظلوم؛ حتى ولو كان المظلوم كافرًا وظُلِمَ، ثم دعا الله، فإن الله يستجيب دعاءه، ودعوة المسافر إذا دعا الله عز وجل حال سفره ودعوة الوالد؛ سواء كان الأب أو الأم؛ وسواء دعا لولده أو عليه.', 'استحباب إكثار الدعاء في السفر؛ لأنه مظنة الإجابة.
التحذير من الظلم، ودعوة المظلوم مستجابة ولو كان كافراً.
التحذير من عقوق الوالدين، واتقاء دعوة الوالد فإنها لا ترد.', 'لا شك فيهن : أي في استجابتهن من الله -عز وجل-.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5909', false),
(20981, 2, 208, 981, 'hadith', 'عن أبي موسي الأشعري رضي الله عنه أن رسول الله كان إذا خاف قوماً قال: « اللهم إنا نجعلك في نحورهم ، ونعوذ بك من شرورهم».', 'When the Messenger of Allah (ﷺ), feared mischief from a people, he would supplicate: "Allahumma inna naj''aluka fi nuhurihim, wa na''udhu bika min shururihim (O Allah! We ask You to face them, and seek Your Protection against their evil.".', 'أبي موسي الأشعري رضي الله عنه', 'Abu Musa Al-Ashari (May Allah be pleased with him)', 'إسناده صحيح', 'رياض الصالحين 981', 'Riyad as-Salihin 981', 'ریاض الصالحین 981', 'رواه أبو داود، والنسائي بإسناد صحيح', 'قوله: "اللهم إنا نجعلك في نحورهم"، أي: أمامهم تدفعهم عنا وتمنعنا منهم، وخص النحر لأنه أسرع وأقوى في الدفع والتمكن من المدفوع، والعدو إنما يستقبل بنحره عن المناهضة للقتال أو للتفاؤل بنحرهم أو قتلهم، "ونعوذ بك من شرورهم"، ففي هذه الحال يكفيك الله شرهم، والمراد نسألك أن تصد صدورهم، وتدفع شرورهم، وتكفينا أمورهم، وتحول بيننا وبينهم.
كلمتان يسيرتان إذا قالهما الإنسان بصدق وإخلاص، فإن الله تعالى يدافع عنه، والله الموفق.', 'الدعاء بهذا الدعاء عند توقع شر ظالم أو غيره.
الالتجاء إلى الله تعالى، والاعتصام به عند كل نازلة.', 'نحورهم : جمع نحر، وهو أسفل الرقبة وأعلى الصدر بين الترقوتين.
نعوذ : أي نلتجئ إلى الله ونستنصر به.', 'sunnah.com', null, false, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5473', false),
(20982, 2, 208, 982, 'hadith', '-عن خولة بنت حكيم رضي الله عنها قالت: سمعت رسول الله صلى الله عليه وسلم يقول: «من نزل منزلاً ثم قال: أعوذ بكلمات الله التامات من شر ما خلق: لم يضره شيء حتي يرتحل من منزله ذلك».', 'I heard the Messenger of Allah (ﷺ) saying, "Whosoever alights somewhere and says: ''A''udhu bikalimat-illahit-tammati min sharri ma khalaqa (I seek refuge with the Perfect Words of Allah from the evil of what He has created),'' nothing will harm him until he leaves that place.".', null, 'Khaulah bint Hakim (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 982', 'Riyad as-Salihin 982', 'ریاض الصالحین 982', 'رواه مسلم', 'يُرْشِدُ النبيُّ صلى الله عليه وسلم أُمَّتَه إلى الاعتصام والالتجاء النافع الذي يَندفِعُ به كلُّ محذورٍ يخافُه الإنسان عندما يَنزِل مكانًا من الأرض، سواء كان في سفر أو نزهة أو غير ذلك: بأنْ يعتصمَ ويلتجئَ بكلمات الله الكاملة في فضلها وبركتها ونفعها، السالمة من كل عيب ونقص، من شر كل مخلوق فيه شر، فيَأْمَنَ في منزلِه ذلك ما دام مُقيمًا فيه مِن كلِّ ما يؤذي.', 'الاستعاذة عبادة، وهي ما كانت بالله تعالى أو بأسمائه وصفاته.
جواز الاستعاذة بكلام الله، لأنه صفة من صفاته سبحانه، بخلاف الاستعاذة بأي مخلوق فهي شرك.
فضيلة هذا الدعاء وبركته.
التَّحَصُّن بالأذكار سببٌ لحماية العبد من الشرور.
إبطال الاستعاذة بغير الله من الجن والسَّحَرة والدجَّالين وغيرهم.
مشروعية هذا الدعاء لمَن نزل مكانًا في الحضر أو السَّفر.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5932', false),
(20983, 2, 208, 983, 'hadith', 'عن ابن عمر رضي الله عنهما قال: كان رسول الله صلى الله عليه وسلم إذا سافر فأقبل الليل قال: « يا أرض ، ربي وربك الله، أعوذ بالله من شرك وشر ما فيك ، وشر ما خلق فيك، وشر ما يدب عليك أعوذ بالله من شر أسد وأسود، ومن الحية والعقرب، ومن ساكن البلد، ومن والد وما ولد» ((رواه أبو داود)) والأسود : الشخص، قال الخطابي: و ساكن البلد : هم الجن الذين هم سكان الأرض . قال: والبلد من الأرض: ما كان مأوى الحيوان، وإن لم يكن فيه بناء ومنازل . قال: ويحتمل أن المراد بالوالد : إبليس وماولد : الشياطين', 'Whenever the Messenger of Allah (ﷺ) set out on a journey, he would say by nightfall: "Ya ardu, Rabbi wa Rabbuk-illahu, a''udhu billahi min sharriki wa sharri ma fiki, wa sharri ma khuliqa fiki, wa sharri ma yadibbu ''alaiki; a''udhu billahi min sharri asadin wa aswadin, wa minal-hayyati wal-''aqrabi, wa min sakinil-baladi, wa min walidin wa ma walad .', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them)', null, 'رياض الصالحين 983', 'Riyad as-Salihin 983', 'ریاض الصالحین 983', null, null, null, null, 'sunnah.com', null, false, null, false),
(20984, 2, 208, 984, 'hadith', 'عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «السفر قطعة من العذاب، يمنع أحدكم طعامه، وشرابه ونومه، فإذا قضى أحدكم نهمته من سفره، فليعجل إلى أهله» ((متفق عليه)) . نهمته : مقصوده', 'The Messenger of Allah (ﷺ) said, "Travelling is a torment because it deprives a traveller of his food, drink and sleep. So when one of you has accomplished his purpose of journey, let him return home quickly.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 984', 'Riyad as-Salihin 984', 'ریاض الصالحین 984', null, 'يبين النبي صلى الله عليه وسلم في هذا الحديث أنّ (السفر قطعة من العذاب) أي: جزء منه، والمراد بالعذاب: الألم الناشئ عن المشقة؛ لما يحصل في الركوب والمشي من ترك المألوف.
وأنّ: (يمنع أحدكم نومه وطعامه وشرابه) أي: يمنعه كمالها ولذيذها؛ لما فيه من المشقة والتعب ومقاساة الحر والبرد والخوف ومفارقة الأهل والأصحاب وخشونة العيش، لأن المسافر مشغول البال، ولا يأكل ويشرب كطعامه وشربه العادي في أيامه العادية، وكذلك في النوم، فإذا كان كذلك، فليرجع الإنسان إلى الراحة إلى أهله وبلده؛ ليقوم على أهله بالرعاية والتأديب وغير ذلك.', 'السفر قطعة من العذاب لما فيه من المشقة، وفراق المألوف، والأحباب.
كراهة التغرب عن الأهل لغير حاجة.
الإقامة عند الأهل خير من السفر.', 'السفر قطعة من العذاب : لما فيه من المشقة مع فراق الأحباب.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5404', false),
(20985, 2, 208, 985, 'hadith', 'عن جابر رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «إذا أطال أحدكم الغيبة فلا يطرقن أهله ليلاً» وفي رواية أن رسول الله صلى الله عليه وسلم نهى أن يطرق الرجل أهله ليلاً.', 'The Messenger of Allah (ﷺ) said, "When one of you stays away (from his family) for a long period of time, let him not surprise his family by night."In another narration, Jabir (May Allah be pleased with him) said: The Messenger of Allah (ﷺ) prohibited us from coming back to our family at night..', 'جابر رضي الله عنه', 'Jabir (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 985', 'Riyad as-Salihin 985', 'ریاض الصالحین 985', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20986, 2, 208, 986, 'hadith', 'عن أنس رضي الله عنه قال: كان رسول الله صلى الله عليه وسلم لا يطرق أهله ليلاً، وكان يأتيهم غدوة أو عشية. ((متفق عليه)) الطروق :المجيء في الليل.', 'The Messenger of Allah (ﷺ) would not come (back) to his family by night. He used to come in the morning or in the evening (before dark)..', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him)', null, 'رياض الصالحين 986', 'Riyad as-Salihin 986', 'ریاض الصالحین 986', null, null, null, null, 'sunnah.com', null, false, null, false),
(20987, 2, 208, 987, 'hadith', 'عن أنس رضي الله عنه قال: أقبلنا مع النبي صلى الله عليه وسلم ، حتي إذ كنا بظهر المدينة، قال: «آيبون، تائبون ، عابدون ، لربنا حامدون» فلم يزل يقول ذلك حتي قدمنا المدينة.', 'We returned with the Prophet (ﷺ) from a journey; and when we entered the suburbs of Al- Madinah, he (ﷺ) said: "Ayibuna, ta''ibuna, ''abiduna, li-Rabbina hamidun (We are returning in safety, turning to our Rubb, worshipping Him and praising Him)." He (ﷺ) continued repeating these words till we entered Al-Madinah..', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 987', 'Riyad as-Salihin 987', 'ریاض الصالحین 987', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(20988, 2, 208, 988, 'hadith', 'عن كعب بن مالك رضي الله عنه أن رسول الله صلى الله عليه وسلم كان إذا قدم من سفر بدأ بالمسجد فركع فيه ركعتين.', 'Whenever the Messenger of Allah (ﷺ) returned from a journey, he would proceed straight to the mosque and perform two Rak''ah of (optional) prayer..', 'كعب بن مالك رضي الله عنه', 'Ka''b bin Malik (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 988', 'Riyad as-Salihin 988', 'ریاض الصالحین 988', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20989, 2, 208, 989, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «لا يحل لامرأة تؤمن بالله واليوم الآخر تسافر مسيرة يوم وليلة إلا مع ذي محرم عليها».', 'The Messenger of Allah (ﷺ) said, "It is not permissible for a woman who believes in Allah and the Last Day to make a journey of one day and night unless she is accompanied by a Mahram (husband or any other relative to whom she is prohibited to marry).".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 989', 'Riyad as-Salihin 989', 'ریاض الصالحین 989', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20990, 2, 208, 990, 'hadith', 'عن ابن عباس رضي الله عنهما أنه سمع النبي صلى الله عليه وسلم يقول: "لا يخلون رجل بامرأة إلا ومعها ذو محرم، ولا تسافر المرأة إلا مع ذي محرم" فقال له رجل: يا رسول الله إن امرأتي خرجت حاجّة، وإني اكتتبت في غزوة كذا وكذا؟ قال: "انطلق فحج مع امرأتك".', 'The Prophet (ﷺ) said, "No man must not be alone with a woman except in the presence of her (Mahram). No woman should travel except in company of a (Mahram)." A man said: "O Messenger of Allah! I have been enrolled for such and such expedition, and my wife left for Hajj." He (ﷺ) said to him, "Go and perform Hajj with your wife.".', 'ابن عباس رضي الله عنهما', 'Ibn ''Abbas (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 990', 'Riyad as-Salihin 990', 'ریاض الصالحین 990', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20991, 2, 209, 991, 'hadith', 'عن أبي أمامة رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: « اقرءوا القرآن فإنه يأتي يوم القيامة شفيعًا لأصحابه».', 'I heard the Messenger of Allah (ﷺ) saying, "Read the Qur''an, for it will come as an intercessor for its reciters on the Day of Resurrection.".', 'أبي أمامة رضي الله عنه', 'Abu Umamah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 991', 'Riyad as-Salihin 991', 'ریاض الصالحین 991', 'رواه مسلم', 'حث النبي صلى الله عليه وسلم أمته على قراءة القرآن؛ فإنه إذا كان يوم القيامة جعل الله عز وجل ثواب هذا القرآن شيئًا قائمًا بنفسه يأتي يوم القيامة يشفع لقارئيه والمشتغلين به المتمسكين بأمره ونهيه.', 'الحض على قراءة القرآن، والإكثار منها، وعدم الانشغال عنه.
فضل قراءة القرآن.', 'شفيعًا : شافعًا طالبًا المغفرة لأصحابه.
أصحابه : القارئون له العاملون بأحكامه وهديه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5383', false),
(20992, 2, 209, 992, 'hadith', 'عن النواس بن سمعان رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: «يؤتى يوم القيامة بالقرآن وأهله الذين كانو يعملون به في الدنيا تقدمه سورة البقرة وآل عمران تحاجان عن صاحبهما ».', 'I heard the Messenger of Allah (ﷺ) saying, "The Qur''an and its people who applied it, will be brought on the Day of Resurrection preceded with Surat Al-Baqarah and Surat Al-''Imran arguing on behalf of those who applied them.".', 'النواس بن سمعان رضي الله عنه', 'An-Nawwas bin Sam''an (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 992', 'Riyad as-Salihin 992', 'ریاض الصالحین 992', 'رواه مسلم', 'حديث النواس بن سمعان رضي الله عنه أن النبي صلى الله عليه وسلم قال: "يؤتي يوم القيامة بالقرآن، وأهله الذين كانوا يعملون به في الدنيا تقدمه سورة البقرة وآل عمران تحاجان عن صاحبهما"، ولكن الرسول صلى الله عليه وسلم قيد في هذا الحديث قراءة القرآن بالعمل به؛ لأن الذين يقرءون القرآن ينقسمون إلى قسمين؛ قسم: لا يعمل به، فلا يؤمنون بأخباره، ولا يعملون بأحكامه هؤلاء يكون القرآن حجة عليهم، وقسم آخر: يؤمنون بأخباره ويصدقون بها، ويعملون بأحكامه، فهؤلاء يكون القرآن حجة لهم يحاج عنهم يوم القيامة، وفي هذا دليل على أن أهم شيء في القرآن العمل به، ويؤيد هذا قوله تعالى: "كتاب أنزلناه إليك مبارك ليدبروا آياته، وليذكر أولوا الألباب"، "ليدبروا آياته"، أي: يتفهمون معانيها، "وليذكر أولوا الألباب"، يعني: ويعملون بها، وإنما أخر العمل عن التدبر؛ لأنه لا يمكن العمل بلا تدبر إذا إن التدبر يحصل به العلم والعمل فرع عن العلم، فالمهم أن هذا هو الفائدة من إنزال القرآن أن يتلى ويعمل به يؤمن بأخباره يعمل بأحكامه يمتثل أمره يجتنب نهيه، فإذا كان يوم القيامة فإنه يحاج عن أصحابه.', 'فضل تلاوة القرآن، وتلاوة سورتي البقرة وآل عمران.
القرآن شفيع لأصحابه يوم القيامة.
العلم يقتضي العمل، وإلا كان حجة على صاحبه يوم القيامة.', 'تقدمه : تتقدمه.
تحاجان : تجادلان.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6828', false),
(20993, 2, 209, 993, 'hadith', '- وعن عثمان بن عفان رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «خيركم من تعلم القرآن وعلمه».', 'The Messenger of Allah (ﷺ) said, "The best amongst you is the one who learns the Qur''an and teaches it.".', null, '''Uthman bin ''Affan (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 993', 'Riyad as-Salihin 993', 'ریاض الصالحین 993', 'رواه البخاري', null, null, null, 'sunnah.com', null, false, null, false),
(20994, 2, 209, 994, 'hadith', 'عن عائشة رضي الله عنها قالت: قال رسول الله صلى الله عليه وسلم : «الذي يقرأ القرآن وهو ماهر به مع السفرة الكرام البررة، والذي يقرأ القرآن ويتتعتع فيه وهو عليه شاق له أجران».', 'The Messenger of Allah (ﷺ) said, "The one who is proficient in the recitation of the Qur''an will be with the honourable and obedient scribes (angels) and he who recites the Qur''an and finds it difficult to recite, doing his best to recite it in the best way possible, will have two rewards.".', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 994', 'Riyad as-Salihin 994', 'ریاض الصالحین 994', 'متفق عليه', 'أخبر النبي صلى الله عليه وسلم أن الذي يقرأ القرآن، وهو جيّد الحفظ مُتقن له، وماهر وحاذق بقراءته، له من الثواب في الآخرة أن تكون منزلته مع الملائكة السفرة الكرام البررة، وأن الذي يقرأ القرآن ويتتعتع فيه ويتردد في تلاوته؛ لِضَعف حفظه وهو مع ذلك يتعاهده، وهو عليه شديد وشاقٌّ فله أجران؛ أجر بالقراءة وأجر للمشقة وتردده في تلاوته.', 'الحث على حفظ القرآن وإتقانه وكثرة تلاوته لنوال الأجر والثواب، وبيان علو منزلة من فعل ذلك.
قال القاضي: وليس معناه أن الذي يتتعتع عليه له من الأجر أكثر من الماهر به، بل الماهر أفضل وأكثر أجرًا؛ لأنه مع السفرة وله أجور كثيرة، ولم يذكر هذه المنزلة لغيره، وكيف يلحق به من لم يعتنِ بكتاب الله تعالى وحفظه وإتقانه وكثرة تلاوته ودرايته كاعتنائه حتى مَهَرَ فيه.
قال ابن باز: الذي يقرأ القرآن وهو ماهِرٌ فيه، يُجيد قراءَته، ويحفظه جيدًا مع السَّفَرة الكرام البَرَرة، يعني: إذا كان يتلوه قولًا وعملًا، لا مجرّد التلاوة فقط، يُجيد تلاوته، ويعمل به، فهو قائم به لفظًا ومعنًى.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/10113', false),
(20995, 2, 209, 995, 'hadith', 'عن أبي موسى الأشعري رضي الله عنه: قال رسول الله صلى الله عليه وسلم : «مثل المؤمن الذي يقرأ القرآن مثل الأترجة: ريحها طيب، وطعمها طيب، ومثل المؤمن الذي لا يقرأ القرآن كمثل التمرة: لا ريح لها وطعمها حلو، ومثل المنافق الذي يقرأ القرآن كمثل الريحانة: ريحها طيب وطعمها مر، ومثل المنافق الذي لايقرأ القرآن كمثل الحنظلة: ليس له ريح وطعمها مر».', 'The Messenger of Allah (ﷺ) said, "The believer who recites the Qur''an is like a citron whose fragrance is sweet and whose taste is delicious. A believer who does not recite the Qur''an is like a date-fruit which has no fragrance but has a sweet taste. The hypocrite who recites the Qur''an is like basil whose fragrance is so sweet, but its taste is bitter. The hypocrite who does not recite the Qur''an is like a colocynth which has no fragrance and its taste is bitter.".', 'أبي موسى الأشعري رضي الله عنه', 'Abu Musa Al-Ash''ari (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 995', 'Riyad as-Salihin 995', 'ریاض الصالحین 995', 'متفق عليه', 'بَيَّنَ النبيُّ صلى الله عليه وسلم أقسامَ الناسِ في قراءة القرآن والانتفاع به: 

فالقسم الأول: المؤمن الذي يقرأ القرآنَ وينتفع به، فهو كَثَمَرَةِ الأترجة، طَيِّبُ الطعم والرائحة وحَسَن اللون، ومنافعه كثيرة، فهو يعمل بما يقرأ، وينفع عبادَ الله. 

الثاني: المُؤمن الذي لا يقرأ القرآن، فهو كالتَّمْرَة، طعمُها حُلْو، ولا ريح لها، فقلبُه مُشتملٌ على الإيمان كاشتمال التمرة على الحلاوة في طعمها وباطنها، وعدم ظهور ريح لها يَشُمُّه الناسُ؛ لعدم ظهور قراءة منه يرتاح الناس بسماعها. 

الثالث: المنافق الذي يقرأ القرآن، فهو كالريحانة، لها رائحة طيبة وطعمها مُرّ، حيث لم يُصلِح قلبَه بالإيمان، ولم يعملْ بالقرآن، ويَظهرُ أمامَ الناس أنه مؤمن، فريحُها الطيب يُشبه قراءتَه، وطعمُها المُرُّ يُشبه كُفرَه. 

الرابع: المنافق الذي لا يقرأ القرآن، فهو كالحَنْظَلَة، حيثُ إنها لا رائحة لها، ومُرٌّ مذاقُها، فانعدام ريحِها أَشبَهَ انعدامَ ريحِه؛ لعدم قراءته، ومَرَارةُ طعمِها شَبيهٌ بمرارة كفرِه، فباطنُه خَالٍ من الإيمان، وظاهره لا نفع فيه، بل هو ضارٌّ.', 'بيان فضيلة حامل القرآن العامل به.
مِن طُرُق التعليم ضَرْبُ المَثَل؛ لتقريب الفهم.
ينبغي للمسلم أن يكونَ له وِرْدٌ مُسْتَمِرٌّ مِن كتاب الله تعالى.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6258', false),
(20996, 2, 209, 996, 'hadith', 'عن عمر بن الخطاب رضي الله عنه: أن النبي صلى الله عليه وسلم قال : « إن الله يرفع بهذا الكتاب أقوامًا ويضع به آخرين».', 'The Prophet (ﷺ) said, "Verily, Allah elevates some people with this Qur''an and abases others.".', 'عمر بن الخطاب رضي الله عنه', '''Umar bin Al-Khattab (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 996', 'Riyad as-Salihin 996', 'ریاض الصالحین 996', 'رواه مسلم', 'عن عمر بن الخطاب رضي الله عنه أن النبي صلى الله عليه وسلم قال: "إن الله يرفع بهذا الكتاب أقواماً ويضع به آخرين"، يعني: معناه أن هذا القرآن يأخذه أناس يتلونه ويقرءونه، فمنهم من يرفعه الله به في الدنيا والآخرة، ومنهم من يضعهم الله به في الدنيا والآخرة، من عمل بهذا القرآن تصديقاً بأخباره، وتنفيذاً لأوامره واجتناباً لنواهيه، واهتداء بهديه، وتخلقاً بما جاء به من أخلاق -وكلها أخلاق فاضلة-، فإن الله تعالى يرفعه به في الدنيا والآخرة، وذلك لأن هذا القرآن هو أصل العلم ومنبع العلم وكل العلم، وقد قال الله تعالى: (يرفع الله الذين آمنوا منكم والذين أوتوا العلم درجات)، أما في الآخرة فيرفع الله به أقواماً في جنات النعيم.
وأما الذين يضعهم الله به فقوم يقرءونه ويحسنون قراءته، لكنهم يستكبرون عنه -والعياذ بالله- لا يصدقون بأخباره، ولا يعملون بأحكامه يستكبرون عنه عملاً، ويجحدونه خبراً إذا جاءهم شيء من القرآن كقصص الأنبياء السابقين أو غيرهم أو عن اليوم الآخر أو ما أشبه ذلك صاروا والعياذ بالله يشككون في ذلك ولا يؤمنون، وربما يصل بهم الحال إلى الجحد مع أنهم يقرءون القرآن، وفي الأحكام يستكبرون لا يأتمرون بأمره ولا ينتهون بنهيه، هؤلاء يضعهم الله في الدنيا والآخرة، والعياذ بالله.', 'الحث على الاهتمام بكتاب الله تلاوة وحفظاً وفهماً وعملاً.
العلم يرفع صاحبه في الدنيا والآخرة، ما لا يرفعه المال ولا الملك ولا غيرهما.
الأمة المسلمة عزها وشرفها بتمسكها بدينها، والقيام بحق كتابها.', 'يضع : يخفض.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/10119', false),
(20997, 2, 209, 997, 'hadith', 'عن ابن عمر رضي الله عنهما: عن النبي صلى الله عليه وسلم قال :« لا حسد إلا في اثنتين: رجل آتاه الله القرآن، فهو يقوم به آناء الليل وآناء النهار، ورجل آتاه الله مالا، فهو ينفقه آناء الليل وآناء النهارِ» ((متفق عليه)). (1) .', 'The Prophet (ﷺ) said: "Envy is justified in regard to two types of persons only: a man whom Allah has given knowledge of the Qur''an, and so he recites it during the night and during the day; and a man whom Allah has given wealth and so he spends from it during the night and during the day.".', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 997', 'Riyad as-Salihin 997', 'ریاض الصالحین 997', null, 'يُشير النبي صلى الله عليه وسلم هنا إلى أن الحَسَدَ أنواع مختلفة فمنه حسد مَذْمُوم محرم شرعًا، وهو أن يتمنى المرء زوال النعمة عن أخيه، وحسد مباح وهو أن يرى نعمة دنيوية عند غيره فيتمنى لنفسه مثلها، وحسد محمود مستحب شرعًا، وهو أن يرى نعمة دينية عند غيره فيتمناها لنفسه. وهو ما عناه النبي صلى الله عليه وسلم بقوله: "لا حَسَدَ إلا في اثنتين" أي أن الحسد تختلف أنواعه وأحكامه حسب اختلاف أنواعه ولا يكون محمودًا مستحبًا شرعيًا إلا في أمرين: 
الأمر الأول: أن يكون هناك رجل غني تقي، أعطاه الله مالا حلالا، فينفقه في سبيل الله تعالى، فيتمنى أن يكون مثله، ويَغْبِطَه على هذه النعمة. 
الأمر الثاني: أن يكون هناك رجل عالم، أعطاه الله علما نافعا يعمل به، ويعلمه لغيره، ويحكم به بين الناس، فيتمنى أن يكون مثله.', 'الحَسَدُ داء خطير يجب الابتعاد عنه والحذر منه.
حسد الغِبْطَة محمود إذا كان في وجوه الخير.
فضل الغني الذي لا يبخل بما آتاه الله .
الواجب شكر المُنْعِم على ما أنعم به على العبد وذلك بأن يضعها العبد في موضعها.
استحباب الإنفاق وبذل المال والخروج عنه بالكلية في وجوه الخير ما لم يؤد إلى حرمان الورثة أو سؤال الناس ونحو ذلك مما حَرَّمَه الشرع.
فضل العلم بأحكام الدين وتعليم الناس ودعوتهم إلى التفقه في الدين.', 'الحسد : الغبطة ، وهي: أن يتمنى مثله.
سلطه : مكنه الله من إنفاقه في وجوه الخير.
هلكته : وجوه إنفاقه ومجالات صرفه.
في الحق : في أنواع البر ونواحي الخير.
حكمة : وضع كل شيء في موضعه.
يقضي بها : يحكم ويفتي بين الناس بمقتضاها.
آناء : الآناء: الساعات', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3772', false),
(20998, 2, 209, 998, 'hadith', 'عن البراء بن عازب رضي الله عنهما قال: كان رجل يقرأ سورة الكهف، وعنده فرس مربوط بشطنين فتغشته سحابة فجعلت تدنو، وجعل فرسه ينفر منها. فلما أصبح أتى النبي صلى الله عليه وسلم ، فذكر له ذلك فقال : « تلك السكينة تنزلت للقرآن».', 'A man was reciting Surat Al-Kahf, and a horse was tied with two ropes beside him. As he was reciting, a cloud overshadowed him, and as it began to come nearer and nearer, the horse began to trample voilently. The man came to the Messenger of Allah (ﷺ) in the morning and mentioned the incident to him. He (ﷺ) said, "That was tranquillity which descended as a result of the recitation of the Qur''an."', 'البراء بن عازب رضي الله عنهما', 'Al-Bara'' bin ''Azib (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 998', 'Riyad as-Salihin 998', 'ریاض الصالحین 998', 'متفق عليه', 'ذكر البراء بن عازب رضي الله عنهما قصة عجيبة حصلت زمن النبي صلى الله عليه وسلم ، حيث كان رجل يقرأ سورة الكهف وإلى جانبه فرس مربوطة بحبل، فغطَّاه شيء مثل الظلة؛ وجعل يقترب منه ويقترب، ففزعت الفرس مما رأته ونفرت، فلما أصبح الرجل أتى النبيَّ صلى الله عليه وسلم فذكر ذلك، فبيَّن له النبي صلى الله عليه وسلم أن تلك السكينة تنزلت عند قراءة القرآن، كرامة لهذا الصحابي الذي كان يقرأ، وشهادة من الله تعالى أن كلامه حق.
والرجل هو أُسيد بن حُضير رضي الله عنه .', 'إن الله يُري بعض عباده بعض آياته، ليزدادوا إيماناً مع إيمانهم.
السكينة تدنو من العباد كلما كثرت قراءة القرآن.
جواز رؤية آحاد الأمة الملائكة.
فضيلة استماع القرآن.', 'فتغشته : غطته وعلته.
ينفر منها : يفر ويذهب.
السكينة : الطمأنينة والرحمة.
بشطنين : جمع شطن: بفتح الشين المعجمة والطاء المهملة: الحبل.
تَدْنُو : أي تقرب وتنزل.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6178', false),
(20999, 2, 209, 999, 'hadith', 'عن ابن مسعود رضي الله عنه قال : قال رسول الله صلى الله عليه وسلم : «من قرأ حرفًا من كتاب الله فله حسنة، والحسنة بعشر أمثالها لا أقول: ألم حرف، ولكن ألف حرف، ولام حرف، وميم حرف».', 'The Messenger of Allah (ﷺ) said, "Whoever recites a letter from the Book of Allah, he will be credited with a good deed, and a good deed gets a ten-fold reward. I do not say that Alif-Lam-Mim is one letter, but Alif is a letter, Lam is a letter and Mim is a letter.".', 'ابن مسعود رضي الله عنه', 'Ibn Mas''ud (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 999', 'Riyad as-Salihin 999', 'ریاض الصالحین 999', 'راوه الترمذي وقال: حديث حسن صحيح', null, null, null, 'sunnah.com', null, false, null, false),
(21000, 2, 209, 1000, 'hadith', 'عن ابن عباس رضي الله عنهما قال : قال رسول الله صلى الله عليه وسلم : «إن الذي ليس في جوفه شيء من القرآن كالبيت الخرب».', 'The Messenger of Allah (ﷺ) said, "He who does not memorize any part from the Qur''an he is like the ruined house.''''', 'ابن عباس رضي الله عنهما', 'Ibn `Abbas (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1000', 'Riyad as-Salihin 1000', 'ریاض الصالحین 1000', 'رواه الترمذي وقال: حديث حسن صحيح', null, null, null, 'sunnah.com', null, false, null, false)
