insert into hadith (id, collection_id, chapter_id, number_in_book, kind, arabic, translation_en, narrator_ar, narrator_en, grade_ar, reference_ar, reference_en, reference_ur, full_ref_ar, explanation_ar, benefits_ar, word_meanings_ar, source, source_ref, daily_ok, review_note, deleted) values
(21001, 2, 209, 1001, 'hadith', 'عن عبد الله بن عمرو بن العاص رضي الله عنهماعن النبي صلى الله عليه وسلم قال: «يقال لصاحب القرآن: اقرأ وارتقِ ورتل كما كنت ترتل في الدنيا، فإن منزلتك عند آخر آية تقرؤها».', 'The Prophet (ﷺ) said, "The one who was devoted to the Qur''an will be told on the Day of Resurrection: ''Recite and ascend (in ranks) as you used to recite when you were in the world. Your rank will be at the last Ayah you recite."''.', 'عبد الله بن عمرو بن العاص رضي الله عنهما', '''Abdullah bin ''Amr bin Al-''As (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1001', 'Riyad as-Salihin 1001', 'ریاض الصالحین 1001', 'رواه أبو داود والترمذي وقال: حديث حسن صحيح', null, null, null, 'sunnah.com', null, false, null, false),
(21002, 2, 209, 1002, 'hadith', 'عن أبي موسى رضي الله عنه عن النبي صلى الله عليه وسلم قال «تعاهدوا هذا القرآن فوالذي نفس محمد بيده لهو أشد تفلتًا من الإبل في عقلها».', 'The Prophet (ﷺ) said, "Read the Qur''an regularly. By the One in Whose Hand Muhammad''s soul is, it escapes from memory faster than a camel does from its tying ropes.".', 'أبي موسى رضي الله عنه', 'Abu Musa Al-Ash''ari (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1002', 'Riyad as-Salihin 1002', 'ریاض الصالحین 1002', 'متفق عله', 'أَمَرَ النبيُّ صلى الله عليه وسلم بمُعاهَدةِ القرآنِ والمواظبةِ على تلاوتِهِ كي لا ينساه بعد أن كان حافظًا له في صدرِهِ، وأَكَّدَ ذلك بِحَلِفِهِ صلى الله عليه وسلم على أنَّ القرآنَ أشدُّ تَخَلُّصًا وذهابًا من الصدور مِن الإبل المَعقولة وهي المشدودة بحبلٍ في وسط الذراع، إنْ تَعاهدَها الإنسانُ أَمْسَكَها وإنْ أَطْلَقَها ذهبتْ وضاعتْ.', 'إنْ واظَبَ حافظُ القرآنِ على تلاوتِه مرَّة بعد مرَّة بقي محفوظًا في قلبه، وإلا ذهبَ عنه ونسيَه.
من فوائد تعاهُدِ القرآن: الأجر والثواب، ورفعة الدرجات يوم القيامة.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5907', false),
(21003, 2, 209, 1003, 'hadith', 'عن ابن عمر رضي الله عنهما أن رسول الله صلى الله عليه وسلم قال: «إنما مثل صاحب القرآن كمثل الإبل المعقلة، إن عاهد عليها أمسكها، وإن أطلقها، ذهبت» متفق عليه.', 'The Messenger of Allah (ﷺ) said: "The parable of one who knows the Qur''an by heart is as the parable of an owner of hobbled camel. If he remains vigilant, he will retain it; and if he neglects it, it will go away.".', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1003', 'Riyad as-Salihin 1003', 'ریاض الصالحین 1003', null, 'شَبَّهَ النبيُّ صلى الله عليه وسلم من دَرَس القرآن وأَلِفَ تلاوته -سواء نظرًا من المصحف أو عن ظهر قلب- بصاحب الإبل المعقلة بالحبل الذي يُشَدُّ به رُكْبة البعير، إن عاهد عليها استمر إمساكه لها، وإن أطلق عُقُلَها ذهبت وانفلتت، فإذا قام صاحب القرآن فقرأه ذَكَره، وإذا لم يقم به نسيه؛ فما زال التعاهد موجودًا فالحفظ موجود.', 'الحث على تعاهد القرآن وتلاوته، والحذر من تعريضه للنسيان.
المداومة على قراءة القرآن  يذلُّ له لسانه ويسهل عليه قراءته، فإذا هَجَره ثقلت عليه القراءة وشقّت عليه.
قال القاضي: ومعنى "صاحب القرآن" أي: الذي ألِفه، والمصاحبة: المُؤالَفة، ومنه: فلان صاحب فلان، وأصحاب الجنة وأصحاب النار.
من أساليب الدعوة ضرب الأمثال.
قال ابن حجر: وخص الإبل بالذكر؛ لأنها أشد الحيوان الإنسي نفورًا، وفي تحصيلها بعد استمكان نفورها صعوبة.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5658', false),
(21004, 2, 209, 1004, 'hadith', 'عن أبي هريرة رضي الله عنه قال :سمعت رسول الله صلى الله عليه وسلم يقول: «ما أذن الله لشيء ما أذن لنبي حسن الصوت يتغنى بالقرآن يجهر به ».', 'I heard the Messenger of Allah (ﷺ) saying, "Allah does not listen so attentively to anything as He listens to the recitation of the Qur''an by a Prophet who recites well with a melodious and audible voice.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (may Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1004', 'Riyad as-Salihin 1004', 'ریاض الصالحین 1004', 'متفق عليه', 'في هذا الحديث الحث على تحسين الصوت عند قراءة القرآن في الصلاة وغيرها، بحيث أنه يحسّن به صوته جاهرًا به، مترنمًا على طريق التحزن، مستغنيًا به عن غيره من الأخبار، طالبًا به غنى النفس، راجيًا به غنى اليد، والمقصود بالتغني في الحديث هو التحسين وليس جعله مثل إيقاعات الأغاني الموسيقية.', 'استحباب تحسين الصوت بالقراءة القرآن وترتيلها، وهو متفق عليه.
يعطي الله سبحانه الأجر العظيم على حسن الصوت في تلاوة القرآن.', 'يتغنى بالقرآن : يحسن صوته بالقرآن.
أَذِن : اسْتَمَعَ، وَهُوَ يدل كذلك على الرِّضَا والقَبولِ.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6218', false),
(21005, 2, 209, 1005, 'hadith', 'عن أبي موسى الأشعري رضي الله عنه أن رسول الله صلى الله عليه وسلم قال له :" لقد أتيت مزمارا من مزامير آل داود " ((متفق عليه)) . وفي روايه لمسلم : أن رسول الله صلى الله عليه وسلم قال له : " لو رأيتني وأنا أستمع لقراءتك البارحة".', 'The Messenger of Allah (ﷺ) said to him, "You have been given a Mizmar (sweet melodious voice) out of the Mazamir of Prophet Dawud (David).".
And in a version narrated by Muslim "If you would have seen me, as I was listening to your recitation last night."', 'أبي موسى الأشعري رضي الله عنه', 'Abu Musa Al-Ash''ari (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1005', 'Riyad as-Salihin 1005', 'ریاض الصالحین 1005', null, 'عن أبي موسى الأشعري -رضي اللّه عنه- أن رسول اللّه صلى الله عليه وسلم قال له لما سمع قراءته الجميلة المرتلة: (لقد أوتيت مزمارا من مزامير آل داود)، وقوله: "لقد أوتيت"، أي: أعطيت، : "مزماراً من مزامير آل داود"، أي داود نفسه، وداود عنده صوت حسن جميل رفيع، حتى قال الله تعالى : "يا جبال أوّبي معه والطير، وألنّا له الحديد" [سبأ: 10]، وآل فلان قد يطلق على الشخص نفسه؛ لأن أحداً منهم لم يُعطَ من حسن الصوت ما أعطيه داود.', '4- مكانة أبي موسى الأشعري  -رضي الله عنه- وحسن صوته ومدح النبي -صلى الله عليه وسلم- له.
1- استحباب تحسين الصوت بالقرآن؛ لأن ذلك يزيد القرآن حلاوة ونفوذاً إلى قلوب السامعين.
5-  فضل نبي الله داود -عليه السلام-.
2- استحباب الاستماع إلى القرآن والإنصات له.
3- الجهر بالعبادة قد يكون في بعض المواضع أفضل من الإسرار.', 'مزماراً : المراد: الصوت الحسن، وأصله الآلة، وأطلق اسمه على الصوت للمشابهة.
آل داود : المراد: داود النبي -عليه السلام- من أنبياء بني إسرائيل.
البارحة : أقرب ليلة مضت.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6212', false),
(21006, 2, 209, 1006, 'hadith', 'عن البراء بن عازب رضي الله عنهما قال :سمعت النبي صلى الله عليه وسلم قرأ في العشاء بالتين والزيتون، فما سمعت أحدًا أحسن صوتا منه.', 'I heard the Prophet (ﷺ) reciting Surat Wat-Teen Waz-Zaitun (Chapter 95) during the ''Isha'' prayer. I have never heard anyone reciting it in a more beautiful voice than his..', 'البراء بن عازب رضي الله عنهما', 'Al-Bara'' bin ''Azib (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1006', 'Riyad as-Salihin 1006', 'ریاض الصالحین 1006', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21007, 2, 209, 1007, 'hadith', 'عن أبي لبابة بشير بن عبد المنذر رضي الله عنه قال، أن النبي صلى الله عليه وسلم قال: من لم يتغنَ بالقرآن فليس منا ".', 'The Prophet (ﷺ) said, "He who does not recite the Qur''an in a pleasant tone is not of us.".', 'أبي لبابة بشير بن عبد المنذر رضي الله عنه', 'Abu Lubabah Bashir bin ''Abdul-Mundhir (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1007', 'Riyad as-Salihin 1007', 'ریاض الصالحین 1007', 'رواه أبو داود بإسناد جيد', 'حث النبي صلى الله عليه وسلم في هذا الحديث على التغني بالقرآن، وهذه الكلمة لها معنيان؛ الأول: من لم يتغن به، أي: من لم يحسن صوته بالقرآن فليس من أهل هدينا وطريقتنا، والمعنى الثاني: من لم يستغن به عن غيره بحيث يطلب الهدى من سواه فليس منا، ولا شك أن من طلب الهدى من غير القرآن أضله الله والعياذ بالله، فيدل الحديث على أنه ينبغي للإنسان أن يحسن صوته بالقرآن، وأن يستغنى به عن غيره.', 'الحث على تحسين الصوت بالقرآن، دون تمطيط أو تلحين يخرجه إلى حد الغناء المذموم, وأن يستغنى به عن غيره.
من لم يتغن بالقرآن فليس من أهل سنة النبي -صلى الله عليه وسلم- وهديه.', 'فليس منا : ليس من أهل هدينا وطريقتنا.
يتغن : يُحَسِّنُ صَوْتَهُ بِالقُرْآنِ.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6276', false),
(21008, 2, 209, 1008, 'hadith', 'عن ابن مسعود رضي الله عنه قال: قال لي النبي صلى الله عليه وسلم :"اقرأ علي القرآن "، فقلت : يا رسول الله، أقرأ عليك وعليك أنزل ؟! قال : "إني أحب أن أسمعه من غيري" فقرأت عليه سورة النساء حتى جئت إلى هذه الآية : {فكيف إذا جئنا من كل أمة بشهيد وجئنا بك على هؤلاء شهيدا} قال: "حسبك الآن" فالتفت إليه، فإذا عيناه تذرفان.', 'The Prophet (ﷺ) said to me, "Recite the Qur''an to me." I said: "O Messenger of Allah! Shall I recite it to you when it was revealed to you?" He (ﷺ) said, "I like to hear it from others." Then I began to recite Surat An-Nisa''. When I reached the Ayah: ''How will it be when We shall bring a witness from every people and bring you as a witness against them?'' (Having heard it) he said, "Enough! Enough!" When I looked at him, I found his eyes were overflowing with tears..', 'ابن مسعود رضي الله عنه', 'Ibn Mas''ud (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1008', 'Riyad as-Salihin 1008', 'ریاض الصالحین 1008', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21009, 2, 209, 1009, 'hadith', 'عن أبي سعيد رافع بن المعلى رضي الله عنه قال : قال لي رسول الله صلى الله عليه وسلم :"ألا أعلمك أعظم سورة في القرآن قبل أن تخرج من المسجد؟ فأخذ بيدي ، فلما أردنا أن نخرج قلت : يا رسول الله إنك قلت لأعلمنك أعظم سورة في القرآن ؟ قال: "الحمد لله رب العالمين هي السبع المثاني، والقرآن العظيم الذي أوتيته ".', 'The Messenger of Allah (ﷺ) said, "Shall I teach you the greatest Surah in the Qur''an before you leave the mosque?" Then he (ﷺ), took me by the hand, and when we were about to step out, I reminded him of his promise to teach me the greatest Surah in the Qur''an. He (ﷺ) said, "It is ''Alhamdu lillahi Rabbil ''Alamin (i.e., Surat Al-Fatihah) which is As-Sab'' Al-Mathani (i.e., the seven oft- repeated Ayat) and the Great Qur''an which is given to me.".', 'أبي سعيد رافع بن المعلى رضي الله عنه', 'Abu Sa''id Ar-Rafi'' bin Al-Mu''alla (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1009', 'Riyad as-Salihin 1009', 'ریاض الصالحین 1009', 'رواه البخاري', 'عن أبي سعيد رافع بن المعلى رضي الله عنه قال: قال لي رسول اللّه صلى الله عليه وسلم : "ألا" أتى بها لتنبيه المخاطب لما يلقى إليه بعدها، قوله: "أعلمك أعظم سورة في القرآن قبل أن تخرج من المسجد"، وإنما قال له ذلك، ولم يعلمه بها ابتداء؛ ليكون أدعى إلى تفريغ ذهنه لتلقيها وإقباله عليها بكليته، قوله: "فأخذ بيدي"، أي: بعد أن قال ذلك ومشينا، قوله: "فلما أردنا أن نخرج قلت: يا رسول اللّه إنك قلت: لأعلمنك أعظم سورة في القرآن"، قوله: "قال: الحمد للّه ربّ العالمين"، أي: سورة الفاتحة، وإنما كانت أعظم سورة لأنها جمعت جميع مقاصد القرآن، ولذا سميت بأم القرآن. ثم أشار إلى ما تميزت به الفاتحة عن غيرها من بقية السور حتى صارت أعظم منها، بقوله: "هي السبع المثاني"، أي: المسماة به، جمع مثناة من التثنية لأنها تثنى في الصلاة في كل ركعة، أو لأنها تثنى بسورة أخرى، أو سميت بذلك لاشتمالها على قسمين: ثناء ودعاء، أو لما اجتمع فيها من فصاحة المباني وبلاغة المعاني، أو لأنها تثنى على مرور الزمان وتتكرر فلا تنقطع وتدرس فلا تندرس، أو لأن فوائدها تتجدد حالاً فحالاً إذ لا منتهى لها، أو جمع مثناه من الثناء لاشتمالها على ما هو ثناء على اللّه تعالى، فكأنها تثنى عليه بأسمائه الحسنى وصفاته، أو من الثنايا لأن اللّه استثناها لهذه الأمة، وغير ذلك، قوله: "والقرآن العظيم"، أي: وهي المسماة بذلك أيضاً، قوله: "الذي أوتيته"، أي: أعطيته، وتسميتها بالقرآن العظيم لجمعها سائر ما يتعلق بالموجودات دنيا وأخرى وأحكاماً وعقائد.', 'سورة الفاتحة أعظم سورة في كتاب الله -تبارك وتعالى-.
تفضيل بعض القرآن على بعض بما جاء عن رسول الله -صلى الله عليه وسلم- في ذلك.
حرص الرسول -صلى الله عليه وسلم- على تعليم الناس الخير، وبيانه لهم.
أن الفاتحة سبع آيات.', 'الحمد لله رب العالمين : سورة الفاتحة.
السبع المثاني : السبع الآيات التي تثنى أي تقرأ في كل ركعة من الصلاة.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/10112', false),
(21010, 2, 209, 1010, 'hadith', 'عن أبي سعيد الخدري رضي الله عنه أن رسول الله صلى الله عليه وسلم قال في:{ قل هو الله أحد}:" والذي نفسي بيده، إنها لتعدل ثلث القرآن". وفي رواية: أن رسول الله صلى الله عليه وسلم قال لأصحابه:" أيعجز أحدكم أن يقرأ بثلث القرآن في ليلة" فشق ذلك عليهم، وقالوا: أينا يطيق ذلك يارسول الله: فقال :" {قل هو الله أحد} ثلث القرآن.".', 'The Messenger of Allah (ﷺ) said, "By Him in Whose Hand my soul is, it is equivalent to one-third of the Qur''an."According to another version, he (ﷺ) said to his Companions, "Is anyone of you incapable of reciting one-third of the Qur''an in one night?" They considered it burdensome and said: "O Messenger of Allah, which of us can afford to do that?" He (ﷺ) said, "Surat Al-Ikhlas .', 'أبي سعيد الخدري رضي الله عنه', 'Abu Sa''id Al-Khudri (May Allah be pleased with him) reported about Surat Al-Ikhlas (Chapter 112):', 'صحيح', 'رياض الصالحين 1010', 'Riyad as-Salihin 1010', 'ریاض الصالحین 1010', 'رواه البخاري', null, null, null, 'sunnah.com', null, false, null, false),
(21011, 2, 209, 1011, 'hadith', 'وعنه أن رجل سمع رجلاً يقرأ:{قل هو الله احد} يرددها فلما أصبح جاء إلى رسول الله صلى الله عليه وسلم، فذكر ذلك له وكان الرجل يتقالها فقال رسول الله صلى الله عليه وسلم : « والذي نفسي بيده، إنها لتعدل ثلث القرآن».', 'A man heard another reciting Surat Al-Ikhlas repeatedly. The next morning he came to the Messenger of Allah (ﷺ) and informed him about it as if he considered it to be of little reward. On that the Messenger of Allah (ﷺ) said, "By Him in Whose Hand my soul is, this Surah is equal to one-third of the Qur''an.".', null, 'Abu Sa''id Al-Khudri (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1011', 'Riyad as-Salihin 1011', 'ریاض الصالحین 1011', 'رواه البخاري', 'ذكر أبو سعيد الخدري رضي الله عنه أن رجلًا سمع آخر يقرأ سورة: {قُلْ هُوَ اللَّهُ أَحَدٌ} يرددها كل الليل لا يزيد عليها، فلما أصبح جاء إلى رسول الله صلى الله عليه وسلم فذكر ذلك له، وكأن السائل يرى أنها قليلة، فقال صلى الله عليه وسلم يمينًا على معنى التأكيد: والذي نفسي بيده إنها تساوي ثلث القرآن.', 'فضل سورة الإخلاص، وأنها تعدِل ثلث القرآن.
جواز القراءة في قيام الليل ولو بيسير الآيات وترديدها، وعدم تقليل ذلك.
قال المازري: قيل: معناه: أن القرآن على ثلاثة أنحاء؛ قصص وأحكام وصفات لله تعالى، و{قُلْ هُوَ اللَّهُ أَحَدٌ} متمحضة -يعني لصفات الله-، فهي ثلث، وجزء من ثلاثة أجزاء، وقيل: معناه: أن ثواب قراءتها يضاعف بقدر ثواب قراءة ثلث القرآن بغير تضعيف.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65261', false),
(21012, 2, 209, 1012, 'hadith', 'عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال في:{ قل هو الله أحد} «إنها تعدل ثلث القرآن».', 'The Messenger of Allah (ﷺ) said, "Surat Ikhlas is equivalent to one-third of the Qur''an.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1012', 'Riyad as-Salihin 1012', 'ریاض الصالحین 1012', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21013, 2, 209, 1013, 'hadith', 'عن أنس رضي الله عنه أن رجلا قال: يارسول الله إني أحب هذه السورة "قل هو الله أحد":"إن حبها أدخلك الجنة".', 'A man said: "O Messenger of Allah! I love Surat-Al-Ikhlas .', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1013', 'Riyad as-Salihin 1013', 'ریاض الصالحین 1013', 'رواه الترمذي وقال: حديث حسن- رواه البخاري في صحيحه تعليقًا', null, null, null, 'sunnah.com', null, false, null, false),
(21014, 2, 209, 1014, 'hadith', 'عن عقبة بن عامر رضي الله عنه أن رسول الله صلى الله عليه وسلم قال : « ألم ترَ آيات أنزلت هذه الليلة لم يرَ مثلهن قط ؟ قل أعوذ برب الفلق، وقل أعوذ برب الناس ».', 'The Messenger of Allah (ﷺ) said: "Do you not know that last night certain Ayat were revealed the like of which there is no precedence. They are: ''Say: I seek refuge with (Allah) the Rubb of the daybreak'' (Surah 113), and ''Say: I seek refuge with (Allah) the Rubb of mankind'' (Surah 114).".', 'عقبة بن عامر رضي الله عنه', '''Uqbah bin ''Amir (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1014', 'Riyad as-Salihin 1014', 'ریاض الصالحین 1014', 'رواه مسلم', 'عن عقبة بن عامر رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : "ألم تر"، أي: ألم تعلم، وهو خطاب خاص للراوي، والمراد به عام للجميع، وهي كلمة تعجب، وأشار إلى سبب التعجب، بقوله: "لم ير مثلهن"، أي: في بابها وهو التعوذ، وقوله: "قط"، لتأكيد النفي، قوله: "قل أعوذ برب الفلق"، و "قل أعوذ برب الناس"، أي: لم توجد آيات سورة كلهن تعويذ للقارىء من شر الأشرار مثل هاتين السورتين، ما تعوذ بهما متعوذ عن إيمان وصدق إلا أعاذه الله عز وجل، فالحاصل أن الإنسان ينبغي أن يتعوذ بهاتين السورتين.', 'فضل سورتي الفلق والناس، وأنهن من خير ما أنزل على رسول الله -صلى الله عليه وسلم-.
اقتصار النبي –صلى الله عليه وسلم- عليهما في التعويذ؛ لاشتمالهما على الجوامع في المستعاذ به والمستعاذ منه.', 'ألم تر : استفهام يفيد تعجبًا.
لم يُر مثلهن : لم يوجد آيات مثلهن، ومما اختصتا به أنه لا توجد سورة كلها تعويذ غير هاتين السورتين.
الفلق : الصبح.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/10114', false),
(21015, 2, 209, 1015, 'hadith', 'عن أبي سعيد الخدري رضي الله عنه قال : كان رسول الله صلى الله عليه وسلم يتعوذ من الجان، وعين الإنسان، حتى نزلت المعوذتان، فلما نزلتا، أخذ بهما وترك ما سواهما.', 'The Messenger of Allah (ﷺ) used to seek protection against the evil of jinn and the evil eyes till Surat Al-Falaq and Surat An-Nas were revealed. After they were revealed, he took to them for seeking Allah''s protection and left everything besides them..', 'أبي سعيد الخدري رضي الله عنه', 'Abu Sa''id Al-Khudri (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1015', 'Riyad as-Salihin 1015', 'ریاض الصالحین 1015', 'رواه الترمذي وقال :حديث حسن', 'يفيد الحديث أن رسول الله صلى الله عليه وسلم كان يعتصم بالله تعالى من شر الجان وعين الإنسان الحاسد، عن طريق الأدعية والأذكار، بأن يقول: أعوذ بالله من الجان وعين الإنسان، حتى نزلت المعوذتان، فلما نزلتا أخذ بهما في التعوذ غالبًا، وترك ما سواهما من التعاويذ والرقيات؛ لاشتمالهما على الجوامع في المستعاذ به، والمستعاذ منه.', 'جواز التعوذ من الجان والعين بكل دعاء مشروع.
تحصن العبد بالمعوذتين، وأنهما تغنيان عما سواهما من الرقى.
إثبات أن العين حق.
فضل المُعَوِّذَتَين لاشتمالهما على الجوامع في المستعاذ به، والمستعاذ منه.
العين سبب في حصول الضرر كالمرض بإذن الله -تعالى-، ولا تعارض بين تشخيص الأطباء لمرض ما بكونه التهابًا أو ورمًا أو غير ذلك وبين كون ذلك المرض سببه العين، فالوصف بالالتهاب والأورام تشخيص لحالة المريض والعين سبب لذلك المرض، ولذلك يكون العلاج من الأمرين: بالرقية الشرعية وأخذ شيء من أثر العائن وبالأدوية الطبية.', 'عين الإنسان : نظرة الإنسان إلى الغير بالحسد، فيمرض بسببها، فيقال: أصابه بالعين.
المعوذتان : أي: "قل أعوذ برب الفلق"، و "قل أعوذ برب الناس".
يتعوذ : يعتصم.
أخذ بهما : أي في التعوذ لعمومهما لذلك وغيره.
وترك ما سواهما : أي من التعاويذ.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6184', false),
(21016, 2, 209, 1016, 'hadith', 'عن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال :« من القرآن سورة ثلاثون آية شفعت لرجل حتى غفرت له ،وهي: تبارك الذي بيده الملك ».', 'I heard the Messenger of Allah (ﷺ) saying, "There is a Surah in the Qur''an which contains thirty Ayat which kept interceding for a man until his sins are forgiven. This Surah is ''Blessed is He in Whose Hand is the dominion.'' (Surat Al-Mulk 67).".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'حسن', 'رياض الصالحين 1016', 'Riyad as-Salihin 1016', 'ریاض الصالحین 1016', 'رواه أبو داود والترمذي وقال :" حديث حسن ، وفي رواية أبي داود: "تشفع "', 'يبين رسول اللّه –صلى الله عليه وسلم- أن هناك سورة من القرآن تتكون من ثلاثين آية شفعت لرجل حتى غفر الله له، حيث كان يقرؤها ويعتني بها، فلما مات شفعت له حتى دفع عنه عذابه، وأبهم ذكرها في بداية الحديث، ثم بينها في آخره؛ ليكون أوقع في شرفها وفخامتها، وأبلغ في المواظبة على قراءتها.', 'بيان فضل سورة الملك، والحض على حفظها وتلاوتها.
كتاب الله يشفع لمن يقرأه، ويعمل به.
إثبات عذاب القبر.', 'شفعت : من الشفاعة، وهي السؤال في التجاوز عن الذنوب والجرائم، وتكون فيما يتعلق بأمور الدنيا والآخرة.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6260', false),
(21017, 2, 209, 1017, 'hadith', 'عن أبي مسعود البدري رضي الله عنه عن النبي صلى الله عليه وسلم قال : « من قرأ بالآيتين من آخر سورة البقرة في ليلة كفتاه ».', 'I heard the Prophet (ﷺ) saying, "He who recites the two Ayat at the end of Surat Al-Baqarah at night, they will suffice him.".', 'أبي مسعود البدري رضي الله عنه', 'Abu Mas''ud Al-Badri (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1017', 'Riyad as-Salihin 1017', 'ریاض الصالحین 1017', 'متفق عليه', 'أَخْبَرَ النبيُّ صلى الله عليه وسلم أنَّ مَن قَرأ الآيتين الأخيرتين من سورة البقرة في الليل فإنَّ الله يكفيه الشر والمكروه، وقيل: تكفيه عن قيام الليل، وقيل: تكفيه عن سائر الأوراد، وقيل: إنهما أقلُّ ما يجزىء من قراءة القرآن في قيام الليل، وقيل غير ذلك، ولعل كلَّ ما ذُكِرَ صحيح يَشملُه اللفظ.', 'بيان فضل أواخر سورة البقرة، وهي من قوله تعالى : (آمن الرسول ...)  إلى آخر السورة.
أواخر سورة البقرة تدفع عن صاحبها السوءَ والشرَّ والشيطانَ إذا قرأها من الليل.
الليلة تبدأ بغروب الشمس، وتنتهي بطلوع الفجر.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6274', false),
(21018, 2, 209, 1018, 'hadith', 'عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال : « لا تجعلوا بيوتكم مقابر، إن الشيطان ينفر من البيت الذي تقرأ فيه سورة البقرة».', 'I heard the Messenger of Allah (ﷺ) saying: "Do not turn your houses into graveyards. Satan runs away from the house in which Surat Al-Baqarah is recited.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1018', 'Riyad as-Salihin 1018', 'ریاض الصالحین 1018', 'رواه مسلم', 'يَنْهَى النبيُّ صلى الله عليه وسلم عن تعطيلِ البيوت من الصلاة فتكون كالمقابر التي لا يصلى فيها.

ثم أخبر صلى الله عليه وسلم أنَّ الشيطانَ يَنْفِرُ من البيت الذي تُقرأُ فيه سورةُ البقرة.', 'استحباب الإكثار من العبادات وصلاة النافلة في البيوت.
لا يجوز الصلاة في المقابر؛ لأنها وسيلة من وسائل الشرك والغلو في أصحابها، ما عدا صلاة الجنازة.
النهي عن الصلاة عند القبور قد تَقَرَّر عند الصحابة، ولذلك نهى النبي صلى الله عليه وسلم أن تُجعل البيوت مثل المقابر لا يُصلّى فيها.', 'ينفر: يصد ويعرض إعراضاً بالغاً.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6208', false),
(21019, 2, 209, 1019, 'hadith', 'عن أبي بن كعب رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم :" يا أبا المنذر أتدري أي آية من كتاب الله معك أعظم ؟ قلت: الله لا إله إلا هو الحي القيوم، فضرب في صدري وقال :" ليهنك العلم أبا المنذر".', 'The Messenger of Allah (ﷺ) said: "Abu Mundhir! Do you know which Ayah in Allah''s Book is the greatest?" I replied: "It is ''Allah la ilaha illa Huwal-Haiyul-Qayum (Allah! none has the right to be worshipped but He, the Ever Living...)''." (2:256) Thereupon he (ﷺ) patted me in the chest and said, "Rejoice by this knowledge, O Abu Mundhir!".', 'أبي بن كعب رضي الله عنه', 'Ubayy bin Ka''b (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1019', 'Riyad as-Salihin 1019', 'ریاض الصالحین 1019', 'رواه مسلم', 'سأل النبيُّ صلى الله عليه وسلم أبيَّ بن كعب عن أعظم آية في كتاب الله، 
فتردد في الإجابة، ثم قال: هي آية الكرسي: {الله لا إله إلا هو الحي القيوم}، 
فأيَّده النبي صلى الله عليه وسلم، وضرب النبي على صدره إشارة إلى امتلائه علمًا وحكمة، ودعا له بأن يَسعدَ بهذا العلم وأن يُيَسَّر له.', 'منقبة عظيمة لأبي بن كعب رضي الله عنه.
آية الكرسي أعظم آية في كتاب الله تعالى، فينبغي حفظها وتدبر معانيها والعمل بها.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65059', false),
(21020, 2, 209, 1020, 'hadith', 'عن أبي هريرة رضي الله عنه قال: وكلني رسول الله صلى الله عليه وسلم بحفظ زكاة رمضان، فأتاني آتٍ، فجعل يحثو من الطعام، فأخذته فقلت: لأرفعنك إلى رسول الله صلى الله عليه وسلم قال: إني محتاج، وعلي عيال، وبي حاجة شديدة، فخليت عنه، فأصبحت، فقال رسول الله صلى الله عليه وسلم :" يا أبا هريرة، ما فعل أسيرك البارحة؟" قلت: يا رسول الله شكا حاجة وعيالا، فرحمته، فخليت سبيله. فقال: " أما إنه قد كذبك وسيعود" فعرفت أنه سيعود لقول رسول الله صلى الله عليه وسلم فرصدته، فجاء يحثو من الطعام، فقلت: لأرفعنك إلى رسول الله صلى الله عليه وسلم، قال: دعني فإني محتاج، وعلي عيال لا أعود، فرحمته فخليت سبيله، فأصبحت فقال لي رسول الله صلى الله عليه وسلم: "يا أبا هريرة، ما فعل أسيرك البارحة؟" قلت: يا رسول الله شكا حاجة وعيالا فرحمته، فخليت سبيله، فقال: "إنه قد كذبك وسيعود" فرصدته الثالثة. فجاء يحثو من الطعام، فأخذته، فقلت: لأرفعنك إلى رسول الله صلى الله عليه وسلم، وهذا آخر ثلاث أنك تزعم أنك لا تعود، ثم تعود! فقال: دعني فإني أعلمك كلمات ينفعك الله بها، قلت: ما هن؟ قال: إذا أويت إلى فراشك فاقرأ آية الكرسي، فإنه لن يزال عليك من الله حافظ، ولا يقربك شيطان حتى تصبح، فخليت سبيله فأصبحت، فقال لي رسول الله صلى الله عليه وسلم: "ما فعل أسيرك البارحة؟ " قلت: يا رسول الله زعم أنه يعلمني كلمات ينفعني الله بها، فخليت سبيله. قال: "ما هي؟" قلت: قال لي: إذا أويت إلى فراشك فاقرأ آية الكرسي من أولها حتى تختم الآية: {الله لا إله إلا هو الحي القيوم} وقال لي: لا يزال عليك من الله حافظ، ولن يقربك شيطان حتى تصبح، فقال النبي صلى الله عليه وسلم: "أما إنه قد صدقك وهو كذوب، تعلم من تخاطب منذ ثلاث يا أبا هريرة " ؟ قلت: لا، قال: "ذاك شيطان".', 'The Messenger of Allah (ﷺ) put me in charge of charity of Ramadan (Sadaqat-ul- Fitr). Somebody came to me and began to take away some food-stuff. I caught him and said, "I must take you to the Messenger of Allah (ﷺ)." He said, "I am a needy man with a large family, and so I have a pressing need." I let him go. When I saw the Messenger of Allah (ﷺ) next morning, he asked me, "O Abu Hurairah! What did your captive do last night?" I said, "O Messenger of Allah! He complained of a pressing need and a big family. I felt pity for him so I let him go." He (ﷺ) said, "He told you a lie and he will return." I was sure, according to the saying of the Messenger of Allah (ﷺ) that he would return. I waited for him. He sneaked up again and began to steal food-stuff from the Sadaqah. I caught him and said; "I must take you to the Messenger of Allah (ﷺ)." He said, "Let go of me, I am a needy man. I have to bear the expenses of a big family. I will not come back." So I took pity on him and let him go. I went at dawn to the Messenger of Allah (ﷺ) who asked me, "O Abu Hurairah! What did your captive do last night?" I replied, "O Messenger of Allah! He complained of a pressing want and the burden of a big family. I took pity on him and so I let him go." He (ﷺ) said, "He told you a lie and he will return." (That man) came again to steal the food-stuff. I arrested him and said, "I must take you to the Messenger of Allah (ﷺ), and this is the last of three times. You promised that you would not come again but you did." He said, "Let go of me, I shall teach you some words with which Allah may benefit you." I asked, "What are those words?" He replied, "When you go to bed, recite Ayat-ul- Kursi (2:255) for there will be a guardian appointed over you from Allah, and Satan will not be able to approach you till morning." So I let him go. Next morning the Messenger of Allah (ﷺ) asked me, "What did your prisoner do last night." I answered, "He promised to teach me some words which he claimed will benefit me before Allah. So I let him go." The Messenger of Allah (ﷺ) asked, "What are those words that he taught you?" I said, "He told me: ''When you go to bed, recite Ayat- ul-Kursi from the beginning to the end i.e.,.', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1020', 'Riyad as-Salihin 1020', 'ریاض الصالحین 1020', 'رواه البخاري', null, null, null, 'sunnah.com', null, false, null, false),
(21021, 2, 209, 1021, 'hadith', 'عن أبي الدرداء رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: "من حفظ عشر آيات من أول سورة الكهف، عصم من الدجال" وفي رواية: "من آخر سورة الكهف".', 'The Messenger of Allah (ﷺ) said: "Whoever commits to memory the first ten Ayat of the Surat Al-Kahf, will be protected from (the trial of) Ad-Dajjal (Antichrist).".In another narration, the Messenger of Allah (ﷺ) said: "(Whoever commits to memory) the last ten Ayat of Surat Al-Kahf, he will be protected from (the trial of) Ad-Dajjal (Antichrist)."', 'أبي الدرداء رضي الله عنه', 'Abud-Darda'' (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1021', 'Riyad as-Salihin 1021', 'ریاض الصالحین 1021', 'رواهما مسلم', 'أَخْبَرَ النبيُّ صلى الله عليه وسلم أنَّ مَن حَفِظ عَشْرَ آيات عن ظَهْرِ قَلْبٍ مِن أول سورة الكهف عُصِم ووُقِي وحُفِظ من فتنةِ المسيح الدجال الذي يَخرج آخر الزمان ويَدَّعي الألوهية، وفتنته أعظم فتنة تكون على الأرض منذ خُلِقَ آدم إلى قيام الساعة؛ لما أمكنه الله عز وجل من بعض الخَوَارِق التي يَفتن بها من تبعه، وذلك لأن أول سورة الكهف فيها من العجائب والآيات ما هو أعظم مما يَفتن الدَّجالُ فيه الناس، فمَن تَدَبَّرَها لم يفتتن بالدجال.

وفي رواية: عشر آيات من آخر السورة من قوله تعالى : {أفحسب الذين كفروا أن يتخذوا…}.', 'بيان فضل سورة الكهف، وأن فَوَاتِحَها أو خَوَاتِمَها تَعصم من فتنة الدجال.
الإخبار عن أمر الدجال، وبيان ما يعصم منه.
الحث على حفظ سورة الكهف كاملةً، فإن عجز فليحفظ العشر الآيات الأولى والأخيرة.
قال القرطبي في سَبَبُ ذلك: قيل: لِمَا في قصة أصحاب الكهف من العجائب والآيات، فمَن وَقَفَ عليها لم يَسْتَغرِب أَمْرَ الدجال ولم يَهُلْه ذلك فلم يفتتن به، وقيل: لقوله تعالى: {لينذر بأسًا شديدًا من لدنه} تمسكًا بتخصيص البأس بالشدة واللَّدُنِّيّة، وهو مناسب لما يكون من الدجال من دعوى الإلهية واستيلائه وعظم فتنته، ولذلك عظَّم صلى الله عليه وسلم أمرَه وحَذَّر عنه وتعوذ من فتنته، فيكون معنى الحديث: أن من قرأ هذه الآيات وتدبرها ووقف على معناها حَذِرَه فأمن منه.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6265', false),
(21022, 2, 209, 1022, 'hadith', '-وعن ابن عباس رضي الله عنهما قال: بينما جبريل عليه السلام قاعد عند النبي صلى الله عليه وسلم سمع نقيضًا من فوقه، فرفع رأسه فقال: «هذا باب من السماء فتح اليوم ولم يفتح قط إلا اليوم، فنزل منه ملك فقال: هذا ملك نزل إلى الأرض لم ينزل قط إلا اليوم، فسلم وقال: أبشر بنورين أوتيتهما، لم يؤتهما نبي قبلك: فاتحة الكتاب، وخواتيم سورة البقرة، لن تقرأ بحرف منها إلا أعطيته» ((رواه مسلم)). النقيض: الصوت.', 'While Jibril (Gabriel) was sitting with the Messenger of Allah (ﷺ), he heard a sound above him. He lifted his head, and said: "This is a gate which has been opened in heaven today. It was never opened before." Then an angel descended through it, he said: "This is an angel who has come down to earth. He never came down before." He sent greetings and said: "Rejoice with two lights given to you. Such lights were not given to any Prophet before you. These (lights) are: Fatihah-til-Kitab (Surat Al-Fatihah), and the concluding Ayat of Surat Al-Baqarah. You will never recite a word from them without being given the blessings it contain s.".', null, 'Ibn ''Abbas (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1022', 'Riyad as-Salihin 1022', 'ریاض الصالحین 1022', null, 'كان المَلك جبريل عليه السلام قاعدًا عند النبي صلى الله عليه وسلم، فسمع صوتًا من السماء كصوت الباب إذا فُتح، فرفع جبريل رأسه وبصره إلى السماء، ثم أخبر النبي صلى الله عليه وسلم أن هذا باب من السماء فُتح اليوم، ولم يَسبق أنْ فُتح قط إلا هذا اليوم، فنزل منه ملك من الملائكة إلى الأرض، لم ينزل من قبل إلا هذا اليوم، فسلّم الملك على النبي صلى الله عليه وسلم، وقال له: 

أبشر بنورين أعطيتهما لم يعطهما نبي قبلك؛ وهما: سورة الفاتحة، وآخر آيتين من سورة البقرة. 

ثم قال الملك: لن يقرأ أحد بحرف منهما إلا آتاه الله تعالى ما فيهما من الخير والدعاء والطلب.', 'فضل سورة الفاتحة وخواتيم سورة البقرة، والحث على قراءتهما والعمل بما فيهما.
السماء لها أبواب ينزل منها الأمر الإلهي، ولا تفتح إلا بأمر الله تعالى.
بيان كرامة النبي صلى الله عليه وسلم على ربه، حيث أكرمه بما لم يكرم الأنبياء الذين قبله، فأعطاه هذين النورين.
من أساليب الدعوة إلى الله البشارة بالخير.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5775', false),
(21023, 2, 209, 1023, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «ما اجتمع قوم في بيت من بيوت الله يتلون كتاب الله، ويتدارسونه بينهم، إلا نزلت عليهم السكينة، وغشيتهم الرحمة، وحفتهم الملائكة، وذكرهم الله فيمن عنده».', 'The Messenger of Allah (ﷺ) said, "Any group of people that assemble in one of the Houses of Allah to recite the Book of Allah, learning and teaching it, tranquility will descend upon them, mercy will engulf them, angels will surround them and Allah will make mention of them to those (the angels) in His proximity.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1023', 'Riyad as-Salihin 1023', 'ریاض الصالحین 1023', 'رواه مسلم', 'بَيَّنَ النبيُّ صلى الله عليه وسلم أنَّ جَزاء المسلم عند الله مِن جِنْس ما يَعمله المسلم مع المسلمين؛ فمَن نفَّس وفرَّج وأزال وكَشَفَ عن مؤمنٍ كُربةً وشدة من كُرَب الدنيا، جازاه الله بأن ينفَّس عنه كربةً من كرب يوم القيامة.

ومَن يَسَّر على معسرٍ وسهَّل عليه وأزال عسرته، يسَّر الله عليه في الدنيا والآخرة. 

ومَن ستر مسلمًا كأن اطّلع منه على ما لا ينبغي إظهاره من الزّلات والعَثَرات، ستره الله في الدنيا والآخرة. 

والله يكون مُعينًا لِعَبدِه، ما كان العبد سائرًا في إعانة أخيه في مصالحه الدينية والدنيوية، والإعانة تكون بالدعاء والبدن والمال وغير ذلك. 

ومن مشى إلى تحصيل علمٍ شرعيٍ، قاصدًا به وجه الله تعالى؛ سهَّل الله له به طريقًا إلى الجنة. 

وما اجتمع قومٌ في بيتٍ من بيوت الله، يتلون كتاب الله ويتدارسونه بينهم، إلا نزلت عليهم الطمأنينة والوقار، وغطتهم وعمَّتهم رحمة الله، وحفَّتْهم الملائكة، وأثنى الله عليهم في المقرَّبين عنده، وكفى شرفًا ذِكرُ اللهِ العبدَ في الملأ الأعلى. 

ومَن كان عمله ناقصًا، لم يُلْحِقْه بمرتبة أصحاب الأعمال، فينبغي ألا يَتَّكل على شرف النسب وفضيلة الآباء ويُقَصّر في العمل.', 'قال ابن دقيق العيد: هذا حديث عظيم، جامع لأنواع من العلوم والقواعد والآداب، فيه فضل قضاء حوائج المسلمين ونفعهم بما يتيسر، مِن علم، أو مال، أو معاونة، أو إشارة بمصلحة، أو نصيحة، أو غير ذلك.
الترغيب في التيسير على المعسر.
الحث على عون العبد المسلم، وأن الله تعالى يُعين المعين حسب إعانته لأخيه.
مِن سِتْر المسلم: عدمُ تتبُّع عوراته، وقد رُوي عن بعض السلف أنه قال: أدركت قومًا لم يكن لهم عيوب، فذكروا عيوبَ الناس، فَذَكَر الناسُ لهم عيوبًا، وأدركت قومًا كانت لهم عيوب، فَكَفُّوا عن عيوب الناس، فنُسِيت عيوبُهم.
ليس من لوازم الستر على الناس ترك المنكر وعدم تغييره، بل يُغَيِّر ويَسْتُر، وهذا في حقِّ مَن لا يُعرَف بالفساد والتَّمَادِيْ في الطغيان، وأما من عُرِف بذلك فإنه لا يُستحب الستر عليه، بل يرفع أمره إلى مَن له الولاية، إذا لم يخَفْ مِن ذلك مفسدة؛ وذلك لأن الستر عليه يُغْرِيْهِ على الفساد، ويُجَرِّئهُ على أذية العباد، ويُجرّئ غيره من أهل الشر والعناد.
الحث على طلب العلم وتلاوة القرآن وتدارسه.
قال النووي: في هذا دليل لفضل الاجتماع على تلاوة القرآن في المسجد... ويلحق بالمسجد في تحصيل هذه الفضيلة الاجتماع في مدرسة ورباط ونحوهما إن شاء الله تعالى.
الجزاء إنما رتَّبَه الله على الأعمال لا على الأنساب.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4801', false),
(21024, 2, 209, 1024, 'hadith', '-وعن أبي هريرة رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: «إن أمتي يدعون يوم القيامة غرًا محجلين من آثار الوضوء فمن استطاع منكم أن يطيل غرته، فليفعل».', 'I heard the Messenger of Allah (ﷺ) saying: "On the Day of Resurrection, my followers (or Ummah) will be summoned ''Al-Ghurr Al-Muhajjalun'' from the traces of Wudu''. Whoever can increase the area of his radiance should do so.".', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1024', 'Riyad as-Salihin 1024', 'ریاض الصالحین 1024', 'متفق عليه', 'يبشر النبي صلى الله عليه وسلم أمته بأن الله سبحانه وتعالى يخصهم بعلامة فضل وشرف يومَ القيامة، من بين الأمم، حيث ينادون فيأتون على رؤوس الخلائق تتلألأ وجوههم وأيديهم وأرجلهم بالنور، وذلك أثر من آثار هذه العبادة العظيمة، وهي الوضوء الذي كرروه على هذه الأعضاء الشريفة ابتغاء مرضاة الله، وطلبا لثوابه، فكان جزاؤهم هذه المحمدة العظيمة الخاصة. ثم يقول أبو هريرة رضي الله عنه : "من قدر على إطالة هذه الغرّة فليفعل"؛ لأنه كلما طال مكان الغسل من العضو طالت الغرة والتحجيل، ولكن المشروع فقط أن يكون غسل اليدين في الوضوء إلى المرفقين ويستوعب المرفق بالشروع في العضد وغسل جزء منه، وغسل القدمين إلى الكعبين يستوعب الكعبين بالشروع في الساق، ولا يغسل العضد والساق في الوضوء، وفي الرواية الخرى ينقل عن رسول الله صلى الله عليه وسلم أن حلية المؤمن في الجنة تبلغ ما بلغ ماء الوضوء.', 'الجزاء على الوضوء بالغرة والتحجيل يوم القيامة، وبأن حلية المؤمن في الجنة تبلغ حيث يبلغ الوضوء.
لما كان الوضوء مشتقًّا من الوضاءة، وهو النور، كان بذلك نورا للمؤمنين يوم القيامة في وجوههم و أيديهم و أرجلهم، ويعرفون بهذه الخصيصة من بين الأمم يوم القيامة.
فِي رواية لمسلم: سَمِعْتُ خَلِيلِي -صلى الله عليه وسلم- يقولُ: (تَبلُغُ الحِليَة من المُؤمِن حيث يَبلُغُ الوُضُوءُ) فيه دليل أن الوضوء كما كان زينة في الدنيا، فهو كذلك في الآخرة.
الحلي في الجنة للرجال والنساء.
الحديث إثبات يوم القيامة، وما فيه من حساب وجزاء.
فضيلة هذه الأمة، وفضيلة الوضوء، وأنه خاص بهم.', 'أمتي : أمة الاستجابة، والمراد: من آمن به واتبعه.
يُدْعَون : ينادَوْن نداء تشريف وتكريم.
يوم القيامة : يوم يدعى الناس لرب العالمين من قبورهم مبعوثين للحساب والجزاء.
غُرّاً : جمع " أغر " أصلها لمعة بيضاء في جبهة الفرس، فأطلقت على نور وجوههم.
مُحَجَلِّين : من " التحجيل " وهو بياض يكون في قوائم الفرس، والمراد به هنا: النور الكائن في هذه الأعضاء يوم القيامة، تشبيها بتحجيل الفرس.
من آثار الوُضوء : العلهّ والسبب للغرة والتحجيل.
اسْتَطَاع : قدر.
يُطِيل : يمد ويزيد.
رَأَيت : أبصرت، والرائي: نُعَيم المجمِّر.
كاد : قارب.
يَبلُغ : يصل.
المَنكِبَين : تثنية منكب، وهو ما يجمع رأس الكتف والعضد.
السَّاقين : تثنية ساق، وهو العظم الذي بين الركبة والكعبين.
خليلي : من اتخذته خليلا، والخليل: من بلغت محبته أعلى منازل المحبة، والمراد به هنا النبي -صلى الله عليه وسلم-.
الحِلية : هي ما يتحلى به لكمال الجمال.
الوُضُوء : هو فعل الوضوء.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3368', false),
(21025, 2, 209, 1025, 'hadith', 'وعنه قال: سمعت خليلي صلى الله عليه وسلم يقول: «تبلغ الحلية من المؤمن حيث يبلغ الوضوء».', 'I heard my Khalil (the Messenger of Allah (ﷺ)) as saying, "The adornment of the believer (in Jannah) will reach the places where the water of Wudu'' reaches (his body).".', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1025', 'Riyad as-Salihin 1025', 'ریاض الصالحین 1025', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21026, 2, 209, 1026, 'hadith', 'عن عثمان بن عفان رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «من توضأ فأحسن الوضوء، خرجت خطاياه من جسده حتى تخرج من تحت أظفاره».', 'The Messenger of Allah (ﷺ) said, "He who performs the Wudu'' perfectly (i.e., according to Sunnah), his sins will depart from his body, even from under his nails.".', 'عثمان بن عفان رضي الله عنه', '''Uthman bin ''Affan (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1026', 'Riyad as-Salihin 1026', 'ریاض الصالحین 1026', 'رواه مسلم', 'يُخْبِرُ النبيُّ صلى الله عليه وسلم أنَّ مَن توضَّأ مع مُراعاةِ سُننِ الوضوء وآدابِه، كان ذلك من أسبابِ تكفيرِ السيئات وحَطِّ الخطايا، «حتى تخرج» ذنوبُه من تحت أظفار يديه ورجليه.', 'الحث على الاعتناء بتعلُّم الوضوء وسننه وآدابه، والعمل بذلك.
فضل الوضوء، وأنه كفارة للذنوب الصغائر، أما الكبائر فلا بد من التوبة.
شرط خروج الخطايا هو إكمال الوضوء والإتيان به بدون إخلال كما بينه النبي -صلى الله عليه وسلم-.
تكفير الذنوب في هذا الحديث مُقيَّدٌ باجتناب الكبائر والتوبة منها، قال تعالى: (إِنْ تَجْتَنِبُوا كَبَائِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنْكُمْ سَيِّئَاتِكُمْ) [النساء:31].', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6263', false),
(21027, 2, 209, 1027, 'hadith', 'وعنه قال: رأيت رسول الله صلى الله عليه وسلم يتوضأ مثل وضوئي هذا ثم قال: «من توضأ هكذا، غفر له ما تقدم من ذنبه، وكانت صلاته ومشيه إلى المسجد نافلة».', 'I saw the Messenger of Allah (ﷺ) performing Wudu'' the way I have just done it and said, "He who performs Wudu'' like this, his previous sins will be forgiven and his Salat and walking to the mosque will be considered as supererogatory act of worship.".', null, '''Uthman bin ''Affan (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1027', 'Riyad as-Salihin 1027', 'ریاض الصالحین 1027', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21028, 2, 209, 1028, 'hadith', '-وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «إذا توضأ العبد المسلم - أو المؤمن- فغسل وجهه، خرج من وجهه كل خطيئة نظر إليها بعينيه مع الماء، أو مع آخر قطر الماء، فإذا غسل يديه، خرج من يديه كل خطيئة كان بطشتها يداه مع الماء، أو مع آخر قطر الماء، فإذا غسل رجليه، خرجت كل خطيئة مشتها رجلاه مع الماء، أو مع آخر قطر الماء، حتى يخرج نقيًا من الذنوب».', 'The Messenger of Allah (ﷺ) said, "When a Muslim, or a believer, washes his face (in the course of Wudu''), every sin which he committed with his eyes, will be washed away from his face with water, or with the last drop of water; when he washes his hands, every sin which is committed by his hands will be effaced from his hands with the water, or with the last drop of water; and when he washes his feet, every sin his feet committed will be washed away with the water, or with the last drop of water; until he finally emerges cleansed of all his sins.".', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1028', 'Riyad as-Salihin 1028', 'ریاض الصالحین 1028', 'رواه مسلم', 'بيَّن النبي صلى الله عليه وسلم أنه إذا توضأ المسلم أو المؤمن فغسل وجهه أثناء الوضوء خرج من وجهه كل خطيئة صغيرة نظر إليها بعينيه مع الماء الساقط بعد الغسل أو مع آخر قطر الماء، فإذا غسل يديه خرج من يديه كل خطيئة صغيرة كان كسبتها يداه مع الماء أو مع آخر قطر الماء، فإذا غسل رجليه خرجت كل خطيئة صغيرة مشتها رجلاه مع الماء أو مع آخر قطر الماء حتى يخرج نقيًّا من الذنوب الصغائر بالانتهاء من الوضوء.', 'فضل المحافظة على الوضوء، وأنه يكفّر الذنوب.
من هدي النبي صلى الله عليه وسلم أنه يرغب الناس في الطاعات والعبادات بذكر الأجر والثواب عليها.
كل عضو من أعضاء الإنسان يقع في بعض المعاصي، ولذلك الذنوب تتبع كل جارحة اكتسبتها، وتخرج من كل جارحة تاب منها.
الوضوء فيه التطهير الحسي، ويكون عندما تغسل أعضاء الوضوء، وتطهير معنوي يكون من الذنوب التي وقعت من الأعضاء.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3284', false),
(21029, 2, 209, 1029, 'hadith', 'وعنه أن رسول الله صلى الله عليه وسلم أتى المقبرة فقال: "السلام عليكم دار قوم مؤمنين وإنا إن شاء الله بكم لاحقون، وددت أنا قد رأينا إخواننا" قالوا: أولسنا إخوانك يا رسول الله؟ قال: "أنتم أصحابي، وإخواننا الذين لم يأتوا بعد" قالوا: كيف تعرف من لم يأتِ بعد من أمتك يا رسول الله؟ فقال: "أرأيت لو أن رجلا له خيل غر محجلة بين ظهري خيل دهم بهم، ألا يعرف خيله ؟" قالوا بلى يا رسول الله، قال: فإنهم يأتون غرًا محجلين من الوضوء وأنا فرطهم على الحوض.', 'The Messenger of Allah (ﷺ) went to the (Baqi'') cemetery and said, "May you be secured from punishment, O dwellers of abode of the believers! We, if Allah wills, will follow you. I wish we see my brothers." The Companions said, "O Messenger of Allah! Are not we your brothers?" He (ﷺ) said, "You are my Companions, but my brothers are those who have not come into the world yet." They said; "O Messenger of Allah! How will you recognize those of your Ummah who are not born yet?" He (ﷺ) said, "Say, if a man has white-footed horses with white foreheads among horses which are pure black, will he not recognize his own horses?" They said; "Certainly, O Messenger of Allah!" He (ﷺ) said, "They (my followers) will come with bright faces and white limbs because of Wudu''; and I will arrive at the Haud (Al-Kauthar) ahead of them.".', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1029', 'Riyad as-Salihin 1029', 'ریاض الصالحین 1029', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21030, 2, 209, 1030, 'hadith', 'وعنه أن رسول الله صلى الله عليه وسلم قال ألا أدلكم على ما يمحو الله به الخطايا ويرفع به الدرجات قالوا بلى يارسول الله قال: «إسباغ الوضوء على المكاره، وكثرة الخطا إلى المساجد، وانتظار الصلاة بعد الصلاة، فذلكم الرباط، فذلكم الرباط».', 'Abu Hurairah (May Allah be pleased with him) reported that the Messenger of Allah (ﷺ) said, "Shall I not tell you something by which Allah effaces the sins and elevates ranks (in Jannah)?" The Companions said; "Certainly, O Messenger of Allah." He (ﷺ) said, "Performing the Wudu'' thoroughly in spite of difficult circumstances, walking with more paces to the mosque, and waiting for the next As- Salat (the prayer) after observing Salat; and that is Ar-Ribat, and that is Ar-Ribat.".', null, null, 'صحيح', 'رياض الصالحين 1030', 'Riyad as-Salihin 1030', 'ریاض الصالحین 1030', 'رواه مسلم', 'سَألَ النبيُّ صلى الله عليه وسلم أصحابَه هل يُريدون أنْ يدلَّهم على أعمال تكون سببًا في مغفرة الذنوب، ومحوها من كُتب الحفظة، وعلو المنازل في الجنة؟ 

قال الصحابة: نعم نريد ذلك. قال: 

الأول: استيعاب وإتمام الوضوء على مشقة؛ كَبردٍ، وقلة ماء، وألم جسم، وماء حار. 

الثاني: كثرة الخُطا -وهي ما بين القدمين- إلى المساجد ببعد الدار، وكثرة التكرار. 

الثالث: انتظار وقت الصلاة، وتعلُّق القلب بها، والتأهب لها، والجلوس لها في المسجد لانتظار الجماعة، فإذا صلاها انتظر في مصلاه صلاةً أخرى. 

ثم بيَّنَ صلى الله عليه وسلم أنَّ هذه الأمور هي المرابطة الحقيقية؛ لأنها تسد طرق الشيطان على النفس، وتقهر الهوى، وتمنعها من قبول الوساوس، فيغلب بها حزبُ الله جنودَ الشيطان؛ وذلك هو الجهاد الأكبر، فكانت بمنزلة الرباط على ثغر العدو.', 'أهمية المحافظة على صلاة الجماعة في المسجد، والاهتمام بالصلوات وعدم التشاغل عنها.
حسن عرض النبي صلى الله عليه وسلم وتشويقه لأصحابه حيث بدأهم بثواب عظيم على طريقة السؤال، وهذه طريقة من طرق التعليم.
فائدة عرض المسألة بالسؤال والجواب: أن يكون الكلام أوقع في النفس بحكم الإبهام والتبيين.
قال النووي رحمه الله: فذلكم الرباط أي: الرباط المرغَّب فيه، وأصل الرباط الحبس على الشيء، كأنه حبس نفسه على هذه الطاعة، وقيل: إنه أفضل الرباط كما قيل: الجهاد جهاد النفس، ويحتمل أنه الرباط المتيسر الممكن، أي: إنه من أنواع الرباط.
كررت كلمة "الرباط" وعرفت ب(ال) التعريف؛ ذلك تعظيمٌ لشأن هذه الأعمال.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3574', false),
(21031, 2, 209, 1031, 'hadith', 'عن أبي مالك الأشعري رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم «الطهور شطر الإيمان» ((رواه مسلم)). وقد سبق بطوله في باب الصبر. وفي الباب حديث عمرو بن عبسة رضي الله عنه السابق في آخر باب الرجاء، وهو حديث عظيم، مشتمل على جمل من الخيرات.', 'The Messenger of Allah (ﷺ) said: "Purification is half the Iman.".', 'أبي مالك الأشعري رضي الله عنه', 'Abu Malik Al-Ash''ari (May Allah be pleased with him)', null, 'رياض الصالحين 1031', 'Riyad as-Salihin 1031', 'ریاض الصالحین 1031', null, null, null, null, 'sunnah.com', null, false, null, false),
(21032, 2, 209, 1032, 'hadith', 'عن عمر بن الخطاب رضي الله عنه عن النبي صلى الله عليه وسلم قال:"ما منكم من أحد يتوضا فيبلغ-أو فيسبغ الوضوء- ثم قال: أشهد أن لا إله إلا الله وحده لا شريك له، وأشهد أن محمدًا عبده ورسوله، إلا فتحت له أبواب الجنة الثمانية يدخل من أيها شاء" ((رواه مسلم)). وزاد الترمذي: "اللهم اجعلني من التوابين واجعلني من المتطهرين"', 'The Messenger of Allah (ﷺ) said, "Whoever of you performs Wudu'' carefully and then affirms: ''Ash-hadu an la ilaha illallahu Wahdahu la sharika Lahu, wa ash-hadu anna Muhammadan ''abduhu wa Rasuluhu .In the narration in At- Tirmidhi, it is added: "Allahummaj-''alni minat-tawwabina, waj-''alni minal-mutatahhirin (O Allah make me among those who repent and purify themselves)."', 'عمر بن الخطاب رضي الله عنه', '''Umar bin Al-Khattab (May Allah be pleased with him)', null, 'رياض الصالحين 1032', 'Riyad as-Salihin 1032', 'ریاض الصالحین 1032', null, null, null, null, 'sunnah.com', null, false, null, false),
(21033, 2, 209, 1033, 'hadith', '- عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «لو يعلم الناس ما في النداء والصف الأول ثم لم يجدوا إلا أن يستهموا عليه لاستهموا عليه، ولو يعلمون ما في التهجير لاستبقوا إليه، ولو يعلمون ما في العتمة والصبح لأتوهما ولو حبوا» ((متفق عليه)). والاستهام: الاقتراع. والتهجير: التبكير إلى الصلاة', 'The Messenger of Allah (ﷺ) said: "Were people to know the blessing of pronouncing Adhan and the standing in the first row, they would even draw lots to secure these privileges. And were they to realize the reward of performing Salat early, they would race for it; and were they to know the merits of Salat after nightfall (''Isha'') and the dawn (Fajr) Salat, they would come to them even if they had to crawl.".', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1033', 'Riyad as-Salihin 1033', 'ریاض الصالحین 1033', null, 'أخبر النبيُّ صلى الله عليه وسلم أن الناس لو يعلمون ما في الأذان والصف الأول من الفضيلة والخير والبركة ثم لم يجدوا من وجوه التقديم والأولوية لها إلا أن يقترعوا عليهما أيهم يستحق على صاحبه لاقترعوا، ولو يعلمون ما في التبكير إلى الصلاة في أول وقتها لاستبقوا إليه، ولو يعلمون مقدار الثواب في إتيان صلاة العشاء وصلاة الفجر لاستسهل إتيانهما ولو حبوًا على الرُّكَب كما يمشي الصبي أول أمْرِه.', 'بيان فضيلة الأذان.
بيان فضيلة الصف الأول، والقُرْب من الإمام.
بيان فضيلة التبكير إلى الصلاة في أول وقتها المستحب؛ لِما فيه من الفضل العظيم، وما يترتب عليه من الفوائد، ومنها: إدراك الصف الأول، وإدراك الصلاة من أولها، وأداء النافلة، وقراءة القرآن، وحصول استغفار الملائكة له، وأنه لا يزال في صلاة ما انتظر الصلاة، وغير ذلك.
الحث العظيم على حضور جماعة هاتين الصلاتين، والفضل الكثير في ذلك لما فيهما من المشقة على النفس من تَنْغِيْص أول نومها وآخره، ولهذا كانتا أثقل الصلاة على المنافقين. ‏
قال النووي: فيه إثبات القرعة في الحقوق التي يزدحم عليها ويتنازع فيها. ‏
الصف الثاني أفضل من الثالث، والثالث أفضل من الرابع، وهلم جرًّا.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65735', false),
(21034, 2, 209, 1034, 'hadith', 'عن معاوية رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: «المؤذنون أطول الناس أعناقًا يوم القيامة».', 'I heard the Messenger of Allah (ﷺ) saying: "The Mu''adhdhinun (callers to prayer) will have the longest necks on the Day of Resurrection.".', 'معاوية رضي الله عنه', 'Mu''awiyah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1034', 'Riyad as-Salihin 1034', 'ریاض الصالحین 1034', 'رواه مسلم', 'أخبر النبي صلى الله عليه وسلم أن المؤذنين الذين يُنادُون بالصلاة هم أطول الناس أعناقًا يوم القيامة لشَرف عملهم، وكثرة خيرهم، وعظم أجرهم.', 'فضل الأذان والترغيب فيه.
بيان شَرف المؤذنين، وعلوّ منزلتهم يوم القيامة.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/10115', false),
(21035, 2, 209, 1035, 'hadith', 'عن عبد الله بن عبد الرحمن بن أبي صعصعة أن أبا سعيد الخدري رضي الله عنه قال له: «إني أراك تحب الغنم والبادية فإذا كنت في غنمك- أو باديتك- فأذنت للصلاة، فارفع صوتك بالنداء، فإنه لا يسمع مدى صوت المؤذن جن، ولا إنس، ولا شيء، إلا شهد له يوم القيامة» قال أبو سعيد: سمعته من رسول الله صلى الله عليه وسلم.', 'Abu Sa''id Al-Khudri (May Allah be pleased with him) said to me: "I see that you like living among your sheep in wilderness. So whenever you are with your sheep or in wilderness and you want to call Adhan, you should raise your voice because whoever hears the Adhan, whether a human or jinn or any other creature, will testify for you on the Day of Resurrection." Abu Sa''id added: "I heard this from the Messenger of Allah (ﷺ).".', 'عبد الله بن عبد الرحمن بن أبي صعصعة أن أبا سعيد الخدري رضي الله عنه', '''Abdullah bin ''Abdur-Rahman', 'صحيح', 'رياض الصالحين 1035', 'Riyad as-Salihin 1035', 'ریاض الصالحین 1035', 'رواه البخاري', 'عن عبد اللّه بن عبد الرحمن بن أبي صعصعة أن أبا سعيد الخدري -رضي اللّه عنه- قال له: "إني أراك تحب الغنم والبادية"، وهي خلاف الحاضرة، وجمعها بَوَادٍ، "فإذا كنت في غنمك أو باديتك فأذنت للصلاة"، أي: أردت الأذان لها، "فارفع صوتك بالنداء"، : بالأذان، "فإنه "لا يسمع غاية، "صوت المؤذن" ونهايته وأقصاه "جن ولا إنس" ولا شيء" قيل: المراد كل شيء يصح منه الشهادة كذلك، وقيل: عام في كل ما يسمع ولو غير عاقل من سائر الحيوانات دون الجماد، "إلا شهد له يوم القيامة"، أي: يشهد له يوم القيامة بأنه من المؤذنين تنويهاً لفضله، وبياناً لثوابه.', 'حرص الصحابة على تعليم الناس السنة.
استحباب رفع الصوت بالأذان ليكثر من يشهد له.
كل من سمع المؤذن يشهد له يوم القيامة.
أذان المنفرد مندوب إليه، ولو كان في صحراء.
يستحسن أن يتخذ المسلمون مؤذناً قوي الصوت.', 'البادية : الصحراء التي لا عمارة فيها.
بالنداء : بالأذان.
مدى صوت المؤذن : غاية صوته، أي: المكان الذي ينتهي إليه الصوت.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5771', false),
(21036, 2, 209, 1036, 'hadith', '- وعن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «إذا نودي بالصلاة، أدبر الشيطان، له ضراط حتى لا يسمع التأذين، فإذا قضي النداء أقبل، حتى ثوب بالصلاة أدبر حتى إذا قضي التثويب أقبل حتى يخطر بين المرء ونفسه يقول: اذكر كذا، واذكر كذا- لما لم يذكر من قبل- حتى يظل الرجل ما يدري كم صلى».', 'The Messenger of Allah (ﷺ) said, "When Adhan for Salat is pronounced, the devil takes to his heels and breaks wind with noise so as not to hear the call. When the Adhan is finished, he returns. When the Iqamah is announced, he turns his back, and after it is finished, he returns again to distract the attention of one and makes him remember things which he does not recall in his mind before the Salat, and says ''Remember this, and this,'' and thus causes one to forget how many Rak''at he performed.".', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1036', 'Riyad as-Salihin 1036', 'ریاض الصالحین 1036', 'متفق عليه', 'إذا أذن المؤذن ولى الشيطان وأبعد عن مكان الأذان حتى يخرج بعيدًا لئلا يسمع الأذان، وله ضراط، ظاهره أنه يتعمد إخراج ذلك الضراط، وهي الريح، ليشتغل بسماع الصوت الذي يخرجه عن سماع المؤذن أو يصنع ذلك استخفافًا كما يصنعه السفهاء، ويحتمل أنه يتعمد ذلك ليقابل ما يناسب الصلاة من الطهارة بالحدث، ويحتمل أنه لا يتعمد ذلك بل يحصل له عند سماع الأذان شدةُ خوفٍ فيحدث له ذلك الصوت بسببها، "فإذا قضي النداء أقبل، حتى إذا ثوب بالصلاة أدبر" عند الإقامة "حتى إذا قضى"، أي: فرغ وانتهى، "التثويب أقبل حتى يخطر"، معناه:يوسوس، وأصله من خطر البعير بذنبه إذا حركه فضرب به فخذيه، أقبل حتى يغوي بني آدم، وإنما هرب الشيطان عند الأذان لما يرى من الاتفاق على إعلان كلمة التوحيد وغيرها من العقائد وإقامة الشعائر، وكراهة أن يسمع ذكر الله عز وجل وهذا هو معنى قوله تعالى : "من شر الوسواس الخناس" ، الذي يخنس عند ذكر الله عز وجل ويختفي ويبعد؛ قوله: "بين المرء ونفسه" أقبل حتى يحول بين المرء وقلبه في صلاته يقول له: اذكر كذا اذكر كذا اذكر كذا،"لما لم يكن يذكر من قبل"، أي: قبل شروعه في الصلاة، "حتى يظل الرجل"، أي: ينسى ويذهب وهمه، "ما يدري كم صلى"، وإنما جاء عند الصلاة مع أن فيها قراءة القرآن؛ لأن غالبها سر ومناجاة فله تطرّق إلى إفسادها على فاعلها أو إفساد خشوعه، وقيل: هربه عند الأذان حتى لا يضطر إلى الشهادة لابن آدم يوم القيامة؛ كما جاء في حديث أبي سعيد.', 'فضيلة الأذان، وأنه يطرد الشيطان.
الحث على الخشوع والاستغراق في الصلاة، والاحتراز عن وسوسة الشيطان فيها.
الصراع بين أهل الإيمان والشيطان دائم لا ينتهي.
استخدام الشيطان طرقًا وأساليب متنوعة، لإلهاء بني آدم.', 'أدبر الشيطان : فرّ هاربًا.
يخطر : يوسوس.
ثُوِّب : أقيم.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/10109', false),
(21037, 2, 209, 1037, 'hadith', 'عن عبد الله بن عمرو بن العاص رضي الله عنهما أنه سمع رسول الله صلى الله عليه وسلم يقول: «إذا سمعتم النداء فقولوا مثل ما يقول، ثم صلوا علي، فإنه من صلى على صلاة صلى الله عليه بها عشرًا، ثم سلوا الله لي الوسيلة، فإنها منزلة في الجنة لا تنبغي إلا لعبد من عباد الله وأرجو أن أكون أنا هو، فمن سأل لي الوسيلة حلت له الشفاعة».', 'I heard the Messenger of Allah (ﷺ) saying, "When you hear the Adhan, repeat what the Mu''adhdhin says. Then ask Allah to exalt my mention because everyone who does so will receive in return ten rewards from Allah. Then beseech Allah to grant me Al-Wasilah, which is a high rank in Jannah, fitting for only one of Allah''s slaves; and I hope that I will be that man. If any one asks Al-Wasilah for me, it becomes incumbent upon me to intercede for him."', 'عبد الله بن عمرو بن العاص رضي الله عنهما', '''Abdullah bin ''Amr bin Al-''As (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1037', 'Riyad as-Salihin 1037', 'ریاض الصالحین 1037', 'رواه مسلم', 'أَرْشَدَ النبيُّ صلى الله عليه وسلم مَن سمع المؤذِّنَ للصلاة أنْ يُردِّدَ خلفه فيقول مثلَ قولِه، ما عدا الحَيْعَلَتَيْن، فإنه يقول بعدهما: لا حول ولا قوة إلا بالله، ثم يصلي على النبي صلى الله عليه وسلم عقب الانتهاء من الأذان، فإنه من صلّى عليه صلاةً واحدة صلى الله عليه بسببِها عشر صلوات، ومعنى صلاة الله على عبدِه: ثناؤه على العبد عند الملائكة.

ثم أمر بسؤال الله الوسيلةَ له صلى الله عليه وسلم، وهي مَنْزِلَةٌ في الجنة، وهي أعلاها، لا تصلح ولا تتيسر تلك المنزلة إلا لعبد واحد من جميع عباد الله تعالى، وأرجو أن أكون هو أنا، وإنما قال صلى الله عليه وسلم ذلك تواضعًا؛ لأنه إذا كانت تلك المنزلة الرفيعة لا تكون إلا لواحد، فلا يكون ذلك الواحد إلا هو صلى الله عليه وسلم؛ لأنه أفضل الخلق.

ثم بَيَّنَ صلى الله عليه وسلم أنَّ مَن دعا للنبيِّ صلى الله عليه وسلم بالوسيلةِ حَصَلَتْ له شفاعتُه صلى الله عليه وسلم.', 'الحث على إجابة المؤذن.
فضل الصلاة على النبي صلى الله عليه وسلم بعد إجابة المؤذن.
الحث على سؤال الوسيلة للنبي صلى الله عليه وسلم بعد الصلاة عليه.
بيان معنى الوسيلة، وعلو شأنها، حيث لا تصلح إلا لعبد واحد.
بيان فضل النبي صلى الله عليه وسلم حيث اختُص بتلك المنزلة الرفيعة.
من سأل الله تعالى الوسيلة للنبي صلى الله عليه وسلم حلت له الشفاعة.
بيان تواضعه صلى الله عليه وسلم حيث طلب من أمته الدعاء له بتلك المنزلة، مع أنها ستكون له.
سعة فضل الله ورحمته، فالحسنة بعشر أمثالها.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65087', false),
(21038, 2, 209, 1038, 'hadith', 'عن أبي سعيد الخدري رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «إذا سمعتم النداء، فقولوا كما يقول المؤذن».', 'The Messenger of Allah (ﷺ) said, "When you hear the Mu''adhdhin (pronouncing the call to Salat), repeat after him what he says.".', 'أبي سعيد الخدري رضي الله عنه', 'Abu Sa''id Al-Khudri (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1038', 'Riyad as-Salihin 1038', 'ریاض الصالحین 1038', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21039, 2, 209, 1039, 'hadith', 'عن جابر رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «من قال حين يسمع النداء: اللهم رب هذه الدعوة التامة، والصلاة القائمة، آت محمدًا الوسيلة والفضيلة، وابعثه مقامًا محمودًا الذي وعدته، حلت له شفاعتي يوم القيامة».', 'The Messenger of Allah (ﷺ) said, "He who says upon hearing the Adhan: ''Allahumma Rabba hadhihid-da''wati-ttammati, was-salatil-qa''imati, ati Muhammadanil-wasilata wal-fadhilata, wab''athu maqaman mahmuda nilladhi wa ''adtahu .', 'جابر رضي الله عنه', 'Jabir (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1039', 'Riyad as-Salihin 1039', 'ریاض الصالحین 1039', 'رواه البخاري', 'يُبَيِّنُ النبيُّ صلى الله عليه وسلم أنَّ مَن قال حين يسمع المؤذِّنَ بعد أنْ ينتهي منه: 

(اللَّهُمَّ رَبَّ هَذِهِ الدَّعْوَةِ)، وهي ألفاظ الأذان التي يُدْعَى بها إلى عبادة الله والصلاة، (التَّامَّةِ) الكاملة، دعوة التوحيد والرسالة، (وَالصَّلاَةِ القَائِمَةِ) الدائمة التي ستقام، (آتِ) وأَعْطِ، (مُحَمَّدًا الوَسِيلَةَ) والمَنْزِلة العَلِيّة في الجنة التي لا تنبغي إلا له صلى الله عليه وسلم، (وَالفَضِيلَةَ) المَرْتَبةَ الزائدةَ على مراتب الخلائق، (وَابْعَثْهُ) وأَعْطِه (مَقَامًا مَحْمُودًا) يُحْمَد القائم فيه؛ وهو الشفاعة العظمى يوم القيامة، (الَّذِي وَعَدْتَهُ) بقولك: {عسى أن يبعثك ربك مقامًا محمودًا} بأن تكون له صلى الله عليه وسلم. 

فمن دعا هذا الدعاء استحقَّ  ووَجَبتْ له شفاعةُ النبي صلى الله عليه وسلم يوم القيامة.', 'مشروعية هذا الدعاء بعد الفراغ من التَّرْدِيْد خَلْفَ المؤذِّن، ومَن لم يَسمع النِّداء؛ فإنه لا يقوله.
فضيلة الرسول صلى الله عليه وسلم حيث أُعطي الوَسِيلة والفَضِيلة والمقام المحمود والشفاعة العظمى في الفَصْلِ بين الخلائق.
إثبات الشَّفاعة للرسول صلى الله عليه وسلم؛ لقوله: "حلَّت له شفاعتي يوم القيامة".
شفاعته صلى الله عليه وسلم تكون لأهل الكبائر مِن أمته في عدم دخول النار أو مَن دَخَلَها أن يخرج منها، أو في دخول الجنة بغير حساب، أو رفع درجات من دخلها.
قال الطيبي: من أوله إلى قوله "محمدًا رسول الله" هي الدعوة التامة، والحَيْعَلَة هي الصلاة القائمة في قوله يُقيمون الصلاة، ويحتمل أن يكون المراد بالصلاة الدعاء وبالقائمة الدائمة مِن قام على الشيء إذا داوم عليه، وعلى هذا فقوله "والصلاة القائمة" بيان للدعوة التامة، ويحتمل أن يكون المراد بالصلاة المعهودة المدعو إليها حينئذ وهو أظهر.
قال المهلب: في الحديث الحض على الدعاء في أوقات الصلوات؛ لأنه حال رجاء الإجابة.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/10635', false),
(21040, 2, 209, 1040, 'hadith', 'عن سعد بن أبي وقاص رضي الله عنه عن النبي صلى الله عليه وسلم أنه قال: «من قال حين يسمع المؤذن: أشهد أن لا إله إلا الله وحده لا شريك له، وأن محمدًا عبده ورسوله، رضيت بالله ربًا وبالإسلام دينًا، غفر له ذنبه».', 'The Prophet (ﷺ) said, "He who says after the Adhan: ''Ash-hadu an la ilaha illallah Wah-dahu la sharika Lahu; wa ash-hadu anna Muhammadan ''abduhu wa Rasuluhu, radhitu Billahi Rabban, wa bi Muhammadin Rasulan, wa bil Islami Dinan .', 'سعد بن أبي وقاص رضي الله عنه', 'Sa''d bin Abu Waqqas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1040', 'Riyad as-Salihin 1040', 'ریاض الصالحین 1040', 'رواه الترمذي وقال حديث حسن', 'أَخْبَرَ النبيُّ صلى الله عليه وسلم أنه مَن قال حين يَسمعُ المؤذنَ 
"أشهد أن لا إله إلا الله وحده لا شريك له" أي: أُقِرُّ وأعترفُ وأُخبِر أنه لا معبود بحق إلا الله، وكل معبود سواه فهو باطل، 
"وأن محمدًا عبده ورسوله" أي: أنه عَبْدٌ لا يُعبَد، ورسول لا يَكذِب، 
"رضيت بالله ربًّا" أي: بربوبيته وألوهيته وأسمائه وصفاته، 
"وبمحمد رسولًا" أي: بجميع ما أرسل به، وبلغه إلينا،
"وبالإسلام" أي: بجميع أحكام الإسلام من الأوامر والنواهي،
"دينًا" أي: اعتقادًا وانقيادًا،
"غفر له ذنبه" أي: من الصغائر.', 'ترديد هذا الدعاء عند سماع النداء من مُكَفِّرات الذنوب.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6272', false)
