insert into hadith (id, collection_id, chapter_id, number_in_book, kind, arabic, translation_en, narrator_ar, narrator_en, grade_ar, reference_ar, reference_en, reference_ur, full_ref_ar, explanation_ar, benefits_ar, word_meanings_ar, source, source_ref, daily_ok, review_note, deleted) values
(21041, 2, 209, 1041, 'hadith', 'عن أنس قال : قَالَ رسول الله : « الدُّعَاءُ لا يُرَدُّ بَيْنَ الأَذَانِ وَالإقَامَةِ » . رواه أَبُو داود والترمذي ، وقال : ( حَدِيثٌ حَسَنٌ )', 'The Messenger of Allah (ﷺ) said: "The supplication made between the Adhan and the Iqamah is never rejected.".', null, 'Anas (May Allah be pleased with him)', null, 'رياض الصالحين 1041', 'Riyad as-Salihin 1041', 'ریاض الصالحین 1041', null, null, null, null, 'sunnah.com', null, false, null, false),
(21042, 2, 209, 1042, 'hadith', 'عن أبي هريرة رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: "أرأيتم لو أن نهرًا بباب أحدكم يغتسل منه كل يوم خمس مرات، هل يبقى من درنه شيء؟" قالوا: لا يبقى من درنه شيء، قال: "فذلك مثل الصلوات الخمس، يمحو الله بهن الخطايا".', 'I heard the Messenger of Allah (ﷺ) saying, "Say, if there were a river at the door of one of you in which he takes a bath five times a day, would any soiling remain on him?" They replied, "No soiling would left on him." He (ﷺ) said, " That is the five (obligatory) Salat (prayers). Allah obliterates all sins as a result of performing them.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairahu (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1042', 'Riyad as-Salihin 1042', 'ریاض الصالحین 1042', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21043, 2, 209, 1043, 'hadith', 'عن جابر رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «مثل الصلوات الخمس كمثل نهر غمر جار على باب أحدكم يغتسل منه كل يوم خمس مرات».', 'The Messenger of Allah (ﷺ) said, "The similitude of the five (obligatory) Salat is like a river running at the door of one of you in which he takes a bath five times a day.".', 'جابر رضي الله عنه', 'Jabiru (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1043', 'Riyad as-Salihin 1043', 'ریاض الصالحین 1043', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21044, 2, 209, 1044, 'hadith', 'عن ابن مسعود رضي الله عنه أن رجلا أصاب من امرأة قُبلةً، فأتى النبي صلى الله عليه وسلم فأخبره فأنزل الله تعالى: {أقم الصلاة طرفي النهار وزلفًا من الليل، إن الحسنات يذهبن السيئات} فقال الرجل: ألي هذا؟ قال: «لجميع أمتي كلهم».', 'A man kissed a woman. So he came to the Messenger of Allah (ﷺ) and informed him about it. Then Allah revealed this Ayah: "And perform the Salat, between the two ends of the day and in some hours of the night. Verily, the good deeds efface the evil deeds (i.e., minor sins)." (11:114) The man asked the Messenger of Allah (ﷺ) whether this applies to him only. The Messenger of Allah (ﷺ) said, "It applies to all of my Ummah.".', 'ابن مسعود رضي الله عنه', 'Ibn Mas''ud (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1044', 'Riyad as-Salihin 1044', 'ریاض الصالحین 1044', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21045, 2, 209, 1045, 'hadith', 'عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «الصلوات الخمس، والجمعة إلى الجمعة، كفارة لما بينهن، ما لم تغشَ الكبائر».', 'The Messenger of Allah (ﷺ) said, "The five (daily) Salat (prayers) and the Friday (prayer) to the Friday (prayer) expiate whatever (minor sins) may be committed in between, so long as major sins are avoided.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1045', 'Riyad as-Salihin 1045', 'ریاض الصالحین 1045', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21046, 2, 209, 1046, 'hadith', 'عن عثمان بن عفان رضي الله عنه قال: سمعت النبي صلى الله عليه وسلم يقول: «ما من امرئ مسلم تحضره صلاة مكتوبة فيحسن وضوءها وخشوعها وركوعها إلا كانت كفارة لما قبلها من الذنوب مالم تؤتَ كبيرة وذلك الدهر كله».', 'I heard Messenger of Allah (ﷺ) saying, "When the time for a prescribed Salat is due and a Muslim performs its Wudu'' and its acts of bowing and prostration properly, this Salat will be an expiation for his past sins, so long as he does not commit major sins, and this applies for ever.".', 'عثمان بن عفان رضي الله عنه', '''Uthman bin ''Affan (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1046', 'Riyad as-Salihin 1046', 'ریاض الصالحین 1046', 'رواه مسلم', 'بَيَّنَ النبيُّ صلى الله عليه وسلم أنَّه ما مِن مُسلم يَدخل عليه وقت الصلاة المفروضة فيحسن وضوءها ويُتِمُّه، ثم يَخشع في صلاته بحيث يكون قلبُه وجوارحُه كلُّها مُقبلةً على الله مستحضرةً عظمتَه، ويُتم أفعالَ الصلاةِ كالركوعِ والسجود وغيرِهِ، إلا كانت هذه الصلاةُ مُكفِّرَةً لما قبلها من المعاصي الصغائر، ما لم يعمل كبيرة من كبائر الذنوب، وهذا الفضل مُمْتَدٌّ على مَرِّ الزمان وفي كل صلاة.', 'الصلاة المكفرة للذنوب هي التي أحسن العبد وضوءَها، وأدَّاها خاشعًا يبتغي بها وجه الله تعالى.
فضل المداومة على العبادات، وأنها سبب لمغفرة صغائر الذنوب.
فضل إحسان الوضوء، وإحسان الصلاة والخشوع فيها. 
أهمية اجتناب كبائر الذنوب لمغفرة الذنوب الصغائر.
كبائر الذنوب لا تُكَفَّر إلا بالتوبة.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6254', false),
(21047, 2, 209, 1047, 'hadith', 'عن أبي موسى رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «من صلى البردين دخل الجنة».', 'Messenger of Allah (ﷺ) said, "He who The observes Al-Bardan (i.e., Fajr and ''Asr prayers) will enter Jannah.".', 'أبي موسى رضي الله عنه', 'Abu Musa (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1047', 'Riyad as-Salihin 1047', 'ریاض الصالحین 1047', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21048, 2, 209, 1048, 'hadith', 'عن أبي زهير عمارة بن رؤيبة رضي الله عنه قال، سمعت رسول الله صلى الله عليه وسلم يقول: «لن يلج النار أحد صلى قبل طلوع الشمس وقبل غروبها» (11).', 'I heard the Messenger of Allah (ﷺ) saying: "He who performs Salat (prayers) before the rising of the sun and before its setting, will not enter the Hell.".', 'أبي زهير عمارة بن رؤيبة رضي الله عنه', 'Abu Zuhair ''Umarah Ruwaibah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1048', 'Riyad as-Salihin 1048', 'ریاض الصالحین 1048', 'رواه مسلم', 'يُخْبِرُ رسولُ الله صلى الله عليه وسلم: أنه لن يدخلَ النارَ، أحدٌ صلّى صلاة الفجر، وصلاة العصر، وداوم عليهما؛ وخَصَّ هاتين الصلاتين؛ لأنهما أثقلُ الصلوات، ولأنّ وقت الصبح يكون عند النوم ولَذَّتِه، ووقت العصر يكون عند الاشتغال بأعمال النهار وتجارته، ومَن حافَظَ على هاتين الصلاتَين مع وُجودِ المَشقّة فسيحافظ على بَقيّة الصلوات.', 'فضل صلاتي الصبح والعصر، فينبغي المحافظة عليهما.
مَن أدَّى هذه الصلوات يكون غالبًا خالي النفس من الكَسَل والرياء مُحِبًّا للعبادة.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6215', false),
(21049, 2, 209, 1049, 'hadith', 'عن جندب بن سفيان رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «من صلى الصبح فهو في ذمة الله فانظر يابن آدم، لا يطلبنك الله من ذمته بشيء».', 'The Messenger of Allah (ﷺ) said, "He who offers the dawn (Fajr) prayers will come under the Protection of Allah. O son of Adam! Beware, lest Allah should call you to account in any respect from (for withdrawing) His Protection.".', 'جندب بن سفيان رضي الله عنه', 'Jundub bin Sufyan (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1049', 'Riyad as-Salihin 1049', 'ریاض الصالحین 1049', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21050, 2, 209, 1050, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «يتعاقبون فيكم ملائكة بالليل، وملائكة بالنهار، ويجتمعون في صلاة الصبح وصلاة العصر، ثم يعرج الذين باتوا فيكم، فيسألهم الله -وهو أعلم بهم-: كيف تركتم عبادي؟ فيقولون تركناهم وهم يصلون، وأتيناهم وهم يصلون».', 'The Messenger of Allah (ﷺ) said, "There are angels who take turns in visiting you by night and by day, and they all assemble at the dawn (Fajr) and the afternoon (''Asr) prayers. Those who have spent the night with you, ascend to the heaven and their Rubb, Who knows better about them, asks: ''In what condition did you leave My slaves?'' They reply: ''We left them while they were performing Salat and we went to them while they were performing Salat."''.', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1050', 'Riyad as-Salihin 1050', 'ریاض الصالحین 1050', 'متفق عليه', 'قال رسول الله صلى الله عليه وسلم: يتعاقبون فيكم ملائكة أي تأتي طائفة عقب طائفة، ثم تعود الأولى عقب مجيء الثانية، وذلك بالليل والنهار، ويجتمعون ويلتقون في صلاة الفجر وصلاة العصر، ومن لطف الله تعالى بعباده المؤمنين أن جعل اجتماع ملائكته في حال طاعة عباده؛ لتكون شهادتهم لهم بأحسن شهادة، وفيه إشارة لشرف هذين الوقتين، ثم يصعد إلى السماء الذين كانوا معكم، سواء الذين كانوا معهم ليلًا والذين كانوا معهم نهارًا، فيسأل الله تعالى الملائكة عن حال المصلين وهو أعلم بحالهم، والحكمة من سؤالهم إظهار شهادتهم لبني آدم بالخير، كيف تركتم عبادي؟ ووقع السؤال عن آخر الأعمال؛ لأن الأعمال بخواتيمها، فيقول الملائكة المسؤولون: تركناهم وهم يصلون، وأتيناهم وهم يصلون، وقدَّموا الترك على الإتيان مع أن الإتيان أسبق لمطابقة السؤال؛ لأنه قال: كيف تركتم، ولأن أعمال العباد معتبر بخواتيمها كما سبق.', 'بيان فضل صلاة الجماعة في الفجر والعصر.

فيه الإشارة إلى عظم هاتين الصلاتين؛ لكونهما تجتمع فيهما الطائفتان، وفي غيرهما طائفة واحدة.

الإشارة إلى شرف الوقتين المذكورين.

تشريف هذه الأمة على غيرها من الأمم.

استشعار هذا الخبر الغيبي يفيد زيادة الإيمان.

أثر الإيمان بقدوم رسل ربنا وسؤال ربنا عنا، من ضبط أحوالنا حتى نتيقظ، ونتحفظ في الأوامر والنواهي، ونفرح في هذه الأوقات بقدومهم.

إعلامنا بحب الملائكة لنا؛ لنزداد لهم حبًّا، ونتقرب إلى الله بذلك.

إثبات كلام الله تعالى مع ملائكته الكرام.', 'يتعاقبون فيكم: تأتي طائفة عقب طائفة.

يعرج: يصعد.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65392', false),
(21051, 2, 209, 1051, 'hadith', '- وعن جرير بن عبد الله البجلي رضي الله عنه قال: كنا عند النبي صلى الله عليه وسلم، فنظر إلى القمر ليلة البدر فقال: «إنكم سترون ربكم كما ترون هذا القمر، لاتضامون في رؤيته، فإن استطعتم أن لا تغلبو على صلاة قبل طلوع الشمس، وقبل غروبها فافعلوا».', 'We were sitting with the Messenger of Allah (ﷺ) when he looked at the full moon and observed, "You will see your Rubb in the Hereafter as you see this moon having no difficulty in seeing it. So try your best to perform the prayers before the rising of the sun and that before its setting.".', null, 'Jarir bin ''Abdullah Al-Bajali (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1051', 'Riyad as-Salihin 1051', 'ریاض الصالحین 1051', 'متفق عليه)). ((وفي رواية: "فنظر إلى القمر ليلة أربع عشرة"', null, null, null, 'sunnah.com', null, false, null, false),
(21052, 2, 209, 1052, 'hadith', 'عن بريدة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «من ترك صلاة العصر فقد حبط عمله».', 'The Messenger of Allah (ﷺ) said, "He who misses the ''Asr Salat (deliberately), his deeds will be rendered nul and void.".', 'بريدة رضي الله عنه', 'Buraidah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1052', 'Riyad as-Salihin 1052', 'ریاض الصالحین 1052', 'رواه البخاري', null, null, null, 'sunnah.com', null, false, null, false),
(21053, 2, 209, 1053, 'hadith', 'عن أبي هريرة رضي الله عنه أن النبي صلى الله عليه وسلم قال: « من غدا إلى المسجد أو راح، أعد الله له في الجنة نزلا كلما غدا أو راح».', 'The Messenger of Allah (ﷺ) said, "He who goes to the mosque in the morning or in the evening, Allah prepares for him a place in Jannah whenever he goes to the mosque in the morning and returns from it in the evening.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1053', 'Riyad as-Salihin 1053', 'ریاض الصالحین 1053', 'متفق عليه', 'بَشَّرَ النبيُّ صلى الله عليه وسلم مَن أتى المَسجدَ للعبادة أو العلم أو لغير ذلك مِن مقاصد الخير في أيِّ وقت؛ أولَ النهار أو آخرَه بأنَّ الله قد هَيَّأَ له مَكانًا وضِيافة في الجنة، كلّما جاء المسجد في ليل أو نهار.', 'فَضْل الذهاب إلى المسجد، والحَثُّ على المحافظة على صلاة الجماعة فيه، فَكَم يَفُوْتُ المُتَخَلِّف عن المساجد من الخير والفضل والأجر والضيافة التي يعدُّها الله تبارك وتعالى لقاصِدِيْ بيته.
إذا كان الناس يُكرِمُون من جاء بيوتَهم، ويُقَدِّمون له الطعام، فالله تبارك وتعالى أَكْرَمُ مِن خَلْقِه! فمَن قَصَدَ بيتَه أَكرمَه، وأَعَدّ الله له نزلًا عظيمًا وكبيرًا.
الفرح والغِبْطَة بالذهاب للمساجد؛ لأنه يُعَدّ له نُزُلٌ كلّما غَدَا أو رَاح بِعَدَد ذهابِه.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5436', false),
(21054, 2, 209, 1054, 'hadith', 'وعنه أن النبي صلى الله عليه وسلم قال: «من تطهر في بيته، ثم مضى إلى بيت من بيوت الله، ليقضي فريضة من فرائض الله كانت خطواته، إحداها تحط خطيئة، والأخرى ترفع درجة».', 'The Prophet (ﷺ) said, "He who purifies (performs Wudu'') himself in his house and then walks to one of the houses of Allah (mosque) for performing an obligatory Salat, one step of his will wipe out his sins and another step will elevate his rank (in Jannah).".', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1054', 'Riyad as-Salihin 1054', 'ریاض الصالحین 1054', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21055, 2, 209, 1055, 'hadith', '-وعن أبي بن كعب رضي الله عنه قال: كان رجل من الأنصار لا أعلم أحدًا أبعد من المسجد منه، وكانت لا تخطئه صلاة! فقيل له: لو اشتريت حمارًا تركبه في الظلماء وفي الرمضاء قال: ما يسرني أن منزلي إلى جنب المسجد إني أريد أن يكتب لي ممشاي إلى المسجد، ورجوعي إذا رجعت إلى أهلي، فقال رسول الله صلى الله عليه وسلم: «قد جمع الله لك ذلك كله».', 'There was a man of the Ansar whose house was the farthest from the mosque. As far as I know, he never missed Salat (in congregation). It was said to him: "If you buy a donkey, you may ride upon it in the dark nights and in the hot days." He said: "I do not like that my house should be situated close to the mosque. I desire that my walking towards the mosque and returning home be recorded to my credit." Upon this the Messenger of Allah (ﷺ) said, "Allah has gathered all (rewards) for you.".', null, 'Ubayy bin Ka''b (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1055', 'Riyad as-Salihin 1055', 'ریاض الصالحین 1055', 'رواه مسلم', 'أخبر أبي بن كعب رضي الله عنه أن رجلًا من الأنصار من أبعد الناس دارًا من المسجد النبوي، وكان لا تفوته صلاة؛ بل يحضر كل صلاة مع النبي صلى الله عليه وسلم، فقيل له: 

لو اشتريت حمارًا تركبه في ظلماء الليل، وفي حر الأرض في النهار، قال: 

ما يسرني أن منزلي إلى جنب المسجد، إني أريد أن يكتب الله لي ممشاي إلى الصلاة في المسجد، ورجوعي إذا رجعت إلى أهلي، فوصل كلامه إلى النبي صلى الله عليه وسلم فقال: 

«قد جمع الله لك ذلك كله».', 'شدة حرص الصحابة على الخير والازدياد منه وكسب الأجر.
قال النووي: فيه إثبات الثواب في الخُطا في الرجوع من الصلاة كما يثبت في الذهاب.
تواصي المسلمين بالخير والتناصح بالبر، فمن رأى أن أخاه تلحقه مشقة فليقدم له النصح في إزالتها.
بُعد الدار عن المسجد ليس عذرًا في ترك الجماعة، ما دام يسمع النداء.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3561', false),
(21056, 2, 209, 1056, 'hadith', 'عن جابر رضي الله عنه قال: خلت البقاع حول المسجد فأراد بنو سلمة أن ينتقلوا قرب المسجد، فبلغ ذلك النبي صلى الله عليه وسلم فقال لهم: "بلغني أنكم تريدون أن تنتقلوا قرب المسجد؟ قالوا: نعم يا رسول الله قد أردنا ذلك، فقال: " بني سلمة دياركم تكتب آثاركم، دياركم تكتب آثاركم" فقالوا: ما يسرنا أنا كنا تحولنا".', 'There were some plots of land lying vacant around the mosque. The people of Banu Salamah decided to move to this land and come nearer to the mosque. The Messenger of Allah (ﷺ) heard about it and said to them, "I have heard that you intend to move near the mosque." They said: "Yes, O Messenger of Allah! We have decided to do that." Thereupon the Messenger of Allah (ﷺ) said, "O Banu Salamah! Stay in your houses, because your footprints (when you come to the mosque) will be recorded." He said this twice. They said: "We would not have liked it, had we moved near the mosque.".', 'جابر رضي الله عنه', 'Jabir (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1056', 'Riyad as-Salihin 1056', 'ریاض الصالحین 1056', 'رواه مسلم، وروى البخاري معناه من رواية أنس', null, null, null, 'sunnah.com', null, false, null, false),
(21057, 2, 209, 1057, 'hadith', 'عن أبي موسى الأشعري رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «إن أعظم الناس أجرًا في الصلاة أبعدهم إليها ممشى، فأبعدهم، والذي ينتظر الصلاة حتى يصليها مع الإمام أعظم أجرًا من الذي يصليها ثم ينام».', 'The Messenger of Allah (ﷺ) said, "The person who will receive the highest reward for Salat (prayer) is the one who comes to perform it in the mosque from the farthest distance. And he who waits for Salat to perform it with the Imam (in congregation) will have a greater reward than the one who observes it alone and then goes to sleep.".', 'أبي موسى الأشعري رضي الله عنه', 'Abu Musa (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1057', 'Riyad as-Salihin 1057', 'ریاض الصالحین 1057', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21058, 2, 209, 1058, 'hadith', 'عن بريدة رضي الله عنه عن النبي صلى الله عليه وسلم : «بشروا المشائين في الظلم إلى المساجد بالنور التام يوم القيامة».', 'The Messenger of Allah (ﷺ) said, "Convey glad tidings to those who walk to the mosque in the darkness. For they will be given full light on the Day of Resurrection.".', 'بريدة رضي الله عنه', 'Buraidah (May Allah be pleased with him)', null, 'رياض الصالحين 1058', 'Riyad as-Salihin 1058', 'ریاض الصالحین 1058', 'رواه أبو داود والترمذي', null, null, null, 'sunnah.com', null, false, null, false),
(21059, 2, 209, 1059, 'hadith', 'عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: "ألا أدلكم على ما يمحو الله به الخطايا، ويرفع به الدرجات؟ " قالوا بلى يا رسول الله. قال: "إسباغ الوضوء على المكاره، وكثرة الخطا إلى المساجد، وانتظار الصلاة بعد الصلاة، فذلكم الرباط، فذلكم الرباط".', 'The Messenger of Allah (ﷺ) said, "Shall I not tell you something by which Allah effaces the sins and elevates the ranks (in Jannah)." The Companions said: "Yes (please tell us), O Messenger of Allah." He said, "Performing the Wudu'' properly in spite of difficult circumstances, walking with more paces to the mosque, and waiting for the next Salat (prayer) after a observing Salat; and that is Ar-Ribat, and that is Ar-Ribat.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1059', 'Riyad as-Salihin 1059', 'ریاض الصالحین 1059', 'رواه مسلم', 'سَألَ النبيُّ صلى الله عليه وسلم أصحابَه هل يُريدون أنْ يدلَّهم على أعمال تكون سببًا في مغفرة الذنوب، ومحوها من كُتب الحفظة، وعلو المنازل في الجنة؟ 

قال الصحابة: نعم نريد ذلك. قال: 

الأول: استيعاب وإتمام الوضوء على مشقة؛ كَبردٍ، وقلة ماء، وألم جسم، وماء حار. 

الثاني: كثرة الخُطا -وهي ما بين القدمين- إلى المساجد ببعد الدار، وكثرة التكرار. 

الثالث: انتظار وقت الصلاة، وتعلُّق القلب بها، والتأهب لها، والجلوس لها في المسجد لانتظار الجماعة، فإذا صلاها انتظر في مصلاه صلاةً أخرى. 

ثم بيَّنَ صلى الله عليه وسلم أنَّ هذه الأمور هي المرابطة الحقيقية؛ لأنها تسد طرق الشيطان على النفس، وتقهر الهوى، وتمنعها من قبول الوساوس، فيغلب بها حزبُ الله جنودَ الشيطان؛ وذلك هو الجهاد الأكبر، فكانت بمنزلة الرباط على ثغر العدو.', 'أهمية المحافظة على صلاة الجماعة في المسجد، والاهتمام بالصلوات وعدم التشاغل عنها.
حسن عرض النبي صلى الله عليه وسلم وتشويقه لأصحابه حيث بدأهم بثواب عظيم على طريقة السؤال، وهذه طريقة من طرق التعليم.
فائدة عرض المسألة بالسؤال والجواب: أن يكون الكلام أوقع في النفس بحكم الإبهام والتبيين.
قال النووي رحمه الله: فذلكم الرباط أي: الرباط المرغَّب فيه، وأصل الرباط الحبس على الشيء، كأنه حبس نفسه على هذه الطاعة، وقيل: إنه أفضل الرباط كما قيل: الجهاد جهاد النفس، ويحتمل أنه الرباط المتيسر الممكن، أي: إنه من أنواع الرباط.
كررت كلمة "الرباط" وعرفت ب(ال) التعريف؛ ذلك تعظيمٌ لشأن هذه الأعمال.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3574', false),
(21060, 2, 209, 1060, 'hadith', 'عن أبي سعيد الخدري رضي الله عنه عن النبي صلى الله عليه وسلم قال: "إذا رأيتم الرجل يعتاد المساجد فاشهدوا له بالإيمان، قال الله عز وجل {إنما يعمر مساجد الله من آمن بالله واليوم الآخر}.', 'The Messenger of Allah (ﷺ) said, "When you see a man frequenting the mosque, testify that he is a believer because Allah says: ''Allah''s mosques are visited only by those who believe in Allah and the Last Day."''.', 'أبي سعيد الخدري رضي الله عنه', 'Abu Sa''id Al-Khudri (May Allah be pleased with him)', 'حسن', 'رياض الصالحين 1060', 'Riyad as-Salihin 1060', 'ریاض الصالحین 1060', 'الآية. رواه الترمذي وقال حديث حسن', null, null, null, 'sunnah.com', null, false, null, false),
(21061, 2, 209, 1061, 'hadith', 'عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «لا يزال أحدكم في صلاة مادامت الصلاة تحبسه لا يمنعه أن ينقلب إلى أهله إلا الصلاة».', 'The Messenger of Allah (ﷺ) said, "Everyone among you will be deemed to be occupied in Salat (prayer) constantly so long as Salat (the prayer) detains him (from worldly concerns), and nothing prevents him from returning to his family but Salat.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1061', 'Riyad as-Salihin 1061', 'ریاض الصالحین 1061', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21062, 2, 209, 1062, 'hadith', 'وعنه أن رسول الله صلى الله عليه وسلم قال: الملائكة تصلي على أحدكم ما دام في مصلاه الذي صلى فيه ما لم يحدث تقول اللهم اغفر له اللهم ارحمه".', 'The Messenger of Allah (ﷺ) said, "The angels supplicate in favour of one of you so long as he remains in the place where he has performed Salat (prayer) in a state of Wudu''. They (the angels) say: ''O Allah! Forgive him, O Allah! Have mercy on him."''.', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1062', 'Riyad as-Salihin 1062', 'ریاض الصالحین 1062', 'رواه البخاري', null, null, null, 'sunnah.com', null, false, null, false),
(21063, 2, 209, 1063, 'hadith', 'عن أنس رضي الله عنه أن رسول الله صلى الله عليه وسلم أخر ليلة صلاة العشاء إلى شطر الليل ثم أقبل علينا بوجهه بعدما صلى فقال: «صلى الناس ورقدوا ولم تزالوا في صلاة منذ انتظرتموها».', 'Once the Messenger of Allah (ﷺ) delayed the night prayer (''Isha'') till midnight. He (ﷺ) turned to us after Salat (prayer) and said, "The people slept after performing their Salat, but you who waited, will be accounted as engaged in Salat throughout the period of your waiting.".', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1063', 'Riyad as-Salihin 1063', 'ریاض الصالحین 1063', 'رواه البخاري', null, null, null, 'sunnah.com', null, false, null, false),
(21064, 2, 209, 1064, 'hadith', 'عن ابن عمر رضي الله عنهما أن رسول الله صلى الله عليه وسلم قال: "صلاة الجماعة أفضل من صلاة الفذ بسبع وعشرين درجة)).', 'The Messenger of Allah (ﷺ) said, "Salat in congregation is twenty-seven times more meritorious than a Salat performed individually.".', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1064', 'Riyad as-Salihin 1064', 'ریاض الصالحین 1064', 'متفق عليه', 'يشير هذا الحديث إلى بيان فضل صلاة الجماعة على صلاة المنفرد، بأن الجماعة -لما فيها من الفوائد العظيمة والمصالح الجسيمة- تفضل وتزيد على صلاة المنفرد بسبع وعشرين مرة من الثواب؛ لما بين العملين من التفاوت الكبير في القيام بالمقصود، وتحقيق المصالح، ولاشك أنَّ من ضيَّع هذا الربح الكبير محروم.', 'بيان فضل الصلاة مع الجماعة؛ مع ورود أدلة أخرى على وجوبها.
صحة صلاة المنفرد وإجزاؤها عنه؛ لأن لفظ "أفضل" في الحديث يدل عن أن كلا الصلاتين فيها فضل؛ ولكن تزيد إحداهما على الأخرى، وهذا في حق غير المعذور، أما المعذور فقد دلت النصوص على أن أجره تام.
الفرق الكبير في الثواب، بين صلاتي الجماعة والانفراد.', 'صلاة الجماعة : الصلاة في جماعة.
أفضل : أكثر فضلا، وأزيد أجرا.
الفَذّ : الفرد.
دَرَجَة : مرة.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3441', false),
(21065, 2, 209, 1065, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «صلاة الرجل في جماعة تُضعَّف على صلاته في بيته وفي سوقه خمسًا وعشرين ضعفًا، وذلك أنه إذا توضأ فأحسن الوضوء، ثم خرج إلى المسجد، لا يخرجه إلا الصلاة، لم يخطُ خطوة إلا رفعت له بها درجة، وحطت عنه بها خطيئة، فإذا صلى لم تزل الملائكة تصلي عليه ما دام في مصلاه، ما لم يحدث، تقول اللهم صلِّ عليه، اللهم ارحمه. ولا يزال في صلاة ما انتظر الصلاة».', 'The Messenger of Allah (ﷺ) said, "A man''s Salat in congregation is twenty-five times more rewarding than his Salat at home or in his shop, and that is because when he performs his Wudu'' properly and proceeds towards the mosque with the purpose of performing Salat in congregation, he does not take a step without being raised a degree (in rank) for it and having a sin remitted for it, till he enters the mosque. When he is performing Salat, the angels continue to invoke Blessings of Allah on him as long as he is in his place of worship in a state of Wudu''. They say: ''O Allah! Have mercy on him! O Allah! Forgive him.'' He is deemed to be engaged in Salat as long as he waits for it.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1065', 'Riyad as-Salihin 1065', 'ریاض الصالحین 1065', 'متفق عليه. وهذا لفظ البخاري', 'أخبر النبي صلى الله عليه وسلم بأن صلاة الرجل في جماعة تزيد أجرًا وثوابًا على صلاته في بيته وفي سوقه، أي: منفرداً كما يومىء إليه مقابلته بصلاة الجماعة؛ ولأن الغالب في فعلها في البيت والسوق الانفراد، ومقدار الزيادة خمسٌ وعشرون ضعفاً، وقوله: (وذلك) إن كان المشار إليه فضل صلاة الجماعة على صلاة الفذ اقتضى اختصاص ذلك بجماعة المسجد، وقوله: (أنه) أي الشأن أو الرجل إذا توضأ فأحسن الوضوء أي أسبغه مع الإتيان بالسنن والآداب ثم خرج إلى المسجد متوجهاً إليه لا يخرجه إلا الصلاة -فإن أخرجه إليه غيرها، أو هي مع غيرها فاته ما يأتي-: لم يخط خطوة إلا رفعت له بها درجة وحط عنه بها خطيئة، أي من الصغائر المتعلقة بحق الله تعالى ، فإذا صلى لم تزل الملائكة تصلي عليه تترحم وتستغفر له ما دام في مصلاه أي جالساً فيه، ويحتمل أن يراد ما دام مستمراً فيه ولو مضطجعاً، ما لم يحدث قول: (اللهم صل عليه اللهم ارحمه)، ولا يزال المصلي في صلاة ما انتظر الصلاة، أي: مدة انتظاره إياها.', 'فضيلة صلاة الجماعة في المسجد ومضاعفتها، وفضيلة الجماعة تحصل بأي عدد يصدق عليه معنى الجماعة، على أن كثرة العدد أدعى لحصول الزيادة في الثواب.
النقص في صلاة المنفرد وتأخرها في الفضل عن صلاة الجماعة.
كل هذا الفضل، من: رفعة الدرجات، وحَطِّ الخطايا، واستغفار الملائكة؛ مرتب على إحسان الوضوء، والخروج من البيت إلى المسجد؛ لقصد الصلاة بِنِيَّة خالصة، فالثواب المذكور مرتب على مجموع الأعمال، فلو خلا منه جزء لم يترتب عليه ما ذكر من الأجر.
فضيلة الوضوء والإخلاص.
أن ثواب من خرج متطهرًا للصلاة لا ينوي إلا الصلاة أن لا يخطو خطوة إلا رفعه الله بها درجة، وحط عنه بها خطيئة حتى يدخل إلى المسجد.
إثبات وجود الملائكة -عليهم الصلاة والسلام-.
دعاء الملائكة بالصلاة والمغفرة والرحمة لمن صلى في المسجد، ثم جلس ينتظر الصلاة.
أفضلية الصلاة على غيرها من الأعمال بعد الإيمان؛ لأن فيها صلاة الملائكة على فاعلها ودعاءهم له بالرحمة والمغفرة.
إن المنتظر الصلاة ثواب من هو في الصلاة.', 'صلاة الرجل : واحد الرجال، والمراد: الذكر دون الأنثى.
في جَماعة : مع جماعة.
تُضَعَّف : يُضَعِّفُها الله، أي: يزيدها.
صلاته في بيته : في داره.
وَفِي سُوقِهِ : محل تجارته، والغالب أن صلاته فيهما تكون بغير جماعة: لأن الجماعة تكون غالبًا في المسجد.
ضِعفًا : مثلا.
وذلك : أي: التضعيف.
أَنَّه : أي: لأنه.
فَأَحسَن الوُضُوء : أكمله على ما ورد عن النبي -صلى الله عليه وسلم-.
إلى المسجد : المكان المعد لإقامة الناس الجماعة فيه.
لاَ يُخرِجُهُ : أي: من بيته.
إلا الصلاة : أي: إلا إرادة الصلاة، دون إرادة شيء آخر.
لَم يَخْطُ بِها : لم يقدم رجله للمشي.
خُطوَةً : وهي ما بين قدمي الماشي حين مشيه، ويجوز خَطوَة على أنها واحدة الخطوات.
إِلاَّ رُفِعَت له : إلا رفع الله له.
بِها : بسببها.
دَرَجَة : منزلة عند الله -تعالى-.
حُطَّ عَنهُ : وضع الله عنه.
خَطِيئَة : سيئة، والمراد: عقوبة السيئة.
فَإِذَا صَلَّى : أي: تحية المسجد أو غيرها، مما يبادر به عند دخول المسجد.
لَم تَزَل : أي: تستمر الملائكة.
المَلاَئِكَة : والملائكة: وهم عالم غيبي، وربما يرون أحيانًا بإذن الله خلقهم الله من نور، فأكرمهم بالقيام بطاعته؛ فلا يعصون الله ما أمرهم ويفعلون ما يؤمرون، يسبحون الليل والنهار لا يفترون.
تُصَلِّي عَلَيه : تدعو له.
مَا دَامَ : أي مدة دوامه.
فِي مُصَلاَّه : في مكان صلاته.
اللهُمَّ صَلِّ عليه : اللهم اثن عليه في الملأ الأعلى، يعني: تقول: اللهم صل عليه... إلخ، وجملة تقول: بيان لجملة (تصلي عليه).
اللهم اغفِر له : استر ذنوبه مع التجاوز عنها.
ولا يَزَال فِي صلاة : أي: في ثواب صلاة.
ما انتَظَر : أي: مدة انتظاره.
الصلاة : أي: التي جاء للمسجد من أجلها.
صلاة : الصلاة في الشرع: عبادة ذات أقوال وأفعال معلومة، أولها التكبير وآخرها التسليم.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3435', false),
(21066, 2, 209, 1066, 'hadith', 'وعنه قال: أتى النبي صلى الله عليه وسلم رجل أعمي، فقال: يا رسول الله، ليس لي قائد يقودني إلى المسجد، فسأل رسول الله صلى الله عليه وسلم أن يرخص له فيصلي في بيته، فرخص له، فلما ولى دعاه فقال له: "هل تسمع النداء بالصلاة؟ " قال نعم، قال: "فأجب".', 'A blind man came to the Messenger of Allah (ﷺ) and said: "O Messenger of Allah! I have no one to guide me to the mosque." He, therefore, sought his permission to perform Salat (prayer) in his house. He (ﷺ) granted him permission. When the man turned away, he called him back, and said, "Do you hear the Adhan (call to prayer)?" He replied in the affirmative. The Messenger of Allah (ﷺ) then directed him to respond to it..', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1066', 'Riyad as-Salihin 1066', 'ریاض الصالحین 1066', 'رواه مسلم', 'أتَى رجُلٌ أعْمَى إلى النبيِّ صلى الله عليه وسلم، فقال: يا رسول الله ليس عندي مَن يُساعدني ويأخذ بيدي إلى المسجد، في الصلوات الخمس، يريد أنْ يُرخِّصَ له النبيُّ صلى الله عليه وسلم في ترك الجماعة، فَرَخَّصَ له، فلمَّا أَدْبَرَ ناداه وقال: هل تسمع الأذان بالصلاة؟ قال: نعم، قال: فأجب المُنادي بالصلاة.', 'وجوب صلاة الجماعة؛ لأن الرُّخصة لا تكون إلا من شيء لازم وواجب.
قوله: «فأجب» لمن يسمع النداء يدل على وجوب صلاة الجماعة؛ لأن الأصل بالأمر للوجوب.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/11287', false),
(21067, 2, 209, 1067, 'hadith', 'عن عبد الله- وقيل: عمرو بن قيس المعروف بابن أم مكتوم المؤذن رضي الله عنه أنه قال: يا رسول الله إن المدينة كثيرة الهوام والسباع. فقال رسول الله صلى الله عليه وسلم : «تسمع حي على الصلاة، حي على الفلاح، فحيهلا» ((رواه أبو داود بإسناد حسن. (12)', 'I said to the Messenger of Allah (ﷺ): "There are many poisonous insects and wild beasts in Al-Madinah, and I am blind. Please grant me permission to perform Salat at home." He (ﷺ) enquired whether he could hear the call: Hayya ''alas-Salah; Hayya ''alal-Falah (Come to the prayer, come to the salvation). When he replied in affirmative, the Messenger of Allah (ﷺ) directed him to come (to mosque) for prayer.".', 'عبد الله- وقيل: عمرو بن قيس المعروف بابن أم مكتوم المؤذن رضي الله عنه', '''Abdullah bin Umm Maktum, the Mu''adhdhin (May Allah be pleased with him)', null, 'رياض الصالحين 1067', 'Riyad as-Salihin 1067', 'ریاض الصالحین 1067', null, null, null, null, 'sunnah.com', null, false, null, false),
(21068, 2, 209, 1068, 'hadith', 'عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «والذي نفسي بيده، لقد هممت أن آمر بحطب فيحتطب، ثم آمر بالصلاة فيؤذن لها، ثم آمر رجلا فيؤم الناس، ثم أخالف إلى رجال فأحرق عليهم بيوتهم».', 'The Messenger of Allah (ﷺ) said, "By Him in Whose Hand my life is, I sometimes thought of giving orders for firewood to be collected, then for proclaiming the Adhan for Salat. Then I would appoint an Imam to lead Salat, and then go to the houses of those who do not come to perform Salat in congregation, and set fire to their houses on them.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1068', 'Riyad as-Salihin 1068', 'ریاض الصالحین 1068', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21069, 2, 209, 1069, 'hadith', 'عن ابن مسعود رضي الله عنه قال: من سره أن يلقى الله تعالى غدًا مسلمًا، فليحافظ على هؤلاء الصلوات، حيث ينادى بهن، فإن الله شرع لنبيكم صلى الله عليه وسلم سنن الهدى، وإنهن من سنن الهدى، ولو أنكم صليتم في بيوتكم كما يصلي هذا المتخلف في بيته لتركتم سنة نبيكم، ولو تركتم سنة نبيكم لضللتم، ولقد رأيتنا وما يتخلف عنها إلا منافق معلوم النفاق، ولقد كان الرجل يؤتى به، يهادى بين الرجلين حتى يقام في الصف.', 'He who likes to meet Allah tomorrow (i.e., on the Day of Requital) as a Muslim, should take care and observe the Salat when the Adhan is announced for them. Allah has expounded to your Prophet (ﷺ) the ways of right guidance, and these (the prayers) are part of the right guidance. If you have to perform Salat in your houses, as this man who stays away (from the mosque) and performs Salat in his house, you will abandon the Sunnah (practice) of your Prophet (ﷺ), and the departure from the Sunnah of your Prophet (ﷺ) will lead you astray. I have seen the time when no one stayed behind except a well-known hypocrite. I also saw that a man was brought swaying (on account of weakness) between two men till he was set up in a row (in the mosque)..', 'ابن مسعود رضي الله عنه', 'Ibn Mas''ud (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1069', 'Riyad as-Salihin 1069', 'ریاض الصالحین 1069', 'رواه مسلم وفي رواية له قال: إن رسول الله صلى الله عليه وسلم علمنا سنن الهدى، وإن من الهدى الصلاة في المسجد الذي يؤذن فيه', null, null, null, 'sunnah.com', null, false, null, false),
(21070, 2, 209, 1070, 'hadith', 'عن أبي الدرداء رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: «ما من ثلاثة في قرية ولا بدو لا تقام فيهم الصلاة إلا قد استحوذ عليهم الشيطان. فعليكم بالجماعة، فإنما يأكل الذئب من الغنم القاصية».', 'I heard the Messenger of Allah (ﷺ) saying, "If three men in a village or in the desert, make no arrangement for Salat in congregation, Satan must have certainly overcome them. So observe Salat in congregation, for the wolf eats up a solitary sheep that stays far from the flock.".', 'أبي الدرداء رضي الله عنه', 'Abud-Darda'' (May Allah be pleased with him)', 'حسن', 'رياض الصالحين 1070', 'Riyad as-Salihin 1070', 'ریاض الصالحین 1070', 'رواه أبو داود بإسناد حسن', null, null, null, 'sunnah.com', null, false, null, false),
(21071, 2, 209, 1071, 'hadith', 'عن عثمان بن عفان رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: «من صلى العشاء في جماعة، فكأنما قام نصف الليل ومن صلى الصبح في جماعة، فكانما صلى الليل كله».', 'I heard the Messenger of Allah (ﷺ) saying: "One who performs ''Isha'' prayer in congregation, is as if he has performed Salat for half of the night. And one who performs the Fajr prayer in congregation, is as if he has performed Salat the whole night."The narration of At-Tirmidhi says: ''Uthman bin Affan (May Allah be pleased with him) narrated that he had heard the Messenger of Allah (ﷺ) saying: "He who attends ''Isha'' in congregation, is as if he has performed Salat for half of the night; and he who attends ''Isha'' and Fajr prayers in congregation, is as if he has performed Salat for the whole night."', 'عثمان بن عفان رضي الله عنه', '''Uthman bin ''Affan (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1071', 'Riyad as-Salihin 1071', 'ریاض الصالحین 1071', 'رواه مسلم)). وفي رواية الترمذي عن عثمان بن عفان رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : "من شهد العشاء في جماعة كان له قيام نصف ليلة، ومن شهد العشاء والفجر في جماعة، كان له كقيام ليلة" ((قال الترمذي حديث حسن صحيح', null, null, null, 'sunnah.com', null, false, null, false),
(21072, 2, 209, 1072, 'hadith', 'عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «ولو يعلمون ما في العتمة والصبح لأتوهما ولو حبوًا» ((متفق عليه)). وقد سبق بطوله.', 'The Messenger of Allah (ﷺ) said, "If they knew the merits of Salat after nightfall (''Isha'') and the morning (Fajr) Salat, they would come to them even if they had to crawl to do so."This is part of a long Hadith which has already been mentioned. See Hadith No. 1033.', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', null, 'رياض الصالحين 1072', 'Riyad as-Salihin 1072', 'ریاض الصالحین 1072', null, null, null, null, 'sunnah.com', null, false, null, false),
(21073, 2, 209, 1073, 'hadith', 'وعنه قال: قال رسول الله صلى الله عليه وسلم : «ليس صلاة أثقل على المنافقين من صلاة الفجر والعشاء ولو يعلمون ما فيهما لأتوهما ولو حبوًا».', 'The Messenger of Allah (ﷺ) said, "No Salat is more burdensome to the hypocrites than the Fajr (dawn) prayer and the ''Isha'' (night) prayer; and if they knew their merits, they would come to them even if they had to crawl to do so.".', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1073', 'Riyad as-Salihin 1073', 'ریاض الصالحین 1073', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21074, 2, 209, 1074, 'hadith', 'عن ابن مسعود رضي الله عنه قال: سألت رسول الله صلى الله عليه وسلم : أي الأعمال أفضل؟ قال: "الصلاة على أوقتها" قلت: ثم أي؟ قال: "بر الوالدين" قلت ثم أي؟ قال: " الجهاد في سبيل الله".', 'I asked the Messenger of Allah (ﷺ): "Which act is the best?" He (ﷺ) said, "As-Salat at their fixed times." I asked, "What next?" He (ﷺ) said, "Being dutiful to parents." I asked, "What next?" He (ﷺ) said, "Striving (Jihad) in the way of Allah.".', 'ابن مسعود رضي الله عنه', 'Ibn Mas''ud (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1074', 'Riyad as-Salihin 1074', 'ریاض الصالحین 1074', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21075, 2, 209, 1075, 'hadith', 'عن ابن عمر رضي الله عنهما قال: قال رسول الله صلى الله عليه وسلم: « بني الإسلام على خمس: شهادة أن لا إله إلا الله وأن محمدًا رسول الله، وإقام الصلاة، وإيتاء الزكاة، وحج البيت، وصوم رمضان».', 'The Messenger of Allah (ﷺ) said, "Islam is based on five (pillars): testifying that there is no true god except Allah and that Muhammad (ﷺ) is His slave and Messenger; performing of Salat (Iqamat-as-Salat); the payment of Zakat; performing Hajj (pilgrimage) to the House .', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1075', 'Riyad as-Salihin 1075', 'ریاض الصالحین 1075', 'متفق عليه', 'شَبَّهَ النبيُّ صلى الله عليه وسلم الإسلامَ بِبِناءٍ مُحْكَمٍ بأركانه الخمسة الحاملة لذلك البُنيان، وبقية خصال الإسلام كتتمة البنيان، 
وأولُ هذه الأركان: الشهادتان؛ شهادة أن لا إله إلا الله وأنَّ محمدًا رسول الله، وهما ركن واحد؛ لا تنفك إحداهما عن الأخرى، ينطق العبد بهما معترفًا بوحدانية الله واستحقاقه للعبادة وحده دون ما سواه، وعاملًا بمقتضاها، ومؤمنًا برسالة محمد صلى الله عليه وسلم مُتَّبِعًا له. 
والركن الثاني: إقامة الصلاة، وهي الصلوات الخمس المفروضات في اليوم والليلة: الفجر، والظهر، والعصر، والمغرب، والعشاء، بشروطها وأركانها وواجباتها. 
والركن الثالث: إخراج الزكاة المفروضة، وهي عبادة ماليَّة واجبة في كل مال بَلَغَ قَدْرًا مُحَدّدًا في الشرع، تُعطى لمستحقيها. 
والركن الرابع: الحج، وهو قَصْدُ مكة لإقامة المَناسك، تَعبُّدًا لله عز وجل. 
والركن الخامس: صوم رمضان، وهو الإمساك عن الأكل والشرب وغيرهما من المفطرات بِنِيَّةِ التعبُّد لله، من طلوع الفجر إلى غروب الشمس.', 'تلازم الشهادتين، فلا تصح أحدهما إلا بالأخرى؛ لذا جعلهما ركنًا واحدًا.
الشهادتان هما أساس الدين، فلا يُقبل قولٌ ولا عملٌ إلا بهما.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65000', false),
(21076, 2, 209, 1076, 'hadith', 'وعنه قال: قال رسول الله صلى الله عليه وسلم «أمرت أن أقاتل الناس حتى يشهدوا أن لا إله إلا الله وأن محمدًا رسول الله، ويقيموا الصلاة ويؤتوا الزكاة، فإذا فعلوا ذلك، عصموا مني دماءهم وأموالهم إلا بحق الإسلام، وحسابهم على الله».', 'The Messenger of Allah (ﷺ) said, "I have been commanded to fight against the people till they testify La ilaha illAllah (There is no true god except Allah) and that Muhammad (ﷺ) is His slave and Messenger, and to establish As-Salat (Iqamat-as-Salat), and to pay Zakat; and if they do this, then their blood and property are secured except by the rights of Islam, and their accountability is left to Allah.".', null, 'Ibn ''Umar (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1076', 'Riyad as-Salihin 1076', 'ریاض الصالحین 1076', 'متفق عليه', 'يُخْبِرُ النبيُّ صلى الله عليه وسلم أنَّ اللهَ أمرَه بمقاتلة المشركين حتى يشهدوا بأن لا معبود بحق إلا الله وحده لا شريك له، ويشهدوا لمحمد صلى الله عليه وسلم بالرسالة، والعمل بمقتضى هذه الشهادة من المحافظة على الصلوات الخمس في اليوم والليلة، ويعطوا الزكاة المفروضة لمستحقيها. 
فإذا فعلوا هذه الأمورَ فإنَّ الإسلام يَعْصِمُ دماءَهم وأموالَهم، فلا يَحِلُّ قتلُهم إلا إذا ارتكبوا جريمة أو جناية يستحقون عليها القتل بموجب أحكام الإسلام، ثم يوم القيامة يتولى الله تعالى حسابَهم حيث يعلم سرائرَهم.', 'الأحكام إنما تَجْرِي على الظواهر، والله يتولَّى السرائر.
أهمية الدعوة إلى التوحيد وأنه أول ما يُبدأ به في الدعوة.
لا يعني هذا الحديث إكراه المشركين على الدخول في الإسلام، بل هم مُخَيَّرون بين الدخول في الإسلام أو دفع الجزية؛ فإنْ أبوا إلا مَنع الدعوة إلى الإسلام، فليس إلا المقاتلة بموجب أحكام الإسلام.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4211', false),
(21077, 2, 209, 1077, 'hadith', 'عن معاذ رضي الله عنه قال: بعثني رسول الله صلى الله عليه وسلم إلى اليمن فقال: «إنك تأتي قومًا من أهل الكتاب، فادعهم إلى شهادة أن لا إله إلا الله وأني رسول الله، فإن هم أطاعوا لذلك، فأعلمهم أن الله تعالى افترض عليهم خمس صلوات في كل يوم وليلة، فإن هم أطاعوا لذلك، فأعلمهم أن الله تعالى افترض عليهم صدقة تؤخذ من أغنيائهم فترد على فقرائهم، فإن هم اطاعوا لذلك، فإياك وكرائم أموالهم واتقِ دعوة المظلوم فإنه ليس بينها وبين الله حجاب».', 'The Messenger of Allah (ﷺ) sent me as a governor to Yemen and (at the time of departure) he instructed me thus: "You will go to people of the Scripture (i.e., the Jews and the Christians). First of all invite them to testify that La ilaha ill Allah (There is no true god except Allah) and that Muhammad (ﷺ) is His slave and Messenger; and if they accept this, then tell them that Allah has enjoined upon them five Salat (prayers) during the day and night; and if they accept it, then tell them that Allah has made the payment of Zakat obligatory upon them. It should be collected from their rich and distributed among their poor; and if they agree to it, don''t take (as a share of Zakat) the best of their properties. Beware of the supplications of the oppressed, for there is no barrier between it and Allah.".', 'معاذ رضي الله عنه', 'Mu''adh (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1077', 'Riyad as-Salihin 1077', 'ریاض الصالحین 1077', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21078, 2, 209, 1078, 'hadith', 'عن جابر رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: «إن بين الرجل وبين الشرك والكفر ترك الصلاة».', 'The Messenger of Allah (ﷺ) said, "Between a man and disbelief and paganism is the abandonment of Salat (prayer).".', 'جابر رضي الله عنه', 'Jabir (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1078', 'Riyad as-Salihin 1078', 'ریاض الصالحین 1078', 'رواه مسلم', 'حَذَّرَ النبيُّ صلى الله عليه وسلم مِن تَرْكِ الصلاة المفروضة، وأخبر أنَّ بَين الرجلِ وبين الوقوعِ في الشرك والكفر تركَ الصلاة، فالصلاةُ الركنُ الثاني من أركان الإسلام، وشأنُها عظيمٌ في الإسلام، فمَن تَرَكَها جاحدًا لوجوبها كَفَرَ بإجماع المسلمين، وإنَّ تركها بالكلية تهاونًا وكسلًا فهو كافر، ونُقل إجماع الصحابة على ذلك، وإنَّ كان يترك أحيانًا ويُصلّي أحيانًا فهو مُعَرَّض لهذا الوعيد الشديد.', 'أهميَّة الصلاة والمحافظة عليها، فهي الفارق بين الكفر والإيمان.
 التحذير الشديد من ترك الصلاة وإضاعتها.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65093', false),
(21079, 2, 209, 1079, 'hadith', 'عن بريدة رضي الله عنه عن النبي صلى الله عليه وسلم قال: «العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر».', 'Messenger of Allah (ﷺ) said, "That which differentiates us from the disbelievers and hypocrites is our performance of Salat. He who abandons it, becomes a disbeliever.".', 'بريدة رضي الله عنه', 'Buraidah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1079', 'Riyad as-Salihin 1079', 'ریاض الصالحین 1079', 'رواه الترمذي وقال: حديث حسن صحيح', 'بَيَّنَ النبيُّ صلى الله عليه وسلم أنَّ العهدَ والميثاقَ بين المسلمين وبين غيرهم من الكفار والمنافقين الصلاةُ، فمَن تَرَكَها فقد كَفَر.', 'عِظَم شأن الصلاة، وأنّها الفارق بين المؤمن والكافر.
ثبوت أحكام الإسلام بالظاهر من حال الرجل دون باطنه.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65094', false),
(21080, 2, 209, 1080, 'hadith', 'عن شقيق بن عبد الله التابعي المتفق على جلالته رحمه الله قال: كان أصحاب محمد صلى الله عليه وسلم لا يرون شيئًا من الأعمال تركه كفر غير الصلاة.', 'The Companions of the Messenger of Allah (ﷺ) did not consider the abandonment of any action as disbelief except neglecting Salat..', null, 'Shaqiq bin ''Abdullah', 'صحيح', 'رياض الصالحين 1080', 'Riyad as-Salihin 1080', 'ریاض الصالحین 1080', 'رواه الترمذي في كتاب الإيمان بإسناد صحيح', null, null, null, 'sunnah.com', null, false, null, false)
on conflict (id) do update set collection_id = excluded.collection_id, chapter_id = excluded.chapter_id, number_in_book = excluded.number_in_book, kind = excluded.kind, arabic = excluded.arabic, translation_en = excluded.translation_en, narrator_ar = excluded.narrator_ar, narrator_en = excluded.narrator_en, grade_ar = excluded.grade_ar, reference_ar = excluded.reference_ar, reference_en = excluded.reference_en, reference_ur = excluded.reference_ur, full_ref_ar = excluded.full_ref_ar, explanation_ar = excluded.explanation_ar, benefits_ar = excluded.benefits_ar, word_meanings_ar = excluded.word_meanings_ar, source = excluded.source, source_ref = excluded.source_ref, daily_ok = excluded.daily_ok, review_note = excluded.review_note, deleted = false;

insert into hadith (id, collection_id, chapter_id, number_in_book, kind, arabic, translation_en, narrator_ar, narrator_en, grade_ar, reference_ar, reference_en, reference_ur, full_ref_ar, explanation_ar, benefits_ar, word_meanings_ar, source, source_ref, daily_ok, review_note, deleted) values
(21081, 2, 209, 1081, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «إن أول ما يحاسب به العبد يوم القيامة من عمله صلاته، فإن صلحت، فقد أفلح وأنجح، وإن فسدت، فقد خاب وخسر، فإن انتقص من فريضته شيئًا، قال الرب، عز وجل: انظروا هل لعبدي من تطوع، فيكمل منها ما انتقص من الفريضة؟ ثم يكون سائر أعماله على هذا».', 'The Messenger of Allah (ﷺ) said, "The first of man''s deeds for which he will be called to account on the Day of Resurrection will be Salat. If it is found to be perfect, he will be safe and successful; but if it is incomplete, he will be unfortunate and a loser. If any shortcoming is found in the obligatory Salat, the Glorious and Exalted Rubb will command to see whether His slave has offered any voluntary Salat so that the obligatory Salat may be made up by it. Then the rest of his actions will be treated in the same manner.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'حسن', 'رياض الصالحين 1081', 'Riyad as-Salihin 1081', 'ریاض الصالحین 1081', 'رواه الترمذي وقال حديث حسن', null, null, null, 'sunnah.com', null, false, null, false),
(21082, 2, 209, 1082, 'hadith', 'عن جابر بن سمرة، رضي الله عنهما، قال: خرج علينا رسول الله صلى الله عليه وسلم فقال: "ألا تصفون كما تصف الملائكة عند ربها؟" فقلنا: يا رسول الله وكيف تصف الملائكة عند ربها؟ قال: "يتمون الصفوف الأُول، ويتراصون في الصف".', 'The Messenger of Allah (ﷺ) came out to us (once) and said, "Why do you not stand in rows as the angels do before their Rubb?" We asked: "O Messenger of Allah! how do the angels stand in rows before their Rubb?" He (ﷺ) replied, "They complete each row beginning with the first and filling all the gaps.".', 'جابر بن سمرة رضي الله عنهما', 'Jabir bin Samurah (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1082', 'Riyad as-Salihin 1082', 'ریاض الصالحین 1082', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21083, 2, 209, 1083, 'hadith', 'عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «لو يعلم الناس ما في النداء والصف الأول، ثم لم يجدوا إلا أن يستهموا عليه لاستهموا».', 'The Messenger of Allah (ﷺ) said, "If people came to know the blessing of calling Adhan and the standing in the first row, they could do nothing but would draw lots to secure these privileges.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1083', 'Riyad as-Salihin 1083', 'ریاض الصالحین 1083', 'متفق عليه', 'أخبر النبيُّ صلى الله عليه وسلم أن الناس لو يعلمون ما في الأذان والصف الأول من الفضيلة والخير والبركة ثم لم يجدوا من وجوه التقديم والأولوية لها إلا أن يقترعوا عليهما أيهم يستحق على صاحبه لاقترعوا، ولو يعلمون ما في التبكير إلى الصلاة في أول وقتها لاستبقوا إليه، ولو يعلمون مقدار الثواب في إتيان صلاة العشاء وصلاة الفجر لاستسهل إتيانهما ولو حبوًا على الرُّكَب كما يمشي الصبي أول أمْرِه.', 'بيان فضيلة الأذان.
بيان فضيلة الصف الأول، والقُرْب من الإمام.
بيان فضيلة التبكير إلى الصلاة في أول وقتها المستحب؛ لِما فيه من الفضل العظيم، وما يترتب عليه من الفوائد، ومنها: إدراك الصف الأول، وإدراك الصلاة من أولها، وأداء النافلة، وقراءة القرآن، وحصول استغفار الملائكة له، وأنه لا يزال في صلاة ما انتظر الصلاة، وغير ذلك.
الحث العظيم على حضور جماعة هاتين الصلاتين، والفضل الكثير في ذلك لما فيهما من المشقة على النفس من تَنْغِيْص أول نومها وآخره، ولهذا كانتا أثقل الصلاة على المنافقين. ‏
قال النووي: فيه إثبات القرعة في الحقوق التي يزدحم عليها ويتنازع فيها. ‏
الصف الثاني أفضل من الثالث، والثالث أفضل من الرابع، وهلم جرًّا.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65735', false),
(21084, 2, 209, 1084, 'hadith', 'وعنه قال: قال رسول الله صلى الله عليه وسلم: «خير صفوف الرجال أولها، وشرها آخرها، وخير صفوف النساء آخرها، وشرها أولها».', 'The Messenger of Allah (ﷺ) said, "The best of the men''s rows (in Salat) is the first row and the worst is the last; but the best of the woman''s row is the last and the worst of their rows is the first.".', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1084', 'Riyad as-Salihin 1084', 'ریاض الصالحین 1084', 'رواه مسلم', 'أَخْبَرَ النبيُّ صلى الله عليه وسلم أنّ خيرَ صفوف الرجال في الصلاة وأكثرها ثوابًا وفضلًا أولُها؛ لقربهم من الإمام واستماعهم لقراءته وبُعْدِهم من النساء، 
وشرّها وأقلّها ثوابًا وفضلًا وأبعدها من مطلوب الشرع آخرها، 
وخير صفوف النساء آخرها؛ لأنه أسترُ لهن، وأبعد من مخالطة الرجال ورؤيتهم والفتنة بهم، وشرها أولها؛ لقربها من الرجال والتعرض للفتنة.', 'حث الرجال على المسارعة إلى الطاعات والصفوف الأولى في الصلوات.
جواز صلاة النساء في المسجد مع الرِّجال في صفوف مستقلة، لكن مع التَّستُّر والحِشْمَة.
النَّساء إذا اجتمعن في المسجد، فإنهن يَكُنَّ صفوفًا، كصفوف الرِّجال، ولا يتفرقن، بل عليهن التَّراص في الصّف وسدّ الخلل، كما في صفوف الرجال.
بيان شدة عناية الشرع بالحث بابتعاد النساء عن الرجال حتى في مواطن العبادة.
تفاضل الناس بحسب أعمالهم.
قال النووي: أما صفوف الرجال فهي على عمومها، فخيرها أولُها أبدًا، وشرها آخرها أبدًا، أما صفوف النساء فالمراد بالحديث: صفوف النساء اللواتي يصلين مع الرجال، وأما إذا صلين متميزات لا مع الرجال فهن كالرجال؛ خير صفوفهن أولُها وشرُّها آخرُها.
قال النووي: الصف الأول الممدوح الذي قد وردت الأحاديث بفضله والحث عليه هو الصف الذي يلي الإمام؛ سواء جاء صاحبه متقدِّمًا أو متأخرًا، وسواء تخلله مقصورة ونحوها أم لا.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/11299', false),
(21085, 2, 209, 1085, 'hadith', 'عن أبي سعيد الخدري، رضي الله عنه أن رسول الله صلى الله عليه وسلم رأي في أصحابه تأخرًا، فقال لهم: «تقدموا فَأتموا بي وليأتم بكم مَن بعدكم، لا يزال قوم يتأخرون حتى يؤخرهم الله».', 'When the Messenger of Allah (ﷺ) perceived a tendency among his Companions to stand in the back rows, he said to them, "Come forward and be close to me and let those who come after you, follow your lead. If people continue to fall behind (i.e., in acquiring virtues), Allah puts them behind.".', 'أبي سعيد الخدري رضي الله عنه', 'Abu Sa''id Al-Khudri (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1085', 'Riyad as-Salihin 1085', 'ریاض الصالحین 1085', 'رواه مسلم', 'يبين الحديث الشريف فضل الدنو من الإمام ، كما يبين أن الصفوف المتأخرة تأتم بالصفوف القريبة من الإمام ، كما توعد المتأخرين في الصفوف الخلفية بالتأخر عن رحمته أو عظيم فضله ورفع المنزلة وعن العلم ونحو ذلك.', 'استحباب الدنو من الإمام، فأوائل الصفوف خير للرجال من أواخرها؛ لحديث: "خير صفوف الرجال أولها"، ولحديث: "لو يعلم الناس ما في الصف الأول، لاستهموا عليه".
أنَّ الإمام هو القدوة في الصلاة في جميع أعمالها وأقوالها، فلا يُخْتَلَف عليه فيها.
في الصلاة الانضباط والنظام الإسلامي؛ ليتعود المسلمون على حسن التنظيم، وجمال الترتيب، والامتثال والطاعة بالمعروف، فهو من جملة أسرار صلاة الجماعة.
أنَّ المامومين الذين لا يرون الإمام، ولا يسمعونه، يقتدون بمن أمامهم من المأمومين المتقدمين.
قوله: "وليأتم بكم من بعدكم" يحتمل أن يراد به الاقتداء في الصلاة، فيليه العلماء ثم العقلاء، والصف الثاني يقتدون بالصف الأول.ويحتمل حمل العلم عنه في غير الصلاة، فليتعلم منه -صلى الله عليه وسلم- الصحابة، وليتعلم منهم التابعون، وهكذا.
الدنو من الإمام والقرب من الصف الأول له جملة من الفوائد والمصالح، وهي: أنه ينوب عن الإمام إذا عرض له عارض، ومنها: أنه يقتدي بصلاة إمامه ويستفيد منه، لا سيما إذا كان الإمام فقيهاً.
قال الإمام النووي: يشترط لصحة الاقتداء علم المأموم بانتقالات الإمام؛ سواء صلاها في المسجد، أو غيره بالإجماع، ويحصل العلم له بذلك بسماع الإمام، أو من خلفه، أو جواز اعتماد واحد من هذه الأمور، واشترط النووي -رحمه الله- ألا تطول المسافة في غير مسجد، وهو قول جمهور العلماء.', 'تأخرًا : أي: تخلفًا، وبُعْدًا في صفوف الصلاة.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/11291', false),
(21086, 2, 209, 1086, 'hadith', 'عن أبي مسعود رضي الله عنه قال: كان رسول الله صلى الله عليه وسلم يمسح مناكبنا في الصلاة، ويقول: «استووا ولا تختلفوا فتختلف قلوبكم، ليلني منكم أولو الأحلام والنهى، ثم الذين يلونهم ثم الذين يلونهم».', 'The Messenger of Allah (ﷺ) used to gently pat our shoulders when we were standing in rows at the time of Salat and say, "Keep (the rows) straight; do not differ from each other lest your hearts should suffer from discord. Let those of you who are mature and prudent be nearer to me, and then those who are next to them.".', 'أبي مسعود رضي الله عنه', 'Abu Mas''ud (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1086', 'Riyad as-Salihin 1086', 'ریاض الصالحین 1086', 'رواه مسلم', 'أخبر أبو مسعود رضي الله عنه أن النبي صلى الله عليه وسلم كان يضع يده على مناكبهم قبيل الصلاة للتسوية وحتى لا يتقدم بعضهم على بعض أو يتأخر، فكان يراعي تسويتهم للصفوف عند القيام للصلاة ويتعهد ذلك، ويقول وهو يسوي المناكب: اعتدلوا في صفوفكم بألا يتقدم بعضكم على بعض، ولا تختلفوا في إقامة الصفوف بالأبدان بالتقدم والتأخر، فتختلف بذلك قلوبكم، وليقرب مني البالغون وأصحاب العقول الراجحة، وليدن مني العلماء النجباء وذوو السكينة والوقار، أمرهم به؛ ليحفظوا صلاته، ويضبطوا الأحكام والسنن، فيبلغوا من بعدهم، ثم الذين يقربون منهم في هذا الوصف، الذين يقاربون الأولين في النهى والحلم ثم الذين يقربون منهم، كالصبيان المميزين، أو الذين هم أنزل مرتبة من المتقدمين حلمًا وعقلًا، ثم قال أبو مسعود: فأنتم اليوم بسبب عدم تسويتكم الصفوف أشدُّ اختلافًا.', 'وجوب تسوية الصفوف، وعدم الاختلاف فيها؛ لأنه جاء به الأمر، وترتب عليه الوعيد.
شدة الاهتمام النبي صلى الله عليه وسلم بتسوية الصفوف، وتولي ذلك بنفسه.
أن عدم تسوية الصفوف يترتب عليه الاختلاف القلبي، فيستولي بسببه على المجتمع البغضاء، والتنافر، والتحاسد، وعدم توحيد الكلمة.
أهل الفضل لهم حق التقدم في مجالس الخير والتكريم على حسب مراتبهم.
بيان فضل العصر النبوي، إذ كان وقت تناصح، وتوافق، واتحاد كلمة، وقليل التنازع والاختلاف، وإنما جاء الاختلاف، واشتد بعده صلى الله عليه وسلم كما بينه أبو مسعود رضي الله عنه في هذا الكلام.
من حكم إقامة الصفوف حصول الاستقامة والاعتدال ظاهرًا، كما هو المطلوب باطنًا، ولئلا يتخللهم الشيطان، فيفسد صلاتهم بالوسوسة، وما في ذلك من حسن الهيئة، وتمكنهم من صلاتهم مع كثرة جمعهم، فإذا تراصوا وسع جميعهم المسجد، وإذا لم يفعلوا ذلك ضاق عنهم.', 'مناكبنا: المناكب: جمع منكب، وهو مابين الكتف والعنق.
ليلني: ليدنُ ويقرب بأن يكونوا خلفي في الصف.
أولو الأحلام والنهى: أصحاب العقول.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65741', false),
(21087, 2, 209, 1087, 'hadith', 'عن أنس، رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: "سووا صفوفكم، فإن تسوية الصف من تمام الصلاة". ((متفق عليه)) وفي رواية البخاري: "فإن تسوية الصفوف من إقامة الصلاة".', 'The Messenger of Allah (ﷺ) said, "Keep your rows straight (during Salat in congregation), for keeping the rows straight is part of the perfection of Salat.".', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1087', 'Riyad as-Salihin 1087', 'ریاض الصالحین 1087', null, 'يَأْمُرُ النبيُّ صلى الله عليه وسلم المصلين إلى أن يُسووا صفوفَهم، وأن لا يتقدم بعضهم على بعض ولا يتأخر، وأن تسويتها من تمام الصلاة وكمالها، وأنّ اعوجاج الصف خللٌ ونقص فيها.', 'مشروعية العناية بكل ما يُكمل الصلاة ويبعدها عن النقص.
حكمة النبي صلى الله عليه وسلم في التعليم، حيث قَرَن الحُكم مع عِلَّته؛ لتتبين حكمة التشريع، وتنشط النفوس على الامتثال.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3031', false),
(21088, 2, 209, 1088, 'hadith', 'وعنه قال: أقيمت الصلاة، فأقبل علينا رسول الله صلى الله عليه وسلم بوجهه فقال: "أقيموا صفوفكم وتراصوا، فإني أراكم من وراء ظهري" ((رواه البخاري بلفظه، ومسلم بمعناه)). وفي رواية للبخاري: وكان أحدنا يلزق منكبه بمنكب صاحبه وقدمه بقدمه".', 'When the Iqamah had been announced, the Messenger of Allah (ﷺ) turned his face towards us and said: "Make your rows straight and stand close together, for I can see you from behind my back.".', null, 'Anas (May Allah be pleased with him)', null, 'رياض الصالحين 1088', 'Riyad as-Salihin 1088', 'ریاض الصالحین 1088', null, null, null, null, 'sunnah.com', null, false, null, false),
(21089, 2, 209, 1089, 'hadith', 'عن النعمان بن بشير رضي الله عنهما، قال: سمعت رسول الله صلى الله عليه وسلم يقول: "لتسون صفوفكم، أو ليخالفن الله بين وجوهكم" ((متفق عليه)) وفي رواية لمسلم: أن رسول الله صلى الله عليه وسلم كان يسوي صفوفنا حتى كأنما يسوي بها القداح، حتى رأى أنا قد عقلنا عنه. ثم خرج يومًا فقام حتى كاد يكبر، فرأى رجلا باديا صدره من الصف، فقال "عباد الله لتسون صفوفكم، أو ليخالفن الله بين وجوهكم".', 'I heard the Messenger of Allah (ﷺ) saying, "Straighten your rows; otherwise, Allah will create dissension among you.".The narration in Muslim is: An-Nu''man bin Bashir (May Allah be pleased with them) said: The Messenger of Allah (ﷺ) directed us to keep our rows as straight as arrows. He continued stressing this until he realized that we had learnt it from him (recognized its significance). One day he came into the mosque and stood up. He was just about to say Takbir (Allah is Greater) when he noticed a man whose chest was projected from the row, so he said, "O slaves of Allah, you must straighten your rows or Allah will certainly put your faces in opposite directions."', 'النعمان بن بشير رضي الله عنهما', 'An-Nu''man bin Bashir (May Allah be pleased with them)', null, 'رياض الصالحين 1089', 'Riyad as-Salihin 1089', 'ریاض الصالحین 1089', null, null, null, null, 'sunnah.com', null, false, null, false),
(21090, 2, 209, 1090, 'hadith', 'عن البراء بن عازب رضي الله عنهما، قال كان رسول الله صلى الله عليه وسلم يتخلل من ناحية إلى ناحية، يمسح صدورنا ومناكبنا ويقول،: "لا تختلفوا فتختلف قلوبكم" وكان يقول: "إن الله وملائكته يصلون على الصفوف الأُول".', 'The Messenger of Allah (ﷺ) used to pass between the rows from one end to the other, touching our chest and shoulders (i.e., arranging the rows) in line and saying, "Do not be out of line; otherwise your hearts will be in disagreement". He would add, "Allah and His angels invoke blessings upon the first rows.".', 'البراء بن عازب رضي الله عنهما', 'Al-Bara'' bin ''Azib (May Allah be pleased with them)', 'حسن', 'رياض الصالحين 1090', 'Riyad as-Salihin 1090', 'ریاض الصالحین 1090', 'رواه أبو داود بإسناد حسن', null, null, null, 'sunnah.com', null, false, null, false),
(21091, 2, 209, 1091, 'hadith', 'عن ابن عمر رضي الله عنهما، أن رسول الله صلى الله عليه وسلم قال: «أقيموا الصفوف، وحاذوا المناكب، وسدوا الخلل، ولينوا بأيدي إخوانكم، ولا تذروا فرجات للشيطان، ومن وصل صفًا وصله الله، ومن قطع صفًا قطعه الله».', 'The Messenger of Allah (ﷺ) said, "Arrange the rows in order, stand shoulder to shoulder, close the gaps, be accommodating to your brothers, and do not leave gaps for Satan. Whoever joins up a row, he will be joined to Allah (i.e., to the Mercy of Allah); and whoever cuts off a row, he will be cut off from Allah (i.e., from His Mercy).".', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1091', 'Riyad as-Salihin 1091', 'ریاض الصالحین 1091', 'رواه أبو داود بإسناد صحيح', 'أخبر عبد الله بن عمر رضي الله عنهما أن النبي صلى الله عليه وسلم أمرهم بإتمام الصفوف ومساواتها في الصلاة والمقاربة بينها، وبيَّن الوسائل التي يتحقق بها ذلك، فتكون المساواة بأن يكون منكب كلِّ إنسانٍ مقابلًا لمنكب الذي بجواره، وأن يسدوا الأماكن التي فيها خلل وفجوة، بأن لا يتركوا فُرجًا ومسافات بين الصفوف، وإنما يجعلوها متراصة متقاربة، وإذا جاء رجل إلى الصف فذهب ليدخل فيه فينبغي أن يلين له كل رجل منكبيه حتى يدخل في الصف، فيتحرك إذا طُلب منه، ويتعاون مع إخوانه في تسوية الصفوف، ونهاهم أن يتركوا فرجات بينهم، فإن الشيطان يدخل من خلالها، ويعجبه ذلك؛ لأن هذا يخالف تسوية الصفوف الذي أمر الله تعالى به، والذي أمر به رسوله صلى الله عليه وسلم، ولأن ذلك يؤدي إلى أن الله يخالف بين وجوهكم وقلوبكم، وهذه من الأشياء التي يريدها الشيطان ويحبها، فأضافها إليه، وأخبر أن من وصل صفًّا بسدِّ الفرجات والتَّراصِّ المنتظم فإن الله يصله بالثواب وحسن الجزاء، ومن قطع صفًّا بأن يتسبب في الخلل والفرجات، ويتكون الفرجة بجواره ولا يسدها ولا يتحرك لإصلاح الصف يقطعه الله من الثواب ويعاقبه.', 'التحريض على إقامة وتسوية الصفوف.
النهي والوعيد الشديد في عدم إتمام الصفوف وإكمالها.
بيان ثواب من يصل الصفوف، وعقاب من يقطعها.
شناعة الفرجات بين المصلين وذلك لإضافتها للشيطان.', 'أقيموا الصفوف: ساووها وأتموها وقاربوا بينها.
حاذوا: الحَذْوُ والحِذَاء: الإزاء والمُقابِل.
المناكب: جمع مَنكِب، وهو مابين الكتف والعنق.
سدوا الخلل: أغلقوا المسافات بينكم.
لا تذروا: لا تتركوا.
فرجات: جمع فرجة، والمقصود الخلل الذي يكون بين المصلين في الصفوف.
للشيطان: أضافها للشيطان؛ تفظيعًا لشأنها، وحملًا على الاحتراز منها.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65737', false),
(21092, 2, 209, 1092, 'hadith', 'عن أنس، رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «رصوا صفوفكم، وقاربوا بينها وحاذوا الأعناق فوالذي نفسي بيده إني لأرى الشيطان يدخل من خلل الصف، كأنها الحذف».', 'The Messenger of Allah (ﷺ) said, "Stand close together in your rows, keep nearer to one another, and put your necks in line, for by Him in Whose Hands my soul is, I see the Satan entering through the opening in the row like Al- hadhaf (i.e., a type of small black sheep found in Yemen).".', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1092', 'Riyad as-Salihin 1092', 'ریاض الصالحین 1092', 'حديث صحيح رواه أبو داود بإسناد على شرط مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21093, 2, 209, 1093, 'hadith', 'وعنه أن رسول الله صلى الله عليه وسلم قال: «أتموا الصف المقدم، ثم الذي يليه، فما كان من نقص فليكن في الصف المؤخر».', 'The Messenger of Allah (ﷺ) said, "Fill (complete) the first row, then the one next to it; and if there is any deficiency (incompleteness), it should be in the last row.".', null, 'Anas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1093', 'Riyad as-Salihin 1093', 'ریاض الصالحین 1093', 'رواه أبو داود بإسناد حسن', 'أَمَرَ النبيُّ صلى الله عليه وسلم الرجال المصلين جماعة بإكمال الصف الأول، ثم بتكميل الصف الذي يليه، وهكذا، فإذا وجد نقص في صف فليكن هذا النقص في الصف الأخير.', 'بيان السنة في تسوية الصفوف.
على المصلين ألا يتركوا النقص في الصفوف المقدمة، بل يكون النقص في الصف الأخير.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65738', false),
(21094, 2, 209, 1094, 'hadith', 'عن عائشة رضي الله عنها، قالت: قال رسول الله صلى الله عليه وسلم: «إن الله وملائكته يصلون على ميامن الصفوف».', 'The Messenger of Allah (ﷺ) said, "Allah and His angels invoke blessings upon those who are on the right side of the rows.".', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her)', null, 'رياض الصالحين 1094', 'Riyad as-Salihin 1094', 'ریاض الصالحین 1094', 'رواه أبو داود بإسناد على شرط مسلم، وفيه رجل مختلف في توثيقه', null, null, null, 'sunnah.com', null, false, null, false),
(21095, 2, 209, 1095, 'hadith', 'عن البراء، رضي الله عنه قال: "كنا إذا صلينا خلف رسول الله صلى الله عليه وسلم ، أحببنا أن نكون عن يمينه، يقبل علينا بوجهه، فسمعته يقول: "رب قني عذابك يوم تبعث - أو تجمع- عبادك".', 'Whenever we performed Salat behind the Messenger of Allah (ﷺ), we liked to be on his right side so that his face might turn towards us (at the end of the Salat). One day, I heard Messenger of Allah (ﷺ) supplicating, "O my Rubb! Shield me from Your Torment on the Day when You will gather (or said, ''resurrect'') Your slaves.".', 'البراء رضي الله عنه', 'Al-Bara'' (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1095', 'Riyad as-Salihin 1095', 'ریاض الصالحین 1095', 'رواه مسلم', 'قال البراء رضي الله عنه: كنا معاشر الصحابة رضي الله عنهم إذا أردنا الصلاة خلف رسول الله صلى الله عليه وسلم أحببنا أن نكون من جهة يمينه حال استقباله القبلةعليه الصلاة والسلام، وإنما أحببنا أن نكون عن يمينه؛ لأنه صلى الله عليه وسلم يُقبل علينا بوجهه الشريف عند الانصراف من الصلاة، وهذا في بعض الأحيان، وكان أيضًا صلى الله عليه وسلم إذا انصرف أن يستقبل جميعهم بوجهه، قال سمرة بن جندب: كان النبي صلى الله عليه وسلم إذا صلى صلاة أقبل علينا بوجهه. بوب عليه البخاري: (باب يستقبل الإمام الناس إذا سلم)، وقال البراء رضي الله عنه: فسمعته صلى الله عليه وسلم يقول: رب احفظني وسلمني من عذابك يوم القيامة الذي تجمع عبادك فيه للحساب، تبعث، وقوله: (أو تجمع) تردُّدٌ من أحد الرواة، وعليه فينوِّع الإنسان بين اللفظين.', 'استحباب إقبال الإمام على المأمومين بعد التسليم، وعدم الإطالة في استقبال القبلة.
بيان استحباب الوقوف عن يمين الإمام، ووجه دلالة الحديث عليه أن محبة الصحابة رضي الله عنهم لذلك، ومسابقتهم إليه كان بعلم من النبي صلى الله عليه وسلم، فلو كان الفضل في غير اليمين لبيَّنه لهم.
بيان ما كان عليه الصحابة رضي الله عنهم من شدة محبتهم للنبي صلى الله عليه وسلم، فكانوا يتسابقون في القيام عن يمينه صلى الله عليه وسلم في الصلاة، حتى يشاهدوا طلعته، ويقع بصره عليهم قبل غيرهم ممن وقف في غير اليمين.', 'أن نكون عن يمينه: أن نقف في يمين الصف.
يقبل علينا بوجهه: أي بعد فراغه من الصلاة يلتفت علينا جهة اليمين بوجهه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65746', false),
(21096, 2, 209, 1096, 'hadith', 'عن أبي هريرة رضي الله عنه قال قال رسول الله صلى الله عليه وسلم: «وسطوا الإمام، وسدوا الخلل».', 'The Messenger of Allah (ﷺ) said, "Let the Imam stand in the middle (so that those praying behind him should be standing both on his right and his left) and close the gaps.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', null, 'رياض الصالحين 1096', 'Riyad as-Salihin 1096', 'ریاض الصالحین 1096', 'رواه أبو داود', null, null, null, 'sunnah.com', null, false, null, false),
(21097, 2, 209, 1097, 'hadith', 'عن أم المؤمنين أم حبيبة رملة بنت أبي سفيان، رضي الله عنهما، قالت سمعت رسول الله صلى الله عليه وسلم، يقول: ما من عبد مسلم يصلي لله تعالى كل يوم ثنتي عشرة ركعة تطوعًا غير الفريضة، إلا بنى الله له بيتًا في الجنة أو: إلا بني له بيت في الجنة".', 'I heard the Messenger of Allah (ﷺ) saying, "A house will be built in Jannah for every Muslim who offers twelve Rak''ah of optional Salat other than the obligatory Salat in a day and a night (to seek the Pleasure of Allah).".', 'أم المؤمنين أم حبيبة رملة بنت أبي سفيان رضي الله عنهما', 'Umm Habibah (May Allah be pleased with her) the Mother of the Believers', 'صحيح', 'رياض الصالحين 1097', 'Riyad as-Salihin 1097', 'ریاض الصالحین 1097', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21098, 2, 209, 1098, 'hadith', 'عن ابن عمر رضي الله عنهما، قال: صليت مع رسول الله صلى الله عليه وسلم، ركعتين قبل الظهر وركعتين بعدها، وركعتين بعد الجمعة، وركعتين بعد المغرب، وركعتين بعد العشاء".', 'I performed along with the Messenger of Allah (ﷺ) two Rak''ah of optional prayers before Zuhr and two after the Zuhr (noon prayer), and two after the Friday prayer, and two after the Maghrib (evening) prayer, and two after the ''Isha'' (night) prayer.".', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1098', 'Riyad as-Salihin 1098', 'ریاض الصالحین 1098', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21099, 2, 209, 1099, 'hadith', 'عن عبد الله بن مغفل، رضي الله عنه، قال: قال رسول الله صلى الله عليه وسلم: "بين كل أذانين صلاة، بين كل أذانين صلاة، بين كل أذانين صلاة" وقال في الثالثة: "لمن شاء".', 'The Messenger of Allah (ﷺ) said, "There is a Salat (prayer) between every Adhan and Iqamah; there is a Salat between every Adhan and Iqamah." (While saying the same for the) third time (he (ﷺ) added), "It is for him who desires (to perform it).".', 'عبد الله بن مغفل رضي الله عنه', '''Abdullah bin Mughaffal (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1099', 'Riyad as-Salihin 1099', 'ریاض الصالحین 1099', 'متفق عليه', 'بَيَّنَ النبيُّ صلى الله عليه وسلم أنَّ بَيْنَ كلِّ أذانٍ وإقامةٍ صلاةُ نافلةٍ، وكرَّر ذلك ثلاثًا، وأخبر في الثالثة أن ذلك مُستحبٌّ لِمَن أراد أن يصلي.', 'استحباب الصلاة بين الأذان والإقامة.
هدي النبي صلى الله عليه وسلم في تكرار القول، وذلك إسماعًا وتأكيدًا لأهمية ما يقول.
المراد بالأذانين: الأذان والإقامة، وأطلق عليهما (الأذانَين) تغليبًا، كالقمرين (الشمس والقمر) والعُمَرَيْن (أبي بكر وعمر).
الأذان إعلام بدخول الوقت، والإقامة إعلام بحضور فعل الصلاة.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65479', false),
(21100, 2, 209, 1100, 'hadith', 'عن عائشة رضي الله عنها، أن النبي صلى الله عليه وسلم كان لا يدع أربعًا قبل الظهر، وركعتين قبل الغداة.', 'The Prophet (ﷺ) never omitted four Rak''ah prayer before the Zuhr prayer and two Rak''ah prayers before dawn (Fajr) prayer..', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 1100', 'Riyad as-Salihin 1100', 'ریاض الصالحین 1100', 'رواه البخاري', 'أَخْبَرَت عائشةُ رضي الله عنها أنَّ النبيَّ صلى الله عليه وسلم كان يُواظِب على صلوات النوافل في بيتها ولا يَدَعُها: أربع ركعات بتسليمتين قبل صلاة الظهر، وركعتان قبل صلاة الفجر.', 'استحباب المحافظة على أربع ركعات قبل صلاة الظهر، وركعتين قبل صلاة الفجر.
الأفضل أن تصلى الرَّواتِب في البيت، ولذلك أخبرت عنها عائشة رضي الله عنها.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/11249', false),
(21101, 2, 209, 1101, 'hadith', 'وعنها قالت: لم يكن النبي، صلى الله عليه وسلم على شيء من النوافل أشد تعاهدًا منه على ركعتي الفجر".', 'The Prophet (ﷺ) did not attach more importance to any Nawafil prayer than the two Rak''ah of prayer before dawn (Fajr) prayer..', null, '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 1101', 'Riyad as-Salihin 1101', 'ریاض الصالحین 1101', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21102, 2, 209, 1102, 'hadith', 'وعنها عن النبي صلى الله عليه وسلم قال: «ركعتا الفجر خير من الدنيا وما فيها» ((رواه مسلم)). وفي رواية لهما لأحب إلي من الدنيا جميعًا.', 'The Prophet (ﷺ) said, "The two Rak''ah before the dawn (Fajr) prayer are better than this world and all it contains."Another narration goes: "The two Rak''ah before the dawn (Fajr) prayer are dearer to me than the whole world."', null, '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 1102', 'Riyad as-Salihin 1102', 'ریاض الصالحین 1102', null, 'علَّمنا النبي صلى الله عليه وسلم أن ركعتي السُّنَّة القبلية لصلاة الفجر أفضل من الدنيا وما فيها من أثاث ومتاع وسائر الأموال والمُلك والخدم، وأجرهما خير من أن يُعطى المصلي تمام الدنيا بدلا عنهما.', 'الحث على المحافظة على الركعتين قبل الفجر، وبيان أجرهما.', 'ركعتا الفجر: السنة القبلية لصلاة الفجر.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/66400', false),
(21103, 2, 209, 1103, 'hadith', 'عن أبي عبد الله بلال بن رباح، رضي الله عنه مؤذن رسول الله صلى الله عليه وسلم أنه أتى رسول الله صلى الله عليه وسلم ليؤذنه بصلاة الغداة، فشغلت عائشة بلالا بأمر سألته عنه، حتى أصبح جدا فقام بلال فآذنه بالصلاة، وتابع أذانه، فلم يخرج رسول الله صلى الله عليه وسلم فلما خرج صلى بالناس، فأخبره أن عائشة شغلته بأمر سألته عنه حتى أصبح جدا، وأنه أبطأ عليه بالخروج، فقال -يعني النبي صلى الله عليه وسلم -: "إني كنت ركعت ركعتي الفجر" فقال: يا رسول الله إنك أصبحت جدا؟ فقال: "لو أصبحت أكثر مما أصبحت، لركعتهما وأحسنتهما، وأجملتهما".', 'I went to inform the Messenger of Allah (ﷺ) about the time of the dawn (Fajr) prayer, and ''Aishah (May Allah be pleased with her) kept me busy and began to ask me about something till the day grew bright. Then I got up and informed the Messenger of Allah (ﷺ) of the time of Salat. I informed him again but he did not came out immediately to lead As- Salat. When he came out, he led As-Salat. I said to him: ''Aishah (May Allah be pleased with her) kept me busy and thus diverted my attention by asking about something and the morning grew bright. You also came out late. Upon that the Messenger of Allah (ﷺ) said, "I was engaged in performing two Rak''ah of Fajr prayer." Bilal (May Allah be pleased with him)said: "O Messenger of Allah! You delayed As-Salat so long as the morning grew bright." He (ﷺ) replied, "Even if the morning had become brighter than it had, I would have performed two Rak''ah of prayer in an excellent manner.".', 'أبي عبد الله بلال بن رباح رضي الله عنه', 'Abu ''Abdullah Bilal bin Rabah (May Allah be pleased with him) the Mu''adhdhin of Messenger of Allah (ﷺ)', 'حسن', 'رياض الصالحين 1103', 'Riyad as-Salihin 1103', 'ریاض الصالحین 1103', 'رواه أبو داود بإسناد حسن', null, null, null, 'sunnah.com', null, false, null, false),
(21104, 2, 209, 1104, 'hadith', 'عن عائشة رضي الله عنها أن رسول الله صلى الله عليه وسلم، كان يصلي ركعتين خفيفتين بين النداء والإقامة من صلاة الصبح". ((متفق عليه)) وفي رواية لهما: يصلي ركعتي الفجر، إذا سمع الأذان فيخففهما حتى أقول هل قرأ فيهمابأم القرآن!. وفي رواية لمسلم: كان يصلى ركعتيي الفجر إذا سمع الأذان ويخففهما. وفي رواية: إذا طلع الفجر.', 'The Prophet (ﷺ) used to perform two Rak''ah short prayer between the Adhan (call to prayer) and the Iqamah of the dawn (Fajr) prayers.In the narration of Muslim, ''Aishah (May Allah be pleased with her) said: When the Messenger of Allah (ﷺ) used to hear the Adhan (of Fajr prayer) he would perform two supererogatory Rak''ah prayer and would make them short.', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her)', null, 'رياض الصالحين 1104', 'Riyad as-Salihin 1104', 'ریاض الصالحین 1104', null, null, null, null, 'sunnah.com', null, false, null, false),
(21105, 2, 209, 1105, 'hadith', 'عن حفصة رضي الله عنها أن رسول الله صلى الله عليه وسلم كان إذا أذن المؤذن للصبح، وبدا الصبح صلى ركعتين خفيفتين. ((متفق عليه)). وفي رواية لمسلم: كان رسول الله صلى الله عليه وسلم إذا طلع الفجر لا يصلى إلا ركعتين خفيفتين.', 'The Messenger of Allah (ﷺ) used to perform two short Rak''ah prayer when it was dawn and the Mu''adhdhin had called Adhan (for the Fajr prayer)..', 'حفصة رضي الله عنها', 'Hafsah (May Allah be pleased with her)', null, 'رياض الصالحين 1105', 'Riyad as-Salihin 1105', 'ریاض الصالحین 1105', null, null, null, null, 'sunnah.com', null, false, null, false),
(21106, 2, 209, 1106, 'hadith', 'عن ابن عمر رضي الله عنهما قال: كان رسول الله صلى الله عليه وسلم يصلي من الليل مثنى مثنى، ويوتر بركعة من آخر الليل، ويصلي الركعتين قبل صلاة الغداة، وكأن الأذان بأذنيه".', 'The Messenger of Allah (ﷺ) used to perform his optional night prayers at night, two Rak''ah followed by two Rak''ah, and at the end he would conclude with an odd Rak''ah (Witr). Then he would perform two Rak''ah prayer before the dawn (Fajr) prayer after hearing the Adhan, and he would make them so brief as if he could hear the Iqamah being called..', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1106', 'Riyad as-Salihin 1106', 'ریاض الصالحین 1106', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21107, 2, 209, 1107, 'hadith', 'عن ابن عباس رضي الله عنهما أن رسول الله صلى الله عليه وسلم، كان يقرأ في ركعتي الفجر في الأولى منهما: {قولوا آمنا بالله وما أنزل إلينا} الآية التي في البقرة، وفي الآخرة منهما: {آمنا بالله واشهد بأنا مسلمون}. وفي رواية: في الآخرة التي في آل عمران: {تعالوا إلى كلمة سواء بيننا وبينكم}.', 'The Messenger of Allah (ﷺ) used to recite during the two Rak''ah of Fajr prayer: "Say (O Muslims): We believe in Allah and that which has been sent down to us..." (2:136) which is in Surat Al-Baqarah in the first Rak''ah and the Verse: "We believe in Allah, and bear witness that we are Muslims (i.e., we submit to Allah." (3:52) in the second Rak''ah.According to another narration, he (ﷺ) recited from Surat Al-''Imran the Verses: "Come to a word which is just between us and you..." (3:64)..', 'ابن عباس رضي الله عنهما', 'Ibn ''Abbas (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1107', 'Riyad as-Salihin 1107', 'ریاض الصالحین 1107', 'رواهما مسلم', 'روى ابن عباس أن رسول الله صلى الله عليه وسلم كان يقرأ في ركعتي الفجر أي: في السنة القبلية في بعض الأحيان، في الركعة الأولى قوله تعالى: {قولوا آمنا بالله وما أنزل إلينا} [البقرة: 136] الآية أي: يقرأ الآية بتمامها، والمراد بعد قراءة الفاتحة؛ لما تقرر من الأدلة أن الصلاة لا تصح بدونها، وفي الركعة الثانية: {آمنا بالله واشهد بأنا مسلمون} [آل عمران: 52] أي: يقرأ الآية المشتملة على هذا الكلام، وهي قوله تعالى: {فلما أحس عيسى منهم الكفر قال من أنصاري إلى الله قال الحواريون نحن أنصار الله آمنا بالله واشهد بأنا مسلمون}.
وفي رواية عنه قال: كان رسول الله صلى الله عليه وسلم يقرأ في ركعتي الفجر في الركعة الأولى: {قولوا آمنا بالله وما أنزل إلينا} [البقرة: 136]، وفي الركعة الثانية الآية التي في آل عمران: {تعالوا إلى كلمة سواء بيننا وبينكم} [آل عمران: 64]، ويحتمل أن يكون في بعض الأوقات يقرأ هذه وفي بعضها يقرأ هذه.', 'بيان الآيات التي كان يقرأها النبي صلى الله عليه وسلم في صلاة الفجر.

جواز الاستدلال بجزء من الآية.', 'ركعتي الفجر: سنة الفجر.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65447', false),
(21108, 2, 209, 1108, 'hadith', 'عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم، قرأ في ركعتي الفجر: {قل يا أيها الكافرون} و{قل هو الله أحد}.', 'The Messenger of Allah (ﷺ) recited in the two supererogatory Rak''ah of the Fajr prayer Surat Al-Kafirun (No. 109) .', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1108', 'Riyad as-Salihin 1108', 'ریاض الصالحین 1108', 'رواه مسلم', 'كَانَ النبيُّ صلى الله عليه وسلّم يَسْتَحِبُّ أنْ يقرأ في ركعتي راتبة الفجر بعد الفاتحة، في الركعة الأولى سورة {قل يا أيها الكافرون} (الكافرون)، وفي الركعة الثانية سورة {قل هو الله أحد} (الإخلاص).', 'استحباب قراءة هاتين السورتين بعد الفاتحة في سنة الفجر.
هاتان السورتان يقال لهما سورة الإخلاص؛ لأن في سورة الكافرون البراءة من جميع ما يعبده المشركون من دون الله، وأنهم أيضًا ليسوا بعبيد لله لأن شركهم يحبط أعمالهم، وأن الله سبحانه هو المستحق العبادة، ولأن في سورة الإخلاص توحيد الله والإخلاص له وبيان صفاته.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/11256', false),
(21109, 2, 209, 1109, 'hadith', 'عن ابن عمر رضي الله عنهما، قال رمقت النبي صلى الله عليه وسلم شهرًا يقرأ في الركعتين قبل الفجر: {قل يا أيها الكافرون}، و: {قل هو الله أحد}.', 'I observed the Prophet (ﷺ) for one month reciting in the two supererogatory Rak''ah of the Fajr prayer Surat Al-Kafirun (No. 109) .', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them)', 'حسن', 'رياض الصالحين 1109', 'Riyad as-Salihin 1109', 'ریاض الصالحین 1109', 'رواه الترمذي وقال: حديث حسن', null, null, null, 'sunnah.com', null, false, null, false),
(21110, 2, 209, 1110, 'hadith', 'عن عائشة رضي الله عنها قالت: كان النبي صلى الله عليه وسلم إذا صلى ركعتي الفجر، اضطجع على شقه الأيمن.', 'When the Prophet (ﷺ) had performed two Rak''ah before the Fajr prayer, he would lie down on his right side..', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 1110', 'Riyad as-Salihin 1110', 'ریاض الصالحین 1110', 'رواه البخاري', null, null, null, 'sunnah.com', null, false, null, false),
(21111, 2, 209, 1111, 'hadith', 'وعنها قالت: كان النبي صلى الله عليه وسلم يصلي فيما بين أن يفرغ من صلاة العشاء إلى الفجر إحدى عشرة ركعة يسلم بين كل ركعتين، ويوتر بواحدة، فإذا سكت المؤذن من صلاة الفجر، وتبين له الفجر وجاء المؤذن، قام فركع ركعتين خفيفتين، ثم اضطجع على شقه الأيمن هكذا حتى يأتيه المؤذن للإقامة". ((رواه مسلم)). (15)', 'When the Prophet (ﷺ) finished the ''Isha prayer, he would perform eleven Rak''ah before the Fajr prayer, concluding each two Rak''ah with Taslim (i.e., saying As-Salamu ''Alaikum) and observing the Witr (odd) at the end. When the Mu''adhdhin finished proclaiming Adhan for the Fajr prayer and it was dawn, he would rise and perform two short Rak''ah, and then would lie down on his right side till the Mu''adhdhin came to (inform) him about Iqamah..', null, '''Aishah (May Allah be pleased with her)', null, 'رياض الصالحين 1111', 'Riyad as-Salihin 1111', 'ریاض الصالحین 1111', null, null, null, null, 'sunnah.com', null, false, null, false),
(21112, 2, 209, 1112, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «إذا صلى أحدكم ركعتي الفجر، فليضطجع على يمينه». ((رواه أبو داود، والترمذي بأسانيد صحيحة. قال الترمذي: حديث حسن صحيح.', 'The Messenger of Allah (ﷺ) said, "When anyone of you has performed two of Sunnah before the Fajr prayer, he should lie down on his right side.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', null, 'رياض الصالحين 1112', 'Riyad as-Salihin 1112', 'ریاض الصالحین 1112', null, null, null, null, 'sunnah.com', null, false, null, false),
(21113, 2, 209, 1113, 'hadith', 'عن ابن عمر رضي الله عنهما قال: صليت مع رسول الله صلى الله عليه وسلم ركعتين قبل الظهر، وركعتين بعدها.', 'I performed with the Messenger of Allah (ﷺ) two Rak''ah before and two after Zuhr prayers..', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1113', 'Riyad as-Salihin 1113', 'ریاض الصالحین 1113', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21114, 2, 209, 1114, 'hadith', 'عن عائشة رضي الله عنها أن النبي صلى الله عليه وسلم كان لا يدع أربعًا قبل الظهر.', 'The Prophet (ﷺ) never omitted four Rak''ah supererogatory prayer before Zuhr prayers..', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 1114', 'Riyad as-Salihin 1114', 'ریاض الصالحین 1114', 'رواه البخاري', 'أَخْبَرَت عائشةُ رضي الله عنها أنَّ النبيَّ صلى الله عليه وسلم كان يُواظِب على صلوات النوافل في بيتها ولا يَدَعُها: أربع ركعات بتسليمتين قبل صلاة الظهر، وركعتان قبل صلاة الفجر.', 'استحباب المحافظة على أربع ركعات قبل صلاة الظهر، وركعتين قبل صلاة الفجر.
الأفضل أن تصلى الرَّواتِب في البيت، ولذلك أخبرت عنها عائشة رضي الله عنها.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/11249', false),
(21115, 2, 209, 1115, 'hadith', 'وعنها قالت: كان النبي صلى الله عليه وسلم يصلي في بيتي قبل الظهر أربعًا، ثم يخرج فيصلي بالناس، ثم يدخل فيصلي ركعتين، وكان يصلي بالناس المغرب ثم يدخل بيتي فيصلي ركعتين، ويصلي بالناس العشاء، ويدخل بيتي، فيصلي ركعتين.', 'Whenever the Prophet (ﷺ) stayed in my house, he would perform four Rak''ah (supererogatory prayer) before Zuhr prayer. Then he would go out and lead Salat. He (ﷺ) would then come back and perform two Rak''ah (supererogatory prayer). He would lead the Maghrib prayer and come back and perform two Rak''ah (supererogatory prayer). When he (ﷺ) had led the ''Isha'' prayer, he would enter the house and perform two Rak''ah (supererogatory prayer).', null, '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 1115', 'Riyad as-Salihin 1115', 'ریاض الصالحین 1115', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21116, 2, 209, 1116, 'hadith', 'عن أم حبيبة رضي الله عنها قالت: قال رسول الله صلى الله عليه وسلم: «من حافظ على أربع ركعات قبل الظهر وأربع بعدها، حرمه الله على النار». ((رواه أبو داود، والترمذي)). وقال حديث حسن صحيح.', 'The Messenger of Allah (ﷺ) said, "Whoever observes the practice of performing four Rak''ah before Zuhr prayer and four after the Zuhr prayer, Allah will shield him against the Fire (of Hell)..', 'أم حبيبة رضي الله عنها', 'Umm Habibah (May Allah be pleased with her)', null, 'رياض الصالحين 1116', 'Riyad as-Salihin 1116', 'ریاض الصالحین 1116', null, null, null, null, 'sunnah.com', null, false, null, false),
(21117, 2, 209, 1117, 'hadith', 'عن عبد الله بن السائب، رضي الله عنه أن رسول الله صلى الله عليه وسلم كان يصلى أربعًا بعد أن تزول الشمس قبل الظهر، وقال «إنها ساعة تفتح فيها أبواب السماء، فأحب أن يصعد لي فيها عمل صالح».', 'The Messenger of Allah (ﷺ) used to perform four Rak''ah prayer after the declining of the sun before Zuhr prayer and would say, "This is an hour at which the gates of heaven are opened, and I like that my good deeds should rise to heaven at that time.".', 'عبد الله بن السائب رضي الله عنه', '''Abdullah bin As-Sa''ib (May Allah be pleased with him)', 'حسن', 'رياض الصالحين 1117', 'Riyad as-Salihin 1117', 'ریاض الصالحین 1117', 'رواه الترمذي وقال: حديث حسن', null, null, null, 'sunnah.com', null, false, null, false),
(21118, 2, 209, 1118, 'hadith', 'عن عائشة رضي الله عنها أن النبي صلى الله عليه وسلم كان إذا لم يصلِ أربعًا قبل الظهر، صلاهن بعدها.', 'If the Prophet (ﷺ) could not perform four Rak''ah before Zuhr prayer, he would perform them after it (i.e., after the obligatory prayer)..', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her)', 'حسن', 'رياض الصالحين 1118', 'Riyad as-Salihin 1118', 'ریاض الصالحین 1118', 'رواه الترمذي وقال: حديث حسن', null, null, null, 'sunnah.com', null, false, null, false),
(21119, 2, 209, 1119, 'hadith', 'عن علي بن أبي طالب، رضي الله عنه قال كان النبي صلى الله عليه وسلم يصلي قلب العصر أربع ركعات يفصل بينهن بالتسليم على الملائكة المقربين ومن تبعهم من المسلمين والمؤمنين. رواه الترمذي وقال حديث حسن.', 'The Prophet (ﷺ) used to perform four Rak''ah before the ''Asr prayer, separating them with Taslim (i.e., offering blessings) on the favourite angels who are near Allah''s proximity and the Muslims and the believers who come after them..', 'علي بن أبي طالب رضي الله عنه', '''Ali bin Abu Talib (May Allah be pleased with him)', null, 'رياض الصالحين 1119', 'Riyad as-Salihin 1119', 'ریاض الصالحین 1119', null, null, null, null, 'sunnah.com', null, false, null, false),
(21120, 2, 209, 1120, 'hadith', 'عن ابن عمر، رضي الله عنهما، عن النبي صلى الله عليه وسلم، قال: «رحم الله امرءًا صلى قبل العصر أربعًا».', 'The Prophet (ﷺ) said, "May Allah have mercy on a man who performs four Rak''ah before the ''Asr prayer.".', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them)', 'حسن', 'رياض الصالحين 1120', 'Riyad as-Salihin 1120', 'ریاض الصالحین 1120', 'رواه أبو داود والترمذي وقال: حديث حسن', null, null, null, 'sunnah.com', null, false, null, false)
on conflict (id) do update set collection_id = excluded.collection_id, chapter_id = excluded.chapter_id, number_in_book = excluded.number_in_book, kind = excluded.kind, arabic = excluded.arabic, translation_en = excluded.translation_en, narrator_ar = excluded.narrator_ar, narrator_en = excluded.narrator_en, grade_ar = excluded.grade_ar, reference_ar = excluded.reference_ar, reference_en = excluded.reference_en, reference_ur = excluded.reference_ur, full_ref_ar = excluded.full_ref_ar, explanation_ar = excluded.explanation_ar, benefits_ar = excluded.benefits_ar, word_meanings_ar = excluded.word_meanings_ar, source = excluded.source, source_ref = excluded.source_ref, daily_ok = excluded.daily_ok, review_note = excluded.review_note, deleted = false;

insert into hadith (id, collection_id, chapter_id, number_in_book, kind, arabic, translation_en, narrator_ar, narrator_en, grade_ar, reference_ar, reference_en, reference_ur, full_ref_ar, explanation_ar, benefits_ar, word_meanings_ar, source, source_ref, daily_ok, review_note, deleted) values
(21121, 2, 209, 1121, 'hadith', 'عن علي بن أبي طالب رضي الله عنه أن النبي صلى الله عليه وسلم كان يصلي قبل العصر ركعتين.".', 'The Prophet (ﷺ) used to perform two Rak''ah before the ''Asr prayer..', 'علي بن أبي طالب رضي الله عنه', '''Ali bin Abu Talib (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1121', 'Riyad as-Salihin 1121', 'ریاض الصالحین 1121', 'رواه أبو داود بإسناد صحيح', null, null, null, 'sunnah.com', null, false, null, false),
(21122, 2, 209, 1122, 'hadith', 'عن عبد الله بن مغفل، رضي الله عنه عن النبي صلى الله عليه وسلم قال: "صلوا قبل المغرب" قال في الثالثة: "لمن شاء".', 'The Prophet (ﷺ) said, "Perform two Rak''ah before Maghrib prayer." He (ﷺ) repeated it twice; when repeating it for the third time he added: "He who may so wish.".', 'عبد الله بن مغفل رضي الله عنه', '''Abdullah bin Mughaffal (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1122', 'Riyad as-Salihin 1122', 'ریاض الصالحین 1122', 'رواه البخاري', null, null, null, 'sunnah.com', null, false, null, false),
(21123, 2, 209, 1123, 'hadith', '- وعن أنس، رضي الله عنه قال: لقد رأيت كبار أصحاب رسول الله صلى الله عليه وسلم يبتدرون السواري عند المغرب.', 'I saw the principal Companions of Messenger of Allah (ﷺ) rushing to the pillars (of the mosque) to perform two Rak''ah prayers behind them before the Maghrib prayer..', null, 'Anas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1123', 'Riyad as-Salihin 1123', 'ریاض الصالحین 1123', 'رواه البخاري', null, null, null, 'sunnah.com', null, false, null, false),
(21124, 2, 209, 1124, 'hadith', 'وعنه قال: كنا نصلي على عهد رسول الله صلى الله عليه وسلم ركعتين بعد غروب الشمس قبل المغرب، فقيل: أكان رسول الله صلى الله عليه وسلم صلاها؟ قال: كان يرانا نصليهما فلم يأمرنا ولم ينهنا".', 'In the lifetime of the Messenger of Allah (ﷺ), we used to perform two Rak''ah (optional prayer) after sunset before the Maghrib prayer. It was asked: "Did Messenger of Allah (ﷺ) perform them?" He replied: "He saw us performing it, but he neither ordered us to perform them nor did he forbid us from doing so.".', null, 'Anas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1124', 'Riyad as-Salihin 1124', 'ریاض الصالحین 1124', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21125, 2, 209, 1125, 'hadith', 'وعنه قال: كنا بالمدينة فإذا أذن المؤذن لصلاة المغرب ابتدروا السواري، فركعوا ركعتين، حتى إن الرجل الغريب ليدخل المسجد فيحسب أن الصلاة قد صليت من كثرة من يصليهما.', 'When we were in Al-Madinah, the moment the Mu''adhdhin finished the Adhan of the Maghrib prayer, the people hastened to the pillars of the mosque and performed two Rak''ah prayer behind them. A stranger coming into the mosque would think that the obligatory prayer had already been performed because of the number of people performing them..', null, 'Anas bin Malik (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1125', 'Riyad as-Salihin 1125', 'ریاض الصالحین 1125', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21126, 2, 209, 1126, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «إذا صلى أحدكم الجمعة، فليصلِ بعدها أربعًا».', 'The Messenger of Allah (ﷺ) said, "If anyone of you performs the Friday prayer, he should perform four Rak''ah (Sunnah) after it.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1126', 'Riyad as-Salihin 1126', 'ریاض الصالحین 1126', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21127, 2, 209, 1127, 'hadith', 'عن ابن عمر رضي الله عنهما، أن النبي صلى الله عليه وسلم كان لا يصلي بعد الجمعة حتى ينصرف، فيصلي ركعتين في بيته.', 'The Prophet (ﷺ) would not perform any Salat (in the mosque) after the Friday prayer till he had returned to his house. He would then perform two Rak''ah there..', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1127', 'Riyad as-Salihin 1127', 'ریاض الصالحین 1127', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21128, 2, 209, 1128, 'hadith', 'عن زيد بن ثابت رضي الله عنه أن النبي صلى الله عليه وسلم قال: «صلوا أيها الناس في بيوتكم، فإن الصلاة صلاة المرء في بيته إلا المكتوبة».', 'The Prophet (ﷺ) said, "O people! perform your (voluntary) Salat (prayers) in your homes because the best Salat of a man is the one he performs at home, except the obligatory Salat.".', 'زيد بن ثابت رضي الله عنه', 'Zaid bin Thabit (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1128', 'Riyad as-Salihin 1128', 'ریاض الصالحین 1128', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21129, 2, 209, 1129, 'hadith', 'عن ابن عمر رضي الله عنهما عن النبي صلى الله عليه وسلم قال: اجلعوا من صلاتكم في بيوتكم، ولا تتخذوها قبورًا".', 'The Prophet (ﷺ) said, "Observe part of the .', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1129', 'Riyad as-Salihin 1129', 'ریاض الصالحین 1129', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21130, 2, 209, 1130, 'hadith', 'عن جابر رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «إذا قضى أحدكم صلاته في مسجده، فليجعل لبيته نصيبًا من صلاته، فإن الله جاعل في بيته صلاته خيرًا».', 'The Messenger of Allah (ﷺ) said, "When you have finished your (Fard) Salat (prayer) in the mosque, you should observe some of your (Sunnah and Nawafil) Salat at home; Allah will bless your homes because of your Salat (in your homes)."', 'جابر رضي الله عنه', 'Jabir (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1130', 'Riyad as-Salihin 1130', 'ریاض الصالحین 1130', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21131, 2, 209, 1131, 'hadith', 'عن عمر بن عطاء أن نافع بن جبير أرسله إلى السائب ابن أخت نمر يسأله عن شيء رآه منه معاوية في الصلاة فقال: نعم صليت معه الجمعة في المقصورة، فلما سلم الإمام، قمت في مقامي، فصليت فلما دخل أرسل إلي فقال: لا تعد لما فعلت: إذا صليت الجمعة فلا تصلها بصلاة حتى تتكلم أو تخرج، فإن رسول الله صلى الله عليه وسلم أمرنا بذلك أن لا نوصل صلاة بصلاة حتى نتكلم أو نخرج.', '"Yes, I performed the Friday prayer along with him in the enclosure (Maqsurah), and when the Imam concluded the Salat with Taslim, I stood up in my place and performed the Sunnah prayer. When Mu''awiyah went home, he sent for me (and when I came) he said: "Never do again what you have done. When you have observed the Friday prayer, you must not start another Sunnah prayer till you have spoken to some one or have shifted your place; because the Messenger of Allah (ﷺ) ordered us not to follow up the congregational Salat with any other Salat until we have talked (to some one) or moved from the place.".', null, '''Umar bin ''Ata reported that Nafi'' bin Jubair sent him to Sa''ib bin Ukht Namir to ask him about something that Mu''awiyah had seen him doing in Salat (prayer). He said:', 'صحيح', 'رياض الصالحين 1131', 'Riyad as-Salihin 1131', 'ریاض الصالحین 1131', 'رواه مسلم', 'أرسل نافع بن جبير عمر بن عطاء إلى السائب بن يزيد، وهو ابن أخت نَمِر، يسأله عن شيءٍ رآه منه معاوية في الصلاة، فأنكره عليه، فقال السائب: نعم، ثم أخبره أنه صلى مع معاوية صلاة الجمعة في موضعٍ من المسجد، يقال له المقصورة، تقصر على الملوك والأمراء، تحصينًا لهم، فإن كان اتخاذها لغير تلك العلة فلا يجوز، ولا يصلى فيها؛ لتفريقها الصفوف، وحيلولتها بين الإمام وبين المصلين خلفه مع تمكنهم من مشاهدة أفعاله.
فلما انتهت الصلاة وسلم الإمام قام السائب في مكانه الذي صلى فيه الجمعة فصلى النافلة من غير فاصل بينها وبين الفرض، فلما دخل معاوية رضي الله عنه بيته، أرسل إلى السائب للحضور عنده حتى يبين له خطأه، فقال له: لا ترجع لما فعلت من وصل النافلة بالفريضة، حتى تتكلم، أو تنتقل من محل الفريضة إلى محل آخر من المسجد.
ثم ذكر معاوية رضي الله عنه دليلًا لما قاله، وهو أن رسول الله صلى الله عليه وسلم أمرهم بما ذَكَر من التكلُّم، أو الخروج، ونهاهم عن وصل صلاة بصلاة دون أن يقطع بينهما بكلام أو خروج.', 'بيان مشروعية فصل النافلة عن الفريضة، إما بالكلام، أو الخروج من محلها، والأفضل الخروج إلى البيت.
جواز اتخاذ المقصورة في المسجد إذا رآها ولي الأمر مصلحة، والحاصل أنها إذا اتخذت لغرض صحيح فجواز الصلاة لمن فيها هو الأرجح.
إن النافلة الراتبة وغيرها يستحب أن يتحول لها عن موضع الفريضة إلى موضع آخر، وأفضله التحول إلى بيته، وإلا فموضع آخر من المسجد، أو غيره؛ لتكثر مواضع سجوده، ولتنفصل صورة النافلة عن صورة الفريضة.
أن الفصل بين النافلة والفريضة يحصل بالكلام أيضًا، ولكن بالانتقال أفضل.
مقصود هذا الحديث منع ما يؤدي إلى الزيادة على الصلوات المحدودات.', 'المقصورة: غرفة في المسجد تكون للأمراء.
قمت في مقامي فصليت: أي قام فصلى النافلة بعد أن سلّم الإمام.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65765', false),
(21132, 2, 209, 1132, 'hadith', 'عن علي رضي الله عنه قال: الوتر ليس بختم كصلاة المكتوبة ولكن سن رسول الله صلى الله عليه وسلم قال: «إن الله وتر يحب الوتر، فأوتروا يا أهل القرآن». ((رواه أبو داود والترمذي)). وقال: حديث حسن.', 'The Witr prayer is not obligatory as the prescribed Salat (prayers), but the Messenger of Allah (ﷺ) observed it as his regular practice (Sunnah). He (ﷺ) said, "Allah is Witr (single, odd) and loves what is Witr. So perform Witr prayer. O followers of Qur''an, observe Witr (prayer).".', 'علي رضي الله عنه', '''Ali (bin Abu Talib) (May Allah be pleased with him)', null, 'رياض الصالحين 1132', 'Riyad as-Salihin 1132', 'ریاض الصالحین 1132', null, null, null, null, 'sunnah.com', null, false, null, false),
(21133, 2, 209, 1133, 'hadith', 'عن عائشة رضي الله عنها قالت: من كل الليل قد أوتر رسول الله صلى الله عليه وسلم: من أول الليل ومن أوسطه، ومن آخره. وانتهى وتره إلى السحر.', 'The Messenger of Allah (ﷺ) observed Witr prayer in every part of night at the beginning, middle and at the last part. He (ﷺ), however, would finish his Witr prayer before dawn..', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 1133', 'Riyad as-Salihin 1133', 'ریاض الصالحین 1133', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21134, 2, 209, 1134, 'hadith', 'عن ابن عمر رضي الله عنهما، عن النبي صلى الله عليه وسلم: « اجعلوا آخر صلاتكم بالليل وترًا».', 'The Prophet (ﷺ) said, "Make Witr prayer the last of your Salat at night.".', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1134', 'Riyad as-Salihin 1134', 'ریاض الصالحین 1134', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21135, 2, 209, 1135, 'hadith', 'عن أبي سعيد الخدري رضي الله عنه أن النبي صلى الله عليه وسلم قال: «أوتروا قبل أن تصبحوا».', 'The Prophet (ﷺ) said, "Perform Witr prayer before dawn.".', 'أبي سعيد الخدري رضي الله عنه', 'Abu Sa''id Al-Khudri (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1135', 'Riyad as-Salihin 1135', 'ریاض الصالحین 1135', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21136, 2, 209, 1136, 'hadith', 'عن عائشة رضي الله عنها أن النبي صلى الله عليه وسلم كان يصلي بالليل، وهي معترضة بين يديه، فإذا بقي الوتر، أيقظها فأوترت. ((رواه مسلم)). وفي رواية له: فإذا بقي الوتر قال: «قومي فأوتري يا عائشة»', 'The Prophet (ﷺ) used to perform his voluntary prayer at night (i.e., Tahajjud prayer) while she was sleeping in front of him; and when the Witr prayer was yet to be observed, he would awaken her to perform her Witr prayer..', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 1136', 'Riyad as-Salihin 1136', 'ریاض الصالحین 1136', null, 'معنى الحديث: أن النبي صلى الله عليه وسلم كان يصلي صلاة الليل، وعائشة رضي الله عنها مُعْتَرِضَةٌ بَيَن يَدَيه، وفي رواية للبخاري ومسلم عنها: "أن النبي صلى الله عليه وسلم كان يُصلي من الليل وأنا مُعْتَرِضَةٌ بَيَنه وَبَيْن القِبلة، كاعتِرَاض الجَنازة".
 فإذا فَرغ النبي صلى الله عليه وسلم من صلاة التهجد، وقبل أن يشرع في صلاة الوتر أيْقَظها لتوتر وفي رواية لمسلم: فإذا بَقي الوِتر، قال: "قُومِي فأوْتِري يا عائشة" . وفي رواية لأبي داود: "حتى إذا أراد أن يوتر أيْقَظها فأوترت".
والمعنى: أن النبي صلى الله عليه وسلم يترك عائشة رضي الله عنها أول الليل ولا يُوقظها، حتى إذا فرغ من صلاته ولم يبق إلا الوتر أيقظها لتدرك وترها وتبادر بالوتر عقب الاستيقاظ لئلا يغلب عليها كسل النوم لو تماهلت عنه فيفوتها.', 'يستحب أن يُوقظ الرجل أهل بيته لصلاة الليل ويَحضُهم على ذلك.
جواز اعتراض المرأة أمام الرجل في صلاته.
جواز اتخاذ الرجل الجالس سترة له.
استحباب تأخير صلاة الوتر إلى آخر الليل.
يستحب لمن وَثِقَ باستيقاظه من آخر الليل، إما بنفسه وإما بإيقَاظ غيره له، أن يؤخر الوتر وإن لم يكن له تهجد، فإن عائشة -رضي الله عنها- كانت بهذه الصفة.', 'معترضة بين يديه : نائمة أمامه من جهة يمينه إلى جهة شماله.
الوتر : هو: الصلاة المخصوصة بعد فريضة العشاء، سميت بذلك لأن عدد ركعاتها وتر لا شفع.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3565', false),
(21137, 2, 209, 1137, 'hadith', 'عن ابن عمر رضي الله عنهما أن النبي صلى الله عليه وسلم قال: «بادروا الصبح بالوتر» ((رواه أبو داود والترمذي)). وقال: حديث حسن صحيح.', 'The Prophet (ﷺ) said, "Hasten to perform the Witr prayer before dawn.".', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them)', null, 'رياض الصالحين 1137', 'Riyad as-Salihin 1137', 'ریاض الصالحین 1137', null, null, null, null, 'sunnah.com', null, false, null, false),
(21138, 2, 209, 1138, 'hadith', 'عن جابر رضي الله عنه قال قال رسول الله صلى الله عليه وسلم : «من خاف أن لا يقوم الليل فليوتر أوله، ومن طمع أن يقوم آخره، فليوتر آخر الليل، فإن صلاة آخر الليل مشهودة، وذلك أفضل».', 'The Messenger of Allah (ﷺ) said, "He who apprehends that he may not get up in the later part of the night, should observe the Witr prayer in the first part of it; and he who is certain to get up in the last part of it, he should observe Witr at the end of the night, because Salat at the end of the night is attended (by the angels), and that is better.".', 'جابر رضي الله عنه', 'Jabir (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1138', 'Riyad as-Salihin 1138', 'ریاض الصالحین 1138', 'رواه مسلم', 'يبين الحديث جواز صلاة الوتر في أول الليل، ويكون الجواز أولى في حق من خشي ألا يقوم آخر الليل، كما بين أفضلية صلاته في آخر الليل وذلك لكونها مشهودة من الملائكة.', 'أنَّ الوتر يجوز في أول الليل وفي آخره، فوقته من صلاة العشاء إلى طلوع الفجر الثاني، ومن كل الليل أوتر النبي -صلى الله عليه وسلم-.
أنَّ تأخير الوتر إلى آخر الليل أفضل لمن قوي على القيام، وطمع في أن يستيقظ قبل الفجر.
أنَّ من يخشى ألا يقوم آخر الليل؛ يشرع له الوتر قبل أن ينام, ويكون في حقه أفضل.', 'طمع : أمل ورجا.
مشهودة : أي تحضرها الملائكة, ولأنَّ الله -تعالى- ينزل آخر الليل، فينادي خلقه ويجيب سؤالهم.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/11278', false),
(21139, 2, 209, 1139, 'hadith', 'عن أبي هريرة رضي الله عنه قال: أوصاني خليلي صلى الله عليه وسلم بصيام ثلاثة أيام من كل شهر، وركعتي الضحى، وأن أوتر قبل أن أرقد" . ((متفق عليه)) والإيتار قبل النوم إنما يستحب لمن لا يثق باستيقاظ آخر الليل، فإن وثق فآخر الليل أفضل.', 'My Khalil (the Messenger of Allah (ﷺ)) directed me to fast three days of each month, and to observe two Rak''ah Duha (optional prayer) at forenoon, and to perform the Witr prayer before going to bed..', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1139', 'Riyad as-Salihin 1139', 'ریاض الصالحین 1139', null, 'يُخْبِرُ أبو هريرةَ رضي الله عنه أنَّ حبيبَه وصاحبَه النبيَّ صلى الله عليه وسلم أوصاه وعَهِدَ إليه  بثلاث خصالٍ: 

الأولى: صوم ثلاثة أيام من كل شهر. 

الثانية: ركعتي الضُّحَى كل يوم. 

الثالثة: الوِتْر قبل النوم؛ وذلك لِمَن خاف أن لا يَستيقظ آخر الليل.', 'اختلاف وصايا النبيِّ صلى الله عليه وسلم لأصحابه: مَبنيٌّ على عِلْمِه صلى الله عليه وسلم بأحوال أصحابه، وما يُناسِب كلَّ واحد منهم، فالقوي يُناسبه الجهاد، والعابد تُناسبه العبادة، والعالِم يُناسبه العِلْم، وهكذا.
قال ابن حجر العسقلاني في قوله: صوم ثلاثة أيام من كل شهر، الذي يظهر أن المراد بها البِيْض؛ وهي: يوم الثالث عشر، والرابع عشر، والخامس عشر، من الشهر الهجري.
قال ابن حجر العسقلاني: فيه استحباب تقديم الوتر على النوم، وذلك في حقِّ مَن لم يَثِق بالاستيقاظ.
أهمية هذه الأعمال الثلاثة؛ لوصية النبي صلى الله عليه وسلم عَدَدًا من أصحابه بها.
قال ابن دقيق العيد في قوله: (وركعتي الضحى): لعلّه ذَكَر الأقَلَّ الذي يوجد التأكيد بفعله، وفي هذا دلالة على استحباب صلاة الضحى، وأنَّ أقلها ركعتان.
وقت صلاة الضحى: من بعد شروق الشمس بربع ساعة تقريبًا، ويَمتَد وقتُها إلى ما قبل الظهر بعشر دقائق تقريبًا، وعددها: أقلها ركعتان، واختُلف في أكثرها؛ فقيل: ثماني ركعات، وقيل: لا حد لأكثرها.
وقت الوتر: من بعد صلاة العشاء إلى طلوع الفجر، وأقله ركعة، وأكثره إحدى عشرة ركعة.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4538', false),
(21140, 2, 209, 1140, 'hadith', 'عن أبي ذر رضي الله عنه عن النبي صلى الله عليه وسلم قال: «يصبح على كل سلامى من أحدكم صدقة: فكل تسبيحة صدقة، وكل تهليلة صدقة، وكل تكبيرة صدقة، وأمر بالمعروف صدقة، ونهي عن المنكر صدقة، ويجزئ من ذلك ركعتان يركعهما من الضحى».', 'The Prophet (ﷺ) said, "In the morning, charity is due on every joint bone of the body of everyone of you. Every utterance of Allah''s Glorification (i.e., saying Subhan Allah) is an act of charity, and every utterance of His Praise (i.e., saying Al-hamdu lillah) is an act of charity and every utterance of declaration of His Greatness (i.e., saying La ilaha illAllah) is an act of charity; and enjoining M''aruf (good) is an act of charity, and forbidding Munkar (evil) is an act of charity, and two Rak''ah Duha prayers which one performs in the forenoon is equal to all this (in reward).".', 'أبي ذر رضي الله عنه', 'Abu Dharr (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1140', 'Riyad as-Salihin 1140', 'ریاض الصالحین 1140', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21141, 2, 209, 1141, 'hadith', 'عن عائشة رضي الله عنها قالت: كان رسول الله صلى الله عليه وسلم يصلي الضحى أربعًا ويزيد ما شاء الله.', 'The Messenger of Allah (ﷺ) used to perform four Rak''ah of Duha prayer (at the forenoon) and would add to them whatever Allah wished..', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 1141', 'Riyad as-Salihin 1141', 'ریاض الصالحین 1141', 'رواه مسلم', 'في هذا الحديث ذكرت عائشة رضي الله عنها أن النبي صلى الله عليه وسلم كان يصلِّي الضُّحى أربع ركعات يُسلَّم من كل ركعتين، ثم ذكرت أن النبي صلى الله عليه وسلم قد يزيد على أربع ركعات؛ على حسب قُدرته ونشاطه.', 'فيه إثبات صلاة الضُّحى من فعله -صلى الله عليه وسلم-.
أن صلاة الضُّحى غير مقيدة بعدد.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/11280', false),
(21142, 2, 209, 1142, 'hadith', 'عن أم هانئ فاختة بنت أبي طالب رضي الله عنها قالت: ذهبت إلى رسول الله صلى الله عليه وسلم عام الفتح فوجدته يغتسل فلما فرغ من غسله صلى ثمان ركعات، وذلك ضحى".', 'I went to the Messenger of Allah (ﷺ) on the day of the conquest of Makkah. He was taking a bath at that time. When he finished the bath, he performed eight Rak''ah (of optional) prayers. This was during the Duha (forenoon)..', 'أم هانئ فاختة بنت أبي طالب رضي الله عنها', 'Umm Hani, daughter of Abu Talib (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 1142', 'Riyad as-Salihin 1142', 'ریاض الصالحین 1142', 'متفق عليه وهذا مختصر لفظ إحدى روايات مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21143, 2, 209, 1143, 'hadith', 'عن زيد بن أرقم رضي الله عنه أنه رأى قومًا يصلون من الضحى، فقال: أما لقد علموا أن الصلاة في غير هذه الساعة أفضل، إن رسول الله صلى الله عليه وسلم قال: «صلاة الأوابين حين ترمض الفصال».', 'I saw some people performing Duha (prayers) in the early forenoon and warned them (saying): These people must know that performing Salat a little later is better. The Messenger of Allah (ﷺ) said, "The Salat of the penitent is to be observed when the young ones of camels feel the heat of the sun (i.e., when it becomes very hot).".', 'زيد بن أرقم رضي الله عنه', 'Zaid bin Arqam (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1143', 'Riyad as-Salihin 1143', 'ریاض الصالحین 1143', 'رواه مسلم', 'رأى زيد بن أرقم رضي الله عنه بعض الناس يصلِّي الضُّحى، فذكر أنه سمع رسول الله صلى الله عليه وسلم يقول: صلاة الأوابين حين تَرْمضُ الفِصَال، أي أن أفضل وقت لصلاة الضحى هو عند شدة ارتفاع الشمس، حين تحترق خفاف صغار الإبل من شِدِّة حَرِّ الشمس على الأرض، فهذا هو الوقت الذي يصلي فيه المطيعون لله تعالى كثيرو الرجوع إليه صلاة الضحى.', 'استحباب صلاة الضُّحَى .
أن أفضل أوقات صلاة الضحى: عند اشتداد حرارة الأرض من وقوع الشمس على الرَّمل وغيره.', 'الأَوَّابِينَ : الأوَّاب: الرَّجاع إلى الله تبارك وتعالى، بترك الذُّنوب، وفعل الطَّاعات والخير.
تَرْمَضُ : أي: تَحترق أخفافها من الرَّمضاء، وهي شِدَّة حرارة الأرض من وقوع الشمس على الرَّمل، عند ارتفاع الشمس.
الفِصَال : جمع "فصيل"، وهو ولد النَّاقة، سُمي بذلك؛ لفَصْلِه عن أُمِّه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/11283', false),
(21144, 2, 209, 1144, 'hadith', 'عن أبي قتادة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: « إذا دخل أحدكم المسجد فلا يجلس حتى يصلي ركعتين».', 'The Messenger of Allah (ﷺ) said, "When anyone of you enters the mosque, he should perform two Rak''ah (of voluntary prayer) before sitting.".', 'أبي قتادة رضي الله عنه', 'Abu Qatadah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1144', 'Riyad as-Salihin 1144', 'ریاض الصالحین 1144', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21145, 2, 209, 1145, 'hadith', 'عن جابر، رضي الله عنه قال: أتيت النبي صلى الله عليه وسلم وهو في المسجد فقال: «صلِ ركعتين».', 'I came to the Prophet (ﷺ) when he was in the mosque, and he said to me, "Perform two Rak''ah prayer.".', 'جابر رضي الله عنه', 'Jabir (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1145', 'Riyad as-Salihin 1145', 'ریاض الصالحین 1145', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21146, 2, 209, 1146, 'hadith', 'عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال لبلال: يا بلال حدثني بأرجى عمل عملته في الإسلام، فإني سمعت دف نعليك بين يدي في الجنة، قال: ما عملت عملا أرجى عندي من أني لم أتطهر طهورًا في ساعة من ليل أو نهار إلا صليت بذلك الطهور ما كتب لي أن أصلي.', 'The Messenger of Allah (ﷺ) said to Bilal (May Allah be pleased with him) "Tell me about the most hopeful act (i.e., one which you deem the most rewarding with Allah) you have done since your acceptance of Islam because I heard the sound of the steps of your shoes in front of me in Jannah." Bilal said: "I do not consider any act more hopeful than that whenever I make Wudu'' (or took a bath) in an hour of night or day, I would immediately perform Salat (prayer) for as long as was destined for me to perform.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1146', 'Riyad as-Salihin 1146', 'ریاض الصالحین 1146', 'متفق عليه وهذا لفظ البخاري', 'رأى النبي صلى الله عليه وسلم في المنام أنه في الجنة، فقال لبلال بن رباح: أخبرني بأرجى عملِ تطوعٍ عملته في الإسلام؟ فإني سمعت صوتًا خفيفًا لنعليك عند تحريكهما بالمشي أمامي في الجنة.

 قال بلال: ما عملت عملًا أرجى عندي أني لم أحدث في ساعة ليل أو نهار إلا وتوضأت، ثم صليت لربي بذلك الوضوء من النوافل المطلقة ما كتب لي أن أصلي.', 'فضل العمل الذي دل عليه بلال رضي الله عنه، ألا وهو الصلاة كلما تطهر وتوضأ، وأنه من أرجى الأعمال وسبب لدخول الجنة.
استحباب الصلاة بعد كل وضوء.
سؤال القدوة أو المربي عن عمل تلميذه؛ ليحضَّه على الثبات عليه إن كان حسنًا، وإلا فينهاه.
شهادة من النبي صلى الله عليه وسلم لبلال رضي الله عنه بأنه من أهل الجنة.
هذا السؤال عند صلاة الفجر، وفي هذا إشارة إلى أن ذلك وقع في رؤيا منام منه صلى الله عليه وسلم، ورؤيا الأنبياء حق.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65849', false),
(21147, 2, 209, 1147, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: « خير يوم طلعت عليه الشمس يوم الجمعة: فيه خلق آدم، وفيه أدخل الجنة، وفيه أخرج منها».', 'The Messenger of Allah (ﷺ) said, "The best day on which the sun has risen is Friday. On that day Adam was created, he was admitted to Jannah, and he was expelled therefrom.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1147', 'Riyad as-Salihin 1147', 'ریاض الصالحین 1147', 'رواه مسلم', 'يُخبِرُ النبيُّ صلى الله عليه وسلم أنَّ خيْرَ يومٍ طلعت عليه الشمس يومُ الجمعة، 
ومن خصائصه: أن الله خلق فيه آدم عليه السلام، وفيه أدخله الجنة، وفيه أخرجه منها وأهبطه إلى الأرض، ولا تقوم الساعة إلا في يوم الجمعة.', 'فضل يوم الجمعة على سائر أيام الأسبوع.
الحث والإكثار من الأعمال الصالحة في يوم الجمعة، والتأهب لنيل رحمة الله تعالى، ودفع نقمته.
هذه الخصائص ليوم الجمعة التي ذكرت في الحديث قيل: أنها ليست لذكر فضيلة يوم الجمعة؛ لأن إخراج آدم وقيام الساعة لا يعد فضيلة، وقيل: بل جميعها فضائل وخروج آدم سبب وجود الذرية من الرسل والأنبياء والصالحين، وقيام الساعة سبب تعجيل جزاء الصالحين ونيلهم ما أعد الله لهم من الكرامات.
 ذُكِرَ ليوم الجمعة خصائص أخرى غير ما ذكر في هذه الرواية، ومنها: فيه تِيْبَ على آدم، وفيه قُبض، وفيه ساعة لا يصادفها عبد مؤمن وهو يصلي يسأل الله شيئًا إلا أعطاه إياه.
أفضل أيام السنة يوم عرفة، وقيل: يوم النحر، وأفضل أيام الأسبوع يوم الجمعة، وأفضل ليلة ليلة القدر.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3711', false),
(21148, 2, 209, 1148, 'hadith', 'وعنه قال: قال رسول الله، صلى الله عليه وسلم : «من توضأ فأحسن الوضوء ثم أتي الجمعة، فاستمع وأنصت، غفر له ما بينه وبين الجمعة وزيادة ثلاثة أيام، ومن مس الحصى، فقد لغا».', 'The Messenger of Allah (ﷺ) said, "If anyone performs Wudu'' properly, then comes to the Friday prayer, listens to the Khutbah (religious talk) attentively and keeps silent, his (minor) sins between that Friday and the following Friday will be forgiven, with the addition of three more days; but he who touches pebbles has caused an interruption. ".', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1148', 'Riyad as-Salihin 1148', 'ریاض الصالحین 1148', 'رواه مسلم', 'يُخْبِرُ النبيُّ صلى الله عليه وسلم أنَّ مَن توضأ فأحسن وضوءه بإتمام أركانه والإتيان بسننه وآدابه، ثم أتى صلاة الجمعة وأنصت وأصغى للخطيب، وسكت عن اللغو؛ غفر الله له صغائر ذنوب عشرة أيام، من صلاة الجمعة إلى الجمعة الثانية وزياة ثلاثة أيام؛ لأن الحسنة بعَشر أمثالها، 
ثم حذَّر صلى الله عليه وسلم من عدم إقبال القلب عمّا يقال في الخطبة من مواعظ، ومِن عَبَثِ الجوارح مِن مَسِّ الحصى وغيره من أنواع العبث والانشغال، بأنَّ مَن فَعل ذلك فقد لغا، ومن لغا فلا حظ له في أجر جمعة كاملة.', 'الحث على أداء الوضوء وإتمامه على كمال، والمحافظة على صلاة الجمعة.
فضل صلاة الجمعة.
وجوب الإنصات لخطبة الجمعة، وعدم التشاغل عنها بالكلام وغيره.
من لغا أثناء الخطبة فصلاة الجمعة مجزئة ومسقطة للفرض، مع نقص الأجر.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5433', false),
(21149, 2, 209, 1149, 'hadith', 'وعنه عن النبي، صلى الله عليه وسلم قال: «الصلوات الخمس والجمعة إلى الجمعة، ورمضان إلى رمضان، مكفرات ما بينهن إذا اجتنبت الكبائر».', 'The Prophet (ﷺ) said, "The five daily (prescribed) Salat, and Friday (prayer) to the next Friday (prayer), and the fasting of Ramadan to the next Ramadan, is expiation of the sins committed in between them, so long as major sins are avoided.".', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1149', 'Riyad as-Salihin 1149', 'ریاض الصالحین 1149', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21150, 2, 209, 1150, 'hadith', 'وعنه وعن ابن عمر، رضي الله عنهم، أنهما سمعا رسول الله صلى الله عليه وسلم ، يقول على أعواد منبره: «لينتهين أقوام عن وَدعهم الجمعات، أو ليختمن الله على قلوبهم، ثم ليكونن من الغافلين».', 'We heard the Messenger of Allah (ﷺ) saying (while delivering Khutbah on his wooden pulpit), "Either some people (i.e., hypocrites) stop neglecting the Friday prayers, or Allah will seal their hearts and they will be among the heedless.".', null, 'Ibn ''Umar and Abu Hurairah (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1150', 'Riyad as-Salihin 1150', 'ریاض الصالحین 1150', 'رواه مسلم', 'حذَّر النبي صلى الله عليه وسلم -وهو على منبره- من ترك صلاة الجمعة والتخلُّف عنها من غير عذر، تهاونًا وكسلًا، أو ليطبع الله على قلوبهم ويغطّيها ويجعل عليها حاجزًا يمنعها عن اتباع الحق، ثم يكونوا من الغافلين عن أسباب الخير، الزاهدة نفوسهم عن الطاعات.', 'التشديد في التخلف عن صلاة الجمعة، وأن ذلك من كبائر الذنوب.
قال النووي: فيه أن الجمعة فرض عين.
مشروعية اتخاذ المنبر للخطبة.
قال السندي: المعنى أن أحد الأمرين كائن لا محالة إما الانتهاء عن ترك الجمعات أو ختم الله تعالى على قلوبهم، فإن اعتياد ترك الجمعة يُغَلِّب الرَّيْنَ على القلب ويُزهِّد النفوس في الطاعات.
ينبغي للواعظ والمذكِّر أن يُبْهِم الأشخاص الذين يريد أن يَعِظهم؛ لأن ذلك أدعى لقبول النصح، وامتثال الأوامر.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65767', false),
(21151, 2, 209, 1151, 'hadith', 'عن ابن عمر رضي الله عنهما، أن رسول الله صلى الله عليه وسلم ، قال: «إذا جاء أحدكم الجمعة، فليغتسل».', 'The Messenger of Allah (ﷺ) said, "When one of you intends to come for the Friday prayer, he should take a bath.".', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1151', 'Riyad as-Salihin 1151', 'ریاض الصالحین 1151', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21152, 2, 209, 1152, 'hadith', 'عن أبي سعيد الخدري، رضي الله عنه، أن رسول الله صلى الله عليه وسلم ، قال: «غسل الجمعة واجب على كل محتلم».', 'The Messenger of Allah (ﷺ) said, "Taking a bath (before coming to Friday prayers) is obligatory on every adult.".', 'أبي سعيد الخدري رضي الله عنه', 'Abu Sa''id Al-Khudri (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1152', 'Riyad as-Salihin 1152', 'ریاض الصالحین 1152', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21153, 2, 209, 1153, 'hadith', 'عن سمرة، رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «من توضأ يوم الجمعة، فبها ونعمت، ومن اغتسل فالغسل أفضل».', 'The Messenger of Allah (ﷺ) said, "It suffices to perform Wudu'' properly for the Friday prayer; but it is better to take a bath.".', 'سمرة رضي الله عنه', 'Samurah (May Allah be pleased with him)', 'حسن', 'رياض الصالحين 1153', 'Riyad as-Salihin 1153', 'ریاض الصالحین 1153', 'رواه أبو داود، والترمذي وقال حديث حسن', null, null, null, 'sunnah.com', null, false, null, false),
(21154, 2, 209, 1154, 'hadith', '- وعن سلمان، رضي الله عنه، قال: قال رسول الله صلى الله عليه وسلم : «لا يغتسل رجل يوم الجمعة، ويتطهر ما استطاع من طهر، ويدهن من دهنه، أو يمس من طيب بيته، ثم يخرج فلا يفرق بين اثنين، ثم يصلي ما كتب له، ثم ينصت إذا تكلم الإمام، إلا غفر له ما بينه وبين الجمعة الأخرى».', 'The Messenger of Allah (ﷺ) said, "If a man takes bath on Friday, (or) purifies himself as much as he can with Wudu'', oils his hair, applies whatever perfume available in his house, sets forth for the mosque, does not separate two people (to make a seat for himself), performs Salat what is prescribed for him, remains silent when the Imam speaks, his (minor) sins between that Friday and the following Friday will be forgiven.".', null, 'Salman (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1154', 'Riyad as-Salihin 1154', 'ریاض الصالحین 1154', 'رواه البخاري', 'في هذا الحديث بيان آداب الجمعة، إذ أخبر النبي صلى الله عليه وسلم أن الرجل الذي يأتي بهذه السنن له ثواب عظيم، وهي أن يغتسل غسلًا قبل صلاة الجمعة، ويتنظف بما يقدر عليه في بدنه وثيابه، فإن كان محتاجًا لتقليم أظفاره أو قص شاربه ونحو ذلك فعله، ويَطلي بالدهن ونحوه ما يحتاج إليه من بدنه، ويُزيل شَعَثَ رأسه ولحيته به، أو يتطيب من طيب بيته، ولا ينافي قوله (أو) أن يجمع بينهما، لورود الأدلة المستقلة في استحباب التطيب، وأضاف الطيب إلى البيت إشارة إلى أن السنة اتخاذ الطيب في البيت، ويَجعل استعماله له عادة، وفي حديث آخر: (ويمس من طيب أهله)؛ لأن اتخاذ الطيب عند المرأة أكثر، فلو قُدِّر أنه نَفِد طيبُه أو لم يكن له طيب فليستعمل طيب امرأته؛ ليعلم أن التطيب في هذا اليوم متأكد، ثم يخرج إلى المسجد لا يزاحم رجلين فيدخل بينهما، لأنه ربما ضيق عليهما، خصوصًا في شدة الحر واجتماع الأنفاس، ثم يصلي ما استطاع أن يصلي، وفيه استحباب التطوع قبل صلاة الجمعة، ثم يسكت ويستمع إذا شرع الإمام في الخطبة، والثواب المرتب على ذلك أن تُغفر له معاصيه التي بين الجمعة الحاضرة وبين الجمعة الماضية، أو المستقبلة.', 'بيان آداب الجمعة.
استحباب الغسل والتطيب والادهان يوم الجمعة.
أن الإسلام دين النظافة والجمال.
من السنة اتخاذ الطيب في البيت، ويجعل استعماله له عادة.
النهي عن التفرقة بين اثنين والمزاحمة.
استحباب التنفل قبل صلاة الجمعة.
تكفير الذنوب بين الجمعتين مشروط بوجود آداب الجمعة كلها.', 'يدهن: يستعمل في بدنه ما يذهب جفافه، وكانت الزيوت والشحوم تقوم مقام الكريمات الجلدية في عصرنا.
ينصت: يسكت ويستمع.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65756', false),
(21155, 2, 209, 1155, 'hadith', 'عن أبي هريرة رضي الله عنه، أن رسول الله صلى الله عليه وسلم ، قال: «من اغتسل يوم الجمعة غسل الجنابة، ثم راح في الساعة الأولى فكأنما قرب بدنة، ومن راح في الساعة الثانية، فكأنما قرب بقرة، ومن راح في الساعة الثالثة، فكأنما قرب كبشًا أقرن، ومن راح في الساعة الرابعة، فكأنما قرب دجاجة، ومن راح في الساعة الخامسة، فكأنما قرب بيضة، فإذا خرج الإمام، حضرت الملائكة يستمعون الذكر».', 'The Messenger of Allah (ﷺ) said, "He who takes a bath on Friday, like the bath for ceremonial purity, and then goes (to the mosque), he is like one who offers a camel as a sacrifice to seek the Pleasure of Allah; and he who comes at the second hour is like one who offers a cow to win the Pleasure of Allah; and he who comes at the third hour is like one who offers a ram with horns (in sacrifice); and he who comes at the fourth hour is like one who offers a hen; and he who comes at the fifth hour is like one who offers an egg. And when the Imam ascends the pulpit, the angels (who write the names of those who come to the mosque before the coming of the Imam) close (their record) in order to listen to the Khutbah.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1155', 'Riyad as-Salihin 1155', 'ریاض الصالحین 1155', 'متفق عليه', 'يُخبِرُ النبيُّ صلى الله عليه وسلم عن فَضْل التَّبْكِيْر في الذهاب إلى صلاة الجمعة، 
ويبدأ التبكير من طلوع الشمس إلى مجيء الإمام؛ وهو خمس ساعات، وتقسم على حسب الوقت بين طلوع الشمس إلى دخول الإمام وصعوده المنبر للخطبة خمسة أجزاء:

الأول: من اغتسل غسلًا كاملًا كغسل الجنابة،  ثم ذهب لمسجد الجمعة في الساعة الأولى فكأنما تصدَّق بِجَمَل.

الثاني: من ذهب في الساعة الثانية فكأنما تصدَّق ببقرة.

الثالث: من ذهب في الساعة الثالثة فكأنما تصدق بكبش -وهو ذكر الضأن-  له قرون. 

الرابع: من ذهب في الساعة الرابعة فكأنما تصدق بدجاجة.

الخامس: من ذهب في الساعة الخامسة فكأنما تصدق ببيضة.

فإذا خرج الإمام للخطبة؛ توقَّفت الملائكة الجالسون على الأبواب لكتابة الداخلين للمسجد الأول فالأول عن الكتابة، وجاؤوا يستمعون الذكر والخطبة.', 'الحث على الاغتسال يوم الجمعة، ويكون قبل الذهاب إلى الصلاة.
فضيلة التبكير إلى صلاة الجمعة من أول ساعات النهار.
الحث على المبادرة إلى الأعمال الصالحة.
حضور الملائكة صلاة الجمعة واستماعهم للخطبة.
الملائكة على أبواب المساجد، يكتبون القادمين، الأوّل فالأول، في المجيء إلى صلاة الجمعة.
قال ابن رجب: قوله: "من اغتسل يوم الجمعة، ثم راح" يَدُلّ على أن الغُسل المستحب للجمعة أوّله طلوع الفجر، وآخره الرواح إلى الجمعة.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5393', false),
(21156, 2, 209, 1156, 'hadith', 'وعنه أن رسول الله صلى الله عليه وسلم ، ذكر يوم الجمعة، فقال: «فيها ساعة لا يوافقها عبد مسلم، وهو قائم يصلي يسأل الله شيئًا، إلا أعطاه إياه» وأشار بيده يقللها.', 'The Messenger of Allah (ﷺ) said while talking about the merits of Friday, "There is a time on Friday at which a Muslim, while he (or she) is performing Salat and is supplicating, will be granted whatever he (or she) is supplicating for." And he (ﷺ) pointed with his hand to indicate that this period of time is very short..', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1156', 'Riyad as-Salihin 1156', 'ریاض الصالحین 1156', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21157, 2, 209, 1157, 'hadith', 'عن أبي بردة بن أبي موسى الأشعري، رضي الله عنه، قال: قال عبد الله بن عمر رضي الله عنهما: أسمعت أباك يحدث عن رسول الله صلى الله عليه وسلم ، في شأن ساعة الجمعة؟ قال: قلت: نعم، سمعته يقول: سمعت رسول الله صلى الله عليه وسلم ، يقول: «هي ما بين أن يجلس الإمام إلى أن تقضى الصلاة».', '''Abdullah bin ''Umar (May Allah be pleased with them) said to me: "Did you hear your father narrating something from the Messenger of Allah (ﷺ) about the special moment during Friday?" I said: "Yes, I heard him report from the Messenger of Allah (ﷺ): ''It occurs between the time when the Imam sits down (on the pulpit after the first Khutbah) and the time Salat is over."''.', 'أبي بردة بن أبي موسى الأشعري رضي الله عنه', 'Abu Burdah bin Abu Musa Al-Ash''ari (May Allah be pleased with him)', 'صحيح بشواهده', 'رياض الصالحين 1157', 'Riyad as-Salihin 1157', 'ریاض الصالحین 1157', 'رواه مسلم', 'روى أبو بردة بن أبي موسى الأشعري ابن الصحابي الجليل رضي الله عنه أن عبد الله بن عمر بن الخطاب رضي الله عنهما سأله: هل سمعت أباك أي أبا موسى الأشعري رضي الله عنه يخبر عن رسول الله صلى الله عليه وسلم في بيان وقت ساعة إجابة الدعاء التي في يوم الجمعة؟ فأخبره أبو بردة أنه سمع أباه أبا موسى رضي الله عنه يقول: إنه سمع النبي صلى الله عليه وسلم يقول: أن الساعة التي في يوم الجمعة هي ما بين جلوس الإمام عقب صعوده على المنبر للخطبة، إلى تمام الصلاة، والفراغ منها.
والحديث نص في أن ساعة الإجابة فيما بين جلوس الإمام على المنبر للخطبة إلى تمام الصلاة، ولكن رجح بعض الأئمة أن هذا من قول أبي بردة، والشاهد الوارد مرفوعًا لفظه: (حين تقام الصلاة إلى انصرافٍ منها)، ويبقى أنه وردت نص آخر أن ساعة الإجابة في آخر يوم الجمة، فقد يكون كلٌّ منهما ساعة إجابة، وقد تكون متنقِّلةً بينهما، فيحرص الإنسان على الدعاء فيهما جميعًا.', 'بيان وقت ساعة الاستجابة في يوم الجمعة.
اهتمام الصحابة والسلف بما ورد عن النبي صلى الله عليه وسلم.', 'ساعة الجمعة: ساعة الإجابة.
تقضى الصلاة: صلاة الجمعة.', 'sunnah.com', null, false, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65754', false),
(21158, 2, 209, 1158, 'hadith', 'عن أوس بن أوس، رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «إن من أفضل أيامكم يوم الجمعة، فأكثروا علي من الصلاة فيه، فإن صلاتكم معروضة علي».', 'The Messenger of Allah (ﷺ) said, "Among the best of your days is Friday. On that day pray to Allah to exalt my mention frequently, for your such supplications are presented to me.".', 'أوس بن أوس رضي الله عنه', 'Aus bin Aus (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1158', 'Riyad as-Salihin 1158', 'ریاض الصالحین 1158', 'رواه أبو داود بإسناد صحيح', null, null, null, 'sunnah.com', null, false, null, false),
(21159, 2, 209, 1159, 'hadith', 'عن سعد بن أبي وقاص، رضي الله عنه، قال: خرجنا مع رسول الله صلى الله عليه وسلم من مكة نريد المدينة، فلما كنا قريبًا من عزوراء نزل ثم رفع يديه، فدعا الله ساعة، ثم خر ساجدًا، فمكث طويلا، ثم قام فرفع يديه ساعة، ثم خر ساجدًا- فعله- ثلاثًا- وقال: «إني سألت ربي، وشفعت لأمتي، فأعطاني ثلث أمتي، فخررت ساجدًا لربي شكرًا، ثم رفعت رأسي، فسألت ربي لأمتي، فأعطاني ثلث أمتي، فخررت ساجدًا لربي شكرًا، ثم رفعت رأسي، فسألت ربي لأمتي، فأعطاني الثلث الآخر، فخررت ساجدًا لربي».', 'We left Makkah with the Messenger of Allah (ﷺ) for Al-Madinah, and when we were near ''Azwara,'' he (ﷺ) alighted (from his riding-camel) raised his hands in supplication to Allah for a while and prostrated himself. He remained for a long time in prostration. Then he stood up and raised his hands for a while, after which he prostrated himself (again), and remained for a long time in prostration. Then he stood up and raised his hands for a while, after which he prostrated himself for the third time. Then he (ﷺ) said, "I supplicated my Rubb and made intercession for my Ummah, and He granted me one-third of them. So I again prostrated myself in gratitude to my Rubb. Then I raised my head and supplicated my Rubb for my Ummah, and He granted me another third of them. Again I raised my head and supplicated my Rubb for my Ummah and He granted me the last third of them. So I fell into prostration out of gratitude before my Rubb.".', 'سعد بن أبي وقاص رضي الله عنه', 'Sa''d bin Abu Waqqas (May Allah be pleased with him)', null, 'رياض الصالحين 1159', 'Riyad as-Salihin 1159', 'ریاض الصالحین 1159', 'رواه أبو داود', null, null, null, 'sunnah.com', null, false, null, false),
(21160, 2, 209, 1160, 'hadith', 'عن عائشة رضي الله عنها، قالت: كان النبي صلى الله عليه وسلم ، يقوم من الليل حتى تتفطر قدماه، فقلت له: لم تصنع هذا يا رسول الله، وقد غفر لك ما تقدم من ذنبك وما تأخر؟ قال: «أفلا أكون عبدًا شكورًا».', 'The Prophet (ﷺ) kept standing (in prayer) so long that the skin of his feet would crack. I asked him: "Why do you do this, while you have been forgiven of your former and latter sins?" He said, "Should I not be a grateful slave of Allah?".', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 1160', 'Riyad as-Salihin 1160', 'ریاض الصالحین 1160', 'متفق عليه وعن المغيرة بن شعبة نحوه، متفق عليه', null, null, null, 'sunnah.com', null, false, null, false)
