insert into hadith (id, collection_id, chapter_id, number_in_book, kind, arabic, translation_en, narrator_ar, narrator_en, grade_ar, reference_ar, reference_en, reference_ur, full_ref_ar, explanation_ar, benefits_ar, word_meanings_ar, source, source_ref, daily_ok, review_note, deleted) values
(21161, 2, 209, 1161, 'hadith', 'عن علي رضي الله عنه، أن النبي صلى الله عليه وسلم، طرقه وفاطمة ليلا، فقال: «ألا تصليان؟» ((متفق عليه)). (20)', 'The Prophet (ﷺ) visited me and Fatimah (May Allah be pleased with her) one night and said, "Do you not observe prayer (at night)?".', 'علي رضي الله عنه', '''Ali (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1161', 'Riyad as-Salihin 1161', 'ریاض الصالحین 1161', null, 'معنى الحديث: يُخبر علي بن أبي طالب رضي الله عنه : أن النبي صلى الله عليه وسلم أتاه وفاطمة ليلاً فوجدهما نَائمَين، فأيْقَظهما، وقال لهما: "ألا تُصَلِّيَانِ؟". 
فالنبي صلى الله عليه وسلم حثهما على صلاة الليل، واختار لهما تلك الفضيلة على الراحة والسكون؛ لِعِلْمه بفضلها ولولا ذلك ما كان يزعج ابنته وابن عمه في وقت جعله الله لخلقه سكنًا.', 'مشروعية إيقاظ النائمين من الأهل والقرابة؛ لما فيه من مَزِيد فضل.
فضل صلاة الليل والترغيب فيها.', 'تصليان : صلاة الليل.
طرقه : أتاه ليلًا.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3577', false),
(21162, 2, 209, 1162, 'hadith', 'عن سالم بن عبد الله بن عمر بن الخطاب، رضي الله عنهم، عن أبيه: أن رسول الله صلى الله عليه وسلم ، قال: «نعم الرجل عبد الله لو كان يصلي من الليل» قال سالم: فكان عبد الله بعد ذلك لا ينام إلا قليلا.', 'Salim bin ''Abdullah bin ''Umar bin Al-Khattab (May Allah be pleased with them) reported, on the authority of his father, that the Messenger of Allah (ﷺ) said, "What an excellent man ''Abdullah is! If only he could perform optional prayers at night." Salim said that after this, (his father) ''Abdullah slept very little at night..', 'سالم بن عبد الله بن عمر بن الخطاب رضي الله عنهم', null, 'صحيح', 'رياض الصالحين 1162', 'Riyad as-Salihin 1162', 'ریاض الصالحین 1162', 'متفق عليه', 'أخبر النبي صلى الله عليه وسلم أن عبد الله بن عمر رجل صالح وحضه على القيام بالليل، فكان رضي الله عنه لا ينام في الليل إلا قليلا.', 'بيان مزيد فضل قيام الليل، والحث عليه وأنه من مراتب الكمال.
مسارعة الصحابة لما يبلغهم من مراتب الكمال.
فضيلة عبد الله بن عمر -رضي الله عنه-.
جواز الثناء على من يؤمن عليه إعجابه بنفسه.
الحث على تمني الخير لنفسه ولغيره.
فيه الإشارة إلى أن قيام الليل سبب في النجاة من النار.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4223', false),
(21163, 2, 209, 1163, 'hadith', 'عن عبد الله بن عمرو بن العاص، رضي الله عنهما قال: قال رسول الله صلى الله عليه وسلم : «يا عبد الله لا تكن مثل فلان: كان يقوم الليل فترك قيام الليل».', 'The Messenger of Allah (ﷺ) said to me, "Do not be like so-and-so O ''Abdullah! He used to pray during the night, then stopped the practice.".', 'عبد الله بن عمرو بن العاص رضي الله عنهما', '''Abdullah bin ''Amr bin Al-''As (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1163', 'Riyad as-Salihin 1163', 'ریاض الصالحین 1163', 'متفق عليه', 'حذر النبي صلى الله عليه وسلم عبد الله بن عمرو أن يترك صلاة الليل كما فعل فلان من الناس، ولم يُذكر اسمه ستراً عليه.
وينبغي للمسلم أن يحذر من التشدد في العبادة وتكليفه النفس ما لا تطيق من الطاعات، ومن فَعَلَ ذلك غلبه الدِّين لكثرة الأعمال والطاعات، فيكون آخر أمره العجز والانقطاع؛ لأن الله تعالى أوجب على عباده وظائف من الطاعات في وقت دون وقت، تيسيراً ورحمة، ولأن الإنسان إذا أخذ بالقصد دام عمله، وتمكن من أداء الحقوق كلها، حقِّ الله تعالى، وحقِّ النفس، وحقِّ الأهل والأصحاب برفق وسهولة، وقد قال النبي -صلّى الله عليه وسلّم-: «إن أحب الأعمال إلى الله أدومها وإن قل»، فينبغي للإنسان أن يكون له ورد بالليل قدر استطاعته.', 'فضيلة قيام الليل، وأنَّه لا ينبغي تركه؛ لما فيه من الفضل العظيم، فصلاة الليل أفضل من صلاة النهار؛ لما فيها من السرية، والبُعد عن الرياء.
قيام الليل من المغرب إلى طلوع الفجر، فالنافلة بين المغرب والعشاء من قيامِ الليل، وأفضل صلاة الليل ثلث الليل بعد نصفه.
قال شيخ الإسلام: الصلاة إذا قام من الليل أفضل من القراءة في غير صلاة، نص على ذلك أئمة الإسلام؛ لقوله -صلى الله عليه وسلم-:"اعلموا أنَّ خير أعمالكم الصلاة" [رواهُ ابن ماجه (277)]، لكن إن حصل له نشاط، وتدبر، وتفهم للقراءة دون الصلاة، فالأفضل في حقه ما كان أنفع له.
استحباب الدوام على ما اعتاده المرء من أعمال الخير والطاعة من غير تفريط، وأنه لا ينبغي للإنسان قطع العبادة؛ لأن هذا قد يشعر بالزهد فيها والرغبة منها.
طلب الستر على المسلم، حيث أن النبي -صلى الله عليه وسلم- لم يسم الرجل الذي ذمه.', 'مثل فلان : لم يدر من هو، والظاهر أنَّ الإبهام من أحد الرواة؛ لقصد الستر عليه، والقصد هو تنفير عبد الله من الغفلة، وترغيبه بقيام الليل.
من الليل : المراد: في جزء من أجزائه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/11270', false),
(21164, 2, 209, 1164, 'hadith', 'عن ابن مسعود رضي الله عنه ، قال: ذكر عند النبي، صلى الله عليه وسلم رجل نام ليلة حتى أصبح! قال: «ذاك رجل بال الشيطان في أذنيه- أو قال: في أذنه-».', 'Mention was made before the Prophet (ﷺ) of a man who slept throughout the night till morning. The Messenger of Allah (ﷺ) remarked, "He is a man in whose ears Satan urinated.".n', 'ابن مسعود رضي الله عنه', '''Abdullah bin Mas''ud (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1164', 'Riyad as-Salihin 1164', 'ریاض الصالحین 1164', 'متفق عليه', 'ذُكِرَ عند النبيِّ صلى الله عليه وسلم رَجلٌ نام حتى أصبح وطَلَعت الشمس ولم يَقم إلى الصلاة المفروضة، فقال صلى الله عليه وسلم: إنه رجل بَالَ الشيطانُ في أُذُنِهِ.', 'كراهية ترك قيام الليل، وأنّ ذلك بسبب الشيطان.
الحَذَر من الشيطان الذي يَقعد للإنسان في كل طريق؛ لِيَحُوْلَ بينه وبين طاعة الله عز وجل.
قال ابن حجر: قوله: (ما قام إلى الصلاة) المُراد الجِنْس، ويحتمل العهد، ويراد به صلاة الليل أو المكتوبة.
قال الطيبي: خص الأذن بالذِّكْر، وإن كانت العين أنسب بالنوم إشارة إلى ثقل النوم، فإن المسامع هي موارد الانتباه، وخص البول؛ لأنه أسهل مدخلًا في التجاويف، وأسرع نفوذًا في العروق، فيورث الكسل في جميع الأعضاء.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3714', false),
(21165, 2, 209, 1165, 'hadith', 'عن أبي هريرة رضي الله عنه، أن رسول الله صلى الله عليه وسلم ، قال: «يعقد الشيطان على قافية، رأس أحدكم، إذا هو نام، ثلاث عقد، يضرب على كل عقدة: عليك ليل طويل فارقد، فإن استيقظ أحدكم، فذكر الله تعالى انحلت عقدة، فإن توضأ انحلت عقدة، فإن صلى انحلت عقدة، فأصبح نشيطًا طيب النفس، وإلا أصبح خبيث النفس كسلان».', 'The Messenger of Allah (ﷺ) said, "When any one of you sleeps, Satan ties three knots at the back of his neck. He recites this incantation at every knot: ''You have a long night, so sleep.'' If he awakes and remembers Allah, one knot is loosened. If he performs Wudu'', the (second) knot is loosened; and if he performs prayer, (all) knots are loosened. He begins his morning in a happy and refreshed mood; otherwise, he gets up in bad spirits and sluggish state.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1165', 'Riyad as-Salihin 1165', 'ریاض الصالحین 1165', 'متفق عليه', 'يُخْبِرُ النبيُّ صلى الله عليه وسلم بحال الشيطان وصراعه مع الإنسان الذي يريد القيام لصلاة الليل أو الفجر.


فإن المؤمن إذا ذهب إلى النوم يعقد الشيطان على قافيته -يعني: مُؤخَّر رأسه- ثلاث عقد.


فإذا استيقظ المؤمن وذكر الله تعالى ولم يستجب لوساوس الشيطان؛ انفكَّت عقدة.


فإن توضأ انفكت الأخرى.
 

وإن قام فصلى انفكت العقدة الثالثة، وأصبح نشيطًا طيب النفس؛ لسروره بما وفّقه الله من الطاعة، مستبشرًا بما وعده الله من الثواب والغفران، مع ما زال عنه من عُقَد الشيطان وتثبيطه،  وإلا أصبح خبيث النفس، محزون القلب، كسلان عن أعمال الخير والبر؛ لأنه مُقَيَّد بِقَيْد الشيطان، ومُبْعَد عن قُرْبِ الرحمن.', 'الشيطان يسعى دائمًا في كل طريق للإنسان؛ لِيَحُوْلَ بينه وبين طاعة الله عز وجل، ولا نجاة للعبد من الشيطان إلا بالاستعانة بالله عز وجل، والأخذ بأسباب الوقاية والحفظ.
ذكر الله تعالى وعبادته تُوْرِث النشاطَ في النفس وانْشِرَاح الصَّدر، وتَطْرد الكَسَل والخُمُول، وتُذْهِب الكَرْب والمَقْت؛ لأنها تطرد الشيطان وهذا مِن وسوسته.
المؤمن يُسَرُّ بتوفيق الله تعالى له للقيام بطاعته، ويَكْتَئِب لتقصيره في درجات الفضل والكمال.
الغفلة والركون عن الطاعات هو من فعل الشيطان وتزيينه.
هذه الأمور الثلاثة -ذكر الله، والوضوء، والصلاة- تطرد الشيطان.
العَقْد من الشيطان على مُؤخَّر الرأس خاصة؛ لأنها مَركَز القُوى، ومجال تَصَرُّفِها، فإذا رَبَطَ عليها أمكنه السيطرة على رُوح الانسان، وإلقاء النوم عليه.
قال ابن حجر العسقلاني: ذكر الليل في قوله: "عليك ليل"، ظاهره اختصاص ذلك بنوم الليل.
قال ابن حجر العسقلاني: لا يتعين للذكر شيء مخصوص لا يجزئ غيره، بل كل ما صدق عليه ذكر الله أجزأ، ويدخل فيه تلاوة القرآن، وقراءة الحديث النبوي، والاشتغال بالعلم الشرعي، وأولى ما يذكر به قول النبي صلى الله عليه وسلم: من تعار من الليل فقال: (لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير، الحمد لله، وسبحان الله، ولا إله إلا الله، والله أكبر، ولا حول ولا قوة إلا بالله، ثم قال: اللهم اغفر لي، أو دعا استجيب له، فإن توضأ قُبلت صلاته) رواه البخاري.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3731', false),
(21166, 2, 209, 1166, 'hadith', 'عن عبد الله بن سلام، رضي الله عنه ، أن النبي، صلى الله عليه وسلم ،قال: «أيها الناس أفشوا السلام، وأطعموا الطعام، وصلوا بالليل والناس نيام، تدخلوا الجنة بسلام».', 'The Prophet (ﷺ) said, "O people, promote the greetings, feed (the poor and needy) and perform Salat when others are asleep so that you will enter Jannah safely.".', 'عبد الله بن سلام رضي الله عنه', '''Abdullah bin Salam (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1166', 'Riyad as-Salihin 1166', 'ریاض الصالحین 1166', 'رواه الترمذي وقال: حديث حسن صحيح', null, null, null, 'sunnah.com', null, false, null, false),
(21167, 2, 209, 1167, 'hadith', 'عن أبي هريرة، رضي الله عنه، قال: قال رسول الله صلى الله عليه وسلم : «أفضل الصيام بعد رمضان شهر الله المحرم، وأفضل الصلاة بعد الفريضة صلاة الليل».', 'The Messenger of Allah (ﷺ) said, "The best month for observing Saum (fasting) after Ramadan is Muharram, and the best Salat after the prescribed Salat is Salat at night.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1167', 'Riyad as-Salihin 1167', 'ریاض الصالحین 1167', 'رواه مسلم', 'أن صوم شهر مُحرم، وهو أول شهور السنة الهجرية أفضل الصيام بعد صوم رمضان؛ لأنه أول السَّنة المستأنفة فافتتاحها بالصوم الذي هو ضياء أفضل الأعمال؛ فينبغي للمسلم أن يحرص عليه ولا يَدعه إلا لعُذر.
وقوله: "شَهر الله" هذا مما يدل على تعظيمه ومَزيته على غيره من الشَّهور. 
وأن صلاة الليل أفضل التَّطوعات بعد الفريضة؛ لأن الخشوع فيه أوفر لاجتماع القلب والخلو بالرَّب قال تعالى:{ إِنَّ نَاشِئَةَ اللَّيْلِ هِيَ أَشَدُّ وَطْئًا وَأَقْوَمُ قِيلًا}، [ سورة المزمل : 6 ]، ولأن الليل وقت السُّكون والرَّاحة فإذا صُرف إلى العِبادة كانت على النَّفْس أشد وأشق وللبدن أتَعب وأنْصَب فكانت أدخل في معنى التكليف وأفضل عند الله.', 'التَّرغيب في صيام التطوع.
التَّرغيب في صلاة التطوع.
التَّرغيب في قيام الليل.
أن صلاة الليل أفضل من غيرها من التَّطوعات في النَّهار؛ لظاهر النَّص.
أن أفضل الصيام المستحب ما كان في محرم كصيام عاشوراء وغيره.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/11261', false),
(21168, 2, 209, 1168, 'hadith', 'عن ابن عمر رضي الله عنهما، أن النبي صلى الله عليه وسلم ، قال: «صلاة الليل مثنى مثنى، فإذا خفت الصبح فأوتر بواحدة».', 'The Prophet (ﷺ) said, "Salat during the night should consist of pairs of but if you fear that morning is near, then pray one Rak''ah as Witr.".', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1168', 'Riyad as-Salihin 1168', 'ریاض الصالحین 1168', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21169, 2, 209, 1169, 'hadith', 'وعنه قال: كان النبي صلى الله عليه وسلم ، يصلي من الليل مثنى مثنى، ويوتر بركعة.', 'The Prophet (ﷺ) performed the night prayer in pairs (i.e., Rak''ah) and made it odd number by observing one Rak''ah (as Witr)..', null, 'Ibn ''Umar (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1169', 'Riyad as-Salihin 1169', 'ریاض الصالحین 1169', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21170, 2, 209, 1170, 'hadith', 'عن أنس رضي الله عنه، قال: كان رسول الله صلى الله عليه وسلم ، يفطر من الشهر حتى نظن أن لا يصوم منه، ويصوم حتى نظن أن لا يفطر منه شيئًا، وكان لا تشاء أن تراه من الليل مصليا إلا رأيته، ولا نائمًا إلا رأيته.', 'The Messenger of Allah (ﷺ) used to leave off observing Saum (fasting) during a month until we thought that he would not observe Saum at all during it; and (sometimes) he would observe Saum till we began to think that he would not omit any day of that month. If one wished to see him performing Salat during the night, he could do that; and if one wished to see him sleeping at night, he could do that..', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1170', 'Riyad as-Salihin 1170', 'ریاض الصالحین 1170', 'رواه البخاري', 'معنى الحديث: يخبر أنس رضي الله عنه عن حال النبي صلى الله عليه وسلم في صيامه وقيامه، فيخبر أنه كان يُفْطِرُ من الشهر حتى يظن المرء أنه لا يصوم منه شيئا؛ لكثرة فطره فيه، ويصوم حتى يُظن أنه لا يُفْطِر منه شيئًا؛ لكثرة صيامه فيه، و كذلك كان عليه -الصلاة والسلام- لا يَتَقَيَد بوقت معين في صلاة القيام، بل يصلي تارة في أول الليل، وتارة في وسطه، وتارة في آخره، بحيث لا تُحب أن تراه من الليل مصليًا إلا رأيته، ولا نائمًا إلا رأيته، فكان عَمَله التَوَسط بين الإفْرَاطِ والتفريط.', 'صوم النفل المطلق لا يختص بزمان إلا ما نهي عنه.
الحث على الإكثار من العبادة وخاصة صيام النفل والتهجد مع  التَوسط في ذلك، بحيث لا يضيع الحقوق أو يُقَصِّر في الواجبات.
لم يَصم رسول الله -صلى الله عليه وسلم- الدَّهر، ولا قام الليل كله.
من كُلِّ الليل قام رسول الله -صلى الله عليه وسلم-، ومن كل الشهر صام رسول الله -صلى الله عليه وسلم-.', 'لا تشاء : لا تحب.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3769', false),
(21171, 2, 209, 1171, 'hadith', 'عن عائشة رضي الله عنها، أن رسول الله صلى الله عليه وسلم، كان يصلي إحدى عشرة ركعة- تعني في الليل- يسجد السجدة من ذلك قدر ما يقرأ أحدكم خمسين آية قبل أن يرفع رأسه، ويركع ركعتين قبل صلاة الفجر، ثم يضطجع على شقه الأيمن حتى يأتيه المنادي للصلاة.', 'The Messenger of Allah (ﷺ) used to perform eleven Rak''ah (of Tahajjud) prayers at night. He (ﷺ) would prostrate so long as one of you might recite fifty Ayat (of the Qur''an). Thereafter, he would perform two Rak''ah before Fajr prayers and would lie down on his right side till the Mu''adhdhin would come and inform him about the time of (Fajr) prayer..', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 1171', 'Riyad as-Salihin 1171', 'ریاض الصالحین 1171', 'رواه البخاري', 'أخبرت عائشة رضي الله عنها أن صلاة النبي صلى الله عليه وسلم بالليل إحدى عشرة ركعة، ثم بيّنت كيفية صلاته وبأنه يسجد سجودًا طويًلا، فمقدار سجوده في الصلاة بقدر قراءة خمسين آية، ويصلي سنة الفجر ركعتين ثم يرقد للاستراحة من مكابدة الليل، ومجاهدة التهجد، على شقه الأيمن لأنه عليه الصلاة والسلام كان يحب التيامن في شأنه كله، حتى يناديه بلال مستئذنًا لأن يقيم لصلاة الصبح؛ لأنها راجعة بأمر الإمام.', 'استحباب قيام الليل.
استحباب تطويل السجود في قيام الليل.
مشروعية الاضطجاع بعد ركعتي الفجر.
المستحب في الاضطجاع أن يكون على شقه الأيمن.
استحباب اتخاذ مؤذن راتب للمسجد.
جواز إعلام المؤذن الإمام بحضور الصلاة وإقامتها.
استحباب سنة الصبح وتخفيفهما.', 'قدر ما يقرأ: بمقدار قراءته.
يضطجع: يرقد.
شقه: جنبه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65727', false),
(21172, 2, 209, 1172, 'hadith', 'وعنها قالت: ما كان رسول الله صلى الله عليه وسلم ، يزيد- في رمضان ولا في غيره- على إحدي عشرة ركعة: يصلي أربعًا فلا تسأل عن حسنهن وطولهن! ثم يصلي أربعًا فلا تسأل عن حسنهن وطولهن! ثم يصلي ثلاثًا. فقلت: يا رسول الله أتنام قبل أن توتر!؟ فقال: «يا عائشة إن عيني تنامان ولا ينام قلبي».', 'The Messenger of Allah (ﷺ) did not observe more than eleven Rak''ah (of Tahajjud prayers), be in Ramadan or any other month. First of all he would perform four Rak''ah. Ask not about their excellence and their length. He (ﷺ) would then perform four more Rak''ah; and do not ask about their excellence and their length. Then he would perform three Rak''ah (Witr prayer). (''Aishah (May Allah be pleased with her) added) I submitted: "O Messenger of Allah! Do you sleep before performing the Witr prayer?" He (ﷺ) said, "O ''Aishah! My eyes sleep but my heart does not sleep.".', null, '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 1172', 'Riyad as-Salihin 1172', 'ریاض الصالحین 1172', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21173, 2, 209, 1173, 'hadith', 'وعنها أن النبي صلى الله عليه وسلم، كان ينام أول الليل، ويقوم آخره فيصلي.', 'The Prophet (ﷺ) would sleep during the early part of night and stand in Salat during the latter part..', null, '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 1173', 'Riyad as-Salihin 1173', 'ریاض الصالحین 1173', 'متفق عليه', 'تُخبر عائشة رضي الله عنها أن النبي صلى الله عليه وسلم كان ينام أول الليل، وذلك بعد صلاة العشاء، ويقوم آخره، وهو: الثلث الثاني من الليل، فإذا فَرَغ من صلاته، رجع إلى فراشه ليَنَام، وذلك في السُدس الأخير من الليل؛ ليستريح بَدَنه من عَنَاء قيام الليل، وفيه من المصلحة أيضاً استقبال صلاة الصبح، وأذكار النهار بنشاط وإقبال، ولأنه أقرب إلى عدم الرياء؛ لأن من نام السدس الأخير أصبح ظاهر اللون سليم القوى، فهو أقرب إلى أن يخفي عمله الماضي عمن يراه.
ولهذا جاء أن الأذان الأول؛ ليوقظ النائم ويرجع القائم، فالقائم يرجع إلى النوم؛ ليَكتَسِب بدنه قوة ونشاطاً، وأما النائم، فيستيقظ حتى يَستعد للصلاة، وحتى يصلي وتره إذا لم يوتر أول الليل.', 'كراهية قيام الليل كله، وأن الأفضل أن ينام جزءاً من الليل، ويقوم جزءا منه؛ دفعًا للملل والكسل.
الأفضل أن يكون القيام في الجزء الأخير من الليل؛ ليكون أنشط في العبادة.
آخر الليل أرْجَى في إجابة الدعاء.
بيان الوقت الذي كان يقوم فيه -صلى الله عليه وسلم- من الليل.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4247', false),
(21174, 2, 209, 1174, 'hadith', 'عن ابن مسعود رضي الله عنه، قال: صليت مع النبي صلى الله عليه وسلم ، ليلة، فلم يزل قائمًا حتى هممت بأمر سوء. قيل: ما هممت؟ قال: هممت أن أجلس وأدعه.', 'One night I joined the Prophet (ﷺ) in his (optional) Salat. He (ﷺ) prolonged the Qiyam (standing) so much that I made up my mind to commit an act of wrong. He was questioned: "What did you intend to do?" He replied: "I intended to sit down and stop following him (in Salat).".', 'ابن مسعود رضي الله عنه', 'Ibn Mas''ud (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1174', 'Riyad as-Salihin 1174', 'ریاض الصالحین 1174', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21175, 2, 209, 1175, 'hadith', 'عن حذيفة رضي الله عنه، قال: صليت مع النبي صلى الله عليه وسلم ، ذات ليلة فافتتح البقرة، فقلت: يركع عند المائة، ثم مضى، فقلت: يصلي بها في ركعة، فمضي، فقلت: يركع بها، ثم افتتح النساء فقرأها، ثم افتتح آل عمران، فقرأها، يقرأ مترسلا. إذا مر بآية فيها تسبيح سبح، وإذا بسؤال سأل، وإذا مر بتعوذ تعوذ، ثم ركع، فجعل يقول: سبحان ربي العظيم، فكان ركوعه نحوًا من قيامه، ثم قال: سمع الله لمن حمده، ربنا لك الحمد، ثم قام طويلا قريبًا مما ركع، ثم سجد فقال: سبحان ربي الأعلى، فكان سجوده قريبًا من قيامه.', 'I performed Salat with the Prophet (ﷺ) one night, and he started reciting Surat Al- Baqarah. I thought that he would go in Ruku'' (bowing posture in Salat) at the end of one hundred Ayat, but he continued (reciting); and I thought that he would perhaps recite (this Surah) in the whole Rak''ah (prayer), but he continued the recitation; I thought he would perhaps bow on completing (this Surah). He (ﷺ) then started reciting Surat An-Nisa'' which he followed with Surat Al-Imran. He recited leisurely. When he recited an Ayah which mentioned the tasbeeh, he would say Subhan Allah and when he recited the Ayah which tells how the Rubb is to be asked, the Messenger of Allah (ﷺ) would then ask from Him; and when he (ﷺ) recited an Ayah asking one to seek Protection Allah, he would seek Protection of Allah. Then he bowed and said, "Subhana Rabbiyal-Azim (My Rubb the Great is free from imperfection)"; his bowing lasted about the same length of time as his standing, (and then on returning to the standing posture after Ruku'') he would say, "Sami'' Allahu liman hamidah, Rabbana lakal-hamd (Allah listens to him who praises Him. Praise be to You, Our Rubb!)," and he would then stand about the same length of time as he had spent in bowing. He would then prostrate himself and say, "Subhana Rabbiyal-A''la (My Rubb the Supreme is free from imperfection)," and his prostration lasted nearly the same length of time as his standing (Qiyam)..', 'حذيفة رضي الله عنه', 'Hudhaifah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1175', 'Riyad as-Salihin 1175', 'ریاض الصالحین 1175', 'رواه مسلم', 'يخبر حُذيفة رضي الله عنه أنه صلَّى مع النبي صلى الله عليه وسلم صلاة الليل وأنه كان يقول في رُكوعه: "سُبحان رَبِّيَ العظيم"، وفي سجوده: "سُبحان رَبِّيَ الأعلى" وهذا يدل على مشروعية هذا الذِّكر في الرَّكوع والسَّجود،" كان يقول في رُكوعه: "سُبحان رَبِّيَ العظيم "، وفي سجوده: "سُبحان رَبِّيَ الأعلى "، "وما مَرَّ بآية رَحْمَة إلا وقَف عِندها فَسأل"
يعني: عندما يمرُّ بآية فيها ذِكر الجنَّة والنَّعيم، لا يتجاوزها حتى يسأل الله تعالى، فيقول: اللَّهم إني أسألك الجنَّة، وله أن يسأل الله تعالى من فَضْلِه، ولو مَرَّ ثناء على الأنبياء أو الأولياء أو ما أشبه ذلك، فله أن يقول: أسأل الله من فضله، أو أسأل الله أن يُلحقني بهم، أو ما أشبه ذلك. 
"ولا بآية عَذاب إلا وقَف عِندها فتعوَّذ "
أي: عندما يَمرُّ بآية فيه ذِكر العذاب وذِكر جهنَّم وأحوال أهلها، لا يتجاوزها حتى يَستعيذ من ذلك.
فيستحب التأسِّي به صلى الله عليه وسلم لكن خَصَّه جمع من العلماء بصلاة النافلة؛ لأنه لم يُنقل عنه صلى الله عليه وسلم ذلك في الفَرض مع كَثرة من وصف قراءته في صلاة الفَريضة، وإن أتى به في الفرض أحيانا فلا بأس؛ لأن ما ثبت في الفرض جاز في النفل وبالعكس إلا إذا دل دليل على التخصيص.', 'جواز صلاة الجماعة في قيام الليل، ما لم  يُتخذ ذلك عادة؛ لأن النبي -صلى الله عليه وسلم- لم يواظب على قيام الليل جماعة.
وجوب قول: "سُبحان رَبِّيَ العظيم" في الركوع ، و "سُبحان رَبِّيَ الأعلى" في السُّجود.
مشروعية الجَهر بالقراءة في الصلاة الليل؛ لأن حذيفة ذكر عن النبي -صلى الله عليه وسلم- أنه كان يسأل عند آية الرَّحمة ويستعيذ عند آية العذاب، وهذا يدل على أنه كان يَسمعه.
استحباب التَّعوذ بالله -تعالى- حينما يمرَّ بآية عَذاب، أو وعِيد، أو نحو ذلك، وسؤال الرَّحمة حينما يمرُّ بآية رحمة، فهو دُعاء مُناسب للمقَام.
استحباب تَدَبُّر القرآن وتَفَهُّم معانيه، سواء كان قارئًا أو مستمعًا، فهذه هي القراءة المُفيدة النَّافعة.
أن النبي -صلى الله عليه وسلم- بَشَر ليس له شيء من شؤون الرُّبوبية، بدليل أنه يَسأل الله -عز وجل- أن يَرحمه وأن يُعيذه من النَّار.
فضيلة حذيفة -رضي الله عنه- حيث حصل له شرف الصلاة مع رسول الله -صلى الله عليه وسلم-.', 'سُبحان الله : تنزيه الله عَمَّا لا يَليق به من نَقص أو عَيْب.
العظيم : وصْفُه تعالى بصِفات العظَمة، والإجْلَال، والكِبْرِيَاء.
آية رَحْمَة : مما فيه وعْد وبشارة بالجَنَّة، ونعيمها، ورضوان الله فيها.
آية عَذاب : مما فيه وعِيد، وتخويف من عَذاب الله، وغضبِه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/10921', false),
(21176, 2, 209, 1176, 'hadith', 'عن جابر رضي الله عنه قال: سئل رسول الله صلى الله عليه وسلم : أي الصلاة أفضل؟ قال: «طول القنوت».', 'The Messenger of Allah (ﷺ) was asked: "Which Salat is the best?" He replied, " The best Salat is that in which Qiyam (the duration of standing) is longer.".', 'جابر رضي الله عنه', 'Jabir (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1176', 'Riyad as-Salihin 1176', 'ریاض الصالحین 1176', 'رواه مسلم', 'سأل الصحابة رضوان الله عليهم النبي صلى الله عليه وسلم: أي الصلاة أفضل؟ وهذا السؤال من حرصهم على إصابة أكثر قدر من الحسنات، والمراد به: أي أنواع الصلوات أفضل؟ أو: أي أعمال الصلاة أفضل؟ القيام أم الركوع أم السجود؟ فأخبر صلى الله عليه وسلم أنه طول القيام فيها.', 'أن تطويل القيام في الصلاة أفضل من تطويل الركوع والسجود، على قول، وقيل طول السجود؛ لأن أقرب ما يكون العبد من ربه في حال السجود.', 'القنوت : القيام.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3569', false),
(21177, 2, 209, 1177, 'hadith', 'عن عبد الله بن عمرو بن العاص، رضي الله عنهما، أن رسول الله صلى الله عليه وسلم ، قال: «أحب الصلاة إلى الله صلاة داود، وأحب الصيام إلى الله صيام داود، كان ينام نصف الليل ويقوم ثلثه وينام سدسه ويصوم يومًا ويفطر يومًا».', 'The Messenger of Allah (ﷺ) said, "The Salat which is dearest to Allah is that of (Prophet) Dawud; and As-Saum (the fasting) which is dearest to Allah is that of (Prophet) Dawud. He used to sleep half the night, get up to perform Salat for one-third of it, then sleep through the remaining one-sixth of it; and he used to observe Saum on alternative days.".', 'عبد الله بن عمرو بن العاص رضي الله عنهما', '''Abdullah bin ''Amr (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1177', 'Riyad as-Salihin 1177', 'ریاض الصالحین 1177', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21178, 2, 209, 1178, 'hadith', 'عن جابر رضي اللله عنه قال: سمعت رسول الله صلى الله عليه وسلم ، يقول: «إن في الليل لساعة، لا يوافقها رجل مسلم يسأل الله تعالى خيرًا من أمر الدنيا والآخرة، إلا أعطاه إياه، وذلك كل ليلة».', 'I heard the Messenger of Allah (ﷺ) saying, "Every night there is a special time during which whatever a Muslim asks Allah of any good relating to this life or the Hereafter, it will be granted to him; and this moment comes every night.".', null, 'Jabir (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1178', 'Riyad as-Salihin 1178', 'ریاض الصالحین 1178', 'رواه مسلم', 'في كل ليلة ساعة يُستجاب فيها الدعاء، فلا يصادفها عبد مسلم لا يدعو فيها بمحرم إلا استجاب الله دعاءه، وهي ثلث الليل الآخر، كما في النصوص الصحيحة الأخرى.', 'الحث على القيام في الليل، أي ساعة من ساعاته.
إثبات ساعة الإجابة في كل ليلة، وذلك في الثلث الأخير منها.', 'ساعة : فترة من الزمن.
يوافقها : يصادفها.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3625', false),
(21179, 2, 209, 1179, 'hadith', 'عن أبي هريرة رضي الله عنه، أن النبي صلى الله عليه وسلم، قال: «إذا قام أحدكم من الليل فليفتتح الصلاة بركعتين خفيفتين».', 'The Prophet (ﷺ) said, "When one of you gets up at night to perform (Tahajjud) prayer, let him start Salat with two short Rak''ah.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1179', 'Riyad as-Salihin 1179', 'ریاض الصالحین 1179', 'رواه مسلم', 'هذا الحديث: فيه بيان أن السُنَّة في صلاة الليل أن تُفتتح بركعتين خَفِيفَتين، ثم بعد ذلك يُطَوِّل ما شاء، كما هي رواية أبي داود، عن أبي هريرة رضي الله عنه موقوفًا عليه: "ثم ليُطَول بعد ما شاء".
وقد صح ذلك من فعله صلى الله عليه وسلم كما هي رواية مسلم.
والحكمة من افتتاح صلاة الليل بركعتين خَفِيفَتَين تمرين النفس وتهيئتها للاستمرار في الصلاة والمبادرة إلى حَلِّ عُقَد الشيطان؛ لأن حَلَّ العُقد كلها لا يتم إلا بإتمام الصلاة؛ وأما ما جاء عنه صلى الله عليه وسلم من افتتاحه صلاة الليل بركعتين خَفِيفَتَين، مع كونه محفوظاً ومُنَزَهاً عن عُقَد الشيطان، فهذا من باب تعليم أمته وإرشادهم إلى ما يحفظهم من الشيطان.
فصحت بذلك السنة القولية والفعلية على مشروعية افتتاح صلاة الليل بركعتين خفيفتين.', 'استحباب افتتاح قيام الليل بركعتين خفيفتين؛ امتثالا لأمر النبي -صلى الله عليه وسلم-، وأقل أحوال الأمر الاستحباب.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3543', false),
(21180, 2, 209, 1180, 'hadith', 'عن عائشة رضي الله عنها قالت كان رسول الله صلى الله عليه وسلم إذا قام من الليل افتتح صلاته بركعتين خفيفتين.', 'Whenever the Messenger of Allah (ﷺ) stood for Salat at night, he would start his prayer with two brief Rak''ah..', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 1180', 'Riyad as-Salihin 1180', 'ریاض الصالحین 1180', 'رواه مسلم', 'هذا الحديث: فيه بيان أن السُنَّة في صلاة الليل أن تُفتتح بركعتين خَفِيفَتين، ثم بعد ذلك يُطَوِّل ما شاء، كما هي رواية أبي داود، عن أبي هريرة رضي الله عنه موقوفًا عليه: "ثم ليُطَول بعد ما شاء".
وقد صح ذلك من فعله صلى الله عليه وسلم كما هي رواية مسلم.
والحكمة من افتتاح صلاة الليل بركعتين خَفِيفَتَين تمرين النفس وتهيئتها للاستمرار في الصلاة والمبادرة إلى حَلِّ عُقَد الشيطان؛ لأن حَلَّ العُقد كلها لا يتم إلا بإتمام الصلاة؛ وأما ما جاء عنه صلى الله عليه وسلم من افتتاحه صلاة الليل بركعتين خَفِيفَتَين، مع كونه محفوظاً ومُنَزَهاً عن عُقَد الشيطان، فهذا من باب تعليم أمته وإرشادهم إلى ما يحفظهم من الشيطان.
فصحت بذلك السنة القولية والفعلية على مشروعية افتتاح صلاة الليل بركعتين خفيفتين.', 'استحباب افتتاح قيام الليل بركعتين خفيفتين؛ امتثالا لأمر النبي -صلى الله عليه وسلم-، وأقل أحوال الأمر الاستحباب.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3543', false),
(21181, 2, 209, 1181, 'hadith', 'وعنها رضي الله عنها، قالت: كان رسول الله صلى الله عليه وسلم ، إذا فاتته الصلاة من الليل من وجع أو غيره، صلى من النهار ثنتي عشر ركعة.', 'If the Messenger of Allah (ﷺ) missed his night (Tahajjud) Salat because of indisposition or the like, he would perform twelve Rak''ah during the day..', null, '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 1181', 'Riyad as-Salihin 1181', 'ریاض الصالحین 1181', 'رواه مسلم', 'كان النبي صلى الله عليه وسلم إذا ترك قيام الليل من وجع أو غيره صلى من النهار ثنتي عشرة ركعة؛ لأنه صلى الله عليه وسلم كان يوتر بإحدى عشر ركعة، فإذا مضى الليل ولم يوتر لنوم أو شبهه؛ فإنه يقضي هذه الصلاة، لكن لما فات وقت الوتر صار المشروع أن يجعله شفعا.', 'صلاة النهار هنا عِوض عن صلاة الليل لجَبْر فضيلتها.
الدليل على جواز قضاء النوافل.
الوتر يقضى في النهار بزيادة ركعة، فيصير شفعا.', 'فاتته الصلاة : مضى وقتها.
وجع : مرض أو ألم.
أو غيره : كغلبة نوم أو عذر أهم منه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4829', false),
(21182, 2, 209, 1182, 'hadith', 'عن عمر بن الخطاب، رضي الله عنه، قال: قال رسول الله صلى الله عليه وسلم : «من نام عن حزبه، أو عن شيء منه، فقرأه فيما بين صلاة الفجر وصلاة الظهر، كتب له كأنما قرأه من الليل».', 'The Messenger of Allah (ﷺ) said: "If anyone falls asleep and therefore fails to observe his Hizb (share) or part of it, if he observes it between the Fajr and the Zuhr prayers, it will be recorded for him as though he had observed it during the night.".', 'عمر بن الخطاب رضي الله عنه', '''Umar bin Al-Khattab (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1182', 'Riyad as-Salihin 1182', 'ریاض الصالحین 1182', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21183, 2, 209, 1183, 'hadith', 'عن أبي هريرة رضي الله عنه، قال رسول الله صلى الله عليه وسلم : «رحم الله رجلا قام من الليل، فصلى وأيقظ امرأته، فإن أبت نضح في وجهها الماء، ورحم الله امرأة قامت من الليل فصلت، وأيقظت زوجها فإن أبي نضحت في وجهه الماء».', 'The Messenger of Allah (ﷺ) said, "May Allah show mercy to a man who gets up during the night and performs Salat, awakens his wife to pray and if she refuses, he sprinkles water on her face (to make her get up). May Allah show mercy to a woman who gets up during the night and performs Salat, awakens her husband for the same purpose; and if he refuses, she sprinkles water on his face.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'حسن', 'رياض الصالحين 1183', 'Riyad as-Salihin 1183', 'ریاض الصالحین 1183', 'رواه أبو داود بإسناد صحيح', 'أخبر النبي صلى الله عليه وسلم أن من قام من الليل فصلى وأيقظ زوجته للصلاة، فامتَنَعت من الاستيقاظ؛ لغَلَبة النوم، وكثرة الكسل؛ فرش على وجْهِها الماء رشًا خفيفًا؛ فإنه مستحق لرحمة الله تعالى وكذا العكس إذا فعلت المرأة ذلك مع زوجها.', 'الحث على التعاون على الطاعة والعمل الصالح.
استحباب إيقاظ كل من الزوجين الآخر لقيام الليل، والاستعانة على ذلك بما يُذهب عنه النوم الغالب.
إشارة إلى أن الرَجُل والمرأة في العبادة سواء، إلا ما دل الدليل على التفريق بينهما.
أن من أصاب خيراً ينبغي له أن يتحرى إصابة الغير، وأن يُحب له ما يُحب لنفسه، فيأخذ بالأقرب فالأقرب.', 'نضح في وجهها الماء : رش في وجهها الماء.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3717', false),
(21184, 2, 209, 1184, 'hadith', 'وعنه وعن أبي سعيد رضي الله عنهما، قالا: قال رسول الله صلى الله عليه وسلم : «إذا أيقظ الرجل أهله من الليل فصليا أو صلى ركعتين جميعًا كتب في الذاكرين والذاكرات».', 'The Messenger of Allah (ﷺ) said, "When a man awakens his wife during the night and they both perform two Rak''ah Salat together, they are recorded among the men and women who celebrate remembrance of Allah.".', null, 'Abu Sa''id and Abu Hurairah (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1184', 'Riyad as-Salihin 1184', 'ریاض الصالحین 1184', 'رواه أبو داود بإسناد صحيح', null, null, null, 'sunnah.com', null, false, null, false),
(21185, 2, 209, 1185, 'hadith', 'عن عائشة رضي الله عنها، أن النبي صلى الله عليه وسلم قال: « إذا نعس أحدكم في الصلاة، فليرقد حتى يذهب عنه النوم، فإن أحدكم إذا صلى وهو ناعس، لعله يذهب يستغفر فيسب نفسه».', 'The Prophet (ﷺ) said, "When one of you dozes off while performing Salat, he should lie down till his drowsiness has gone away from him. When one of you performs Salat while dozing, he may abuse himself instead of seeking pardon (as a result of drowsiness).".', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 1185', 'Riyad as-Salihin 1185', 'ریاض الصالحین 1185', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21186, 2, 209, 1186, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «إذا قام أحدكم، من الليل فاستعجم القرآن على لسانه، فلم يدرِ ما يقول، فليضطجع».', 'The Messenger of Allah (ﷺ) said, "When anyone of you stands up for Salat at night and finds it difficult to recite the Qur''an accurately and he is unaware of what he is reciting, he should go back to sleep.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1186', 'Riyad as-Salihin 1186', 'ریاض الصالحین 1186', 'رواه مسلم', 'معنى الحديث: أن العَبد إذا كان في صلاة الليل، فصعبت عليه قراءة القرآن؛ لغلبة النعاس عليه، حتى صار لا يَدْري ما يقول، فَلْيَضْطَجِع، حتى يَذْهب عنه النوم؛ لئلا يُغَيِّر كلام الله، ويبدله ولعله يَأتي بما لا يجوز، من قَلْب مَعانيه، وتحريف كلماته، وربما يدعو على نفسه.
وفي البخاري عن أنس رضي الله عنه مرفوعًا: "إذا نعس أحدكم في الصلاة فليَنَم، حتى يَعلم ما يَقرأ".', 'الحث على الصلاة في الليل حال النشاط والقدرة على الفَهم والخشوع، واستحضار القلب مع الله -عز وجل-.
أن فضل التهجد في الليل لا يتحقق مع النُعاس والكسل، وأن الصلاة في هذه الحال مكروهة.
يتعين لمن داهمه النعاس أثناء صلاة الليل أن ينام قليلاً؛ ليستعيد به نشاطه.
يقاس على النُعاس في الكراهة كل شاغل يشغله عن الخشوع، ويقاس على صلاة الليل سائر تطوعات الصلاة.
ينبغي على العبد قراءة القرآن قراءة تدبر وفهم.
كراهية قيام الليل والمرء ناعس لأن الجسد له حق على الانسان.', 'استعجم القرآن على لسانه : استغلق  ولم ينطلق به لسانه لغلبة النعاس.
فليضطجع : فلينم.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3734', false),
(21187, 2, 209, 1187, 'hadith', 'عن أبي هريرة رضي الله عنه، أن رسول الله صلى الله عليه وسلم قال: «من قام رمضان إيمانًا واحتسابًا غفر له ما تقدم من ذنبه».', 'The Messenger of Allah (ﷺ) said, "He who observes optional prayer (Tarawih prayers) throughout Ramadan, out of sincerity of Faith and in the hope of earning reward will have his past sins pardoned.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1187', 'Riyad as-Salihin 1187', 'ریاض الصالحین 1187', 'متفق عليه', 'روى أبو هريرة أن النبي صلى الله عليه وسلم ذكر فضل قيام ليالي رمضان، فأخبر عليه الصلاة والسلام أن من قام أي صلى في الليل، كصلاة التراويح أو مطلق القيام في رمضان، مؤمنًا بالله مصدقًا به، ومريدًا به وجه الله تعالى، لا رياءً ولا سمعةً، غفر الله له ما تقدم من ذنبه من الصغائر، وما كان غير الحقوق الآدمية؛ لأن الإجماع قائم على أنها لا تسقط إلا برضاهم، وفي فضل الله وسعة كرمه ما يؤذن بغفران الكبائر أيضًا، وهو ظاهر السياق، لكنهم أجمعوا على التخصيص بالصغائر كنظائره من إطلاق الغفران في أحاديث لما وقع من التقييد في بعضها بما اجتنبت الكبائر، وهي لا تسقط إلا بالتوبة أو الحد.', 'فضل وثواب العمل الصالح في رمضان.

الحث على الإخلاص واحتساب الثواب في العمل الصالح.

الحقوق الآدمية لا تسقط إلا برضا أصحاب الحقوق.

سعة الله وفضله ومغفرته لعباده.', 'قام: أحياه بالصلاة وقراءة القرآن.

احتسابًا: تصديقًا بفضله وابتغاء وجه الله -عزوجل-.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65512', false),
(21188, 2, 209, 1188, 'hadith', 'وعنه، رضي الله عنه قال: كان رسول الله صلى الله عليه وسلم، يرغب في قيام رمضان من غير أن يأمرهم فيه بعزيمة، فيقول: «من قام رمضان إيمانًا واحتسابًا غفر له ما تقدم من ذنبه».', 'The Messenger of Allah (ﷺ) used to urge (the people) to perform (optional Tarawih) prayer at night during the month of Ramadan. He did not order them or make it obligatory on them. He (ﷺ) said, "Whosoever performs (optional Tarawih) prayers at night during the month of Ramadan, with Faith and in the hope of receiving Allah''s reward, will have his past sins forgiven.".', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1188', 'Riyad as-Salihin 1188', 'ریاض الصالحین 1188', 'رواه مسلم', 'روى أبو هريرة أن النبي صلى الله عليه وسلم ذكر فضل قيام ليالي رمضان، فأخبر عليه الصلاة والسلام أن من قام أي صلى في الليل، كصلاة التراويح أو مطلق القيام في رمضان، مؤمنًا بالله مصدقًا به، ومريدًا به وجه الله تعالى، لا رياءً ولا سمعةً، غفر الله له ما تقدم من ذنبه من الصغائر، وما كان غير الحقوق الآدمية؛ لأن الإجماع قائم على أنها لا تسقط إلا برضاهم، وفي فضل الله وسعة كرمه ما يؤذن بغفران الكبائر أيضًا، وهو ظاهر السياق، لكنهم أجمعوا على التخصيص بالصغائر كنظائره من إطلاق الغفران في أحاديث لما وقع من التقييد في بعضها بما اجتنبت الكبائر، وهي لا تسقط إلا بالتوبة أو الحد.', 'فضل وثواب العمل الصالح في رمضان.

الحث على الإخلاص واحتساب الثواب في العمل الصالح.

الحقوق الآدمية لا تسقط إلا برضا أصحاب الحقوق.

سعة الله وفضله ومغفرته لعباده.', 'قام: أحياه بالصلاة وقراءة القرآن.

احتسابًا: تصديقًا بفضله وابتغاء وجه الله -عزوجل-.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65512', false),
(21189, 2, 209, 1189, 'hadith', 'عن أبي هريرة رضي الله عنه، عن النبي صلى الله عليه وسلم قال: «من قام ليلة القدر إيمانا واحتسابًا غفر له ما تقدم من ذنبه».', 'The Prophet (ﷺ) said, "Whosoever performs Qiyam during Lailat-ul-Qadr (Night of Decree), with Faith and being hopeful of Allah''s reward, will have his former sins forgiven.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1189', 'Riyad as-Salihin 1189', 'ریاض الصالحین 1189', 'متفق عليه', 'يُخبِرُ النبيُّ صلى الله عليه وسلم عن فضل قيام ليلة القدر التي تكون في العشر الأواخر من رمضان، وأنَّ مَن اجتهد فيها بالصلاة والدعاء وقراءة القرآن والذكر، مؤمنًا بها وبما جاء في فضلها، راجيًا بعمله ثوابَ الله تعالى، لا رياء ولا سُمعة، فإنه يُغفر له ما سَبَقَ مِن ذنوبِه.', 'فضل ليلة القَدْر والحَث على  قيامها.
الأعمال الصالحة لا تُقبل إلا مع صِدْقِ النيَّات.
فضل الله ورحمته، فإنّ مَن قام ليلة القدر إيمانًا واحتسابًا غُفر له ما تقدم من ذنبه.', 'إيمانًا: تصديقًا بالله وبوعده.
احتسابًا: طلبًا للثواب والأجر من الله عز وجل.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4202', false),
(21190, 2, 209, 1190, 'hadith', 'عن ابن عمر رضي الله عنهما أن رجالا من أصحاب النبي صلى الله عليه وسلم، أروا ليلة القدر في المنام في السبع الأواخر، فقال رسول الله صلى الله عليه وسلم : «أرى رؤياكم قد تواطأت في السبع الأواخر، فمن كان متحريها، فليتحرها في السبع الأواخر».', 'Some of the Companions of the Prophet (ﷺ) saw Lailat-ul-Qadr (Night of Decree) in their dreams in the last seven nights of Ramadan, whereupon the Messenger of Allah (ﷺ) said, "I see that your dreams all agree upon the last seven nights. Whosoever seeks it, let him seek it in the last seven nights.".', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1190', 'Riyad as-Salihin 1190', 'ریاض الصالحین 1190', 'متفق عليه', 'رَأى رجالٌ من أصحاب النبيِّ صلى الله عليه وسلم في المنام أنّ ليلة القدر تكون في آخر سبع ليال من رمضان.

فقال صلى الله عليه وسلم: أرى رؤياكم قد توافقت في السبع الأواخر من رمضان، فمن كان قاصدًا لها، حريصًا على طلبها، فليجتهد في تَحَرِّيها وطلبها بالإكثار من العمل الصالح فهي أرجى أن تكون في السبع الأواخر، وهي تبدأ من ليلة أربع وعشرين إذا كان شهر رمضان ثلاثين يومًا، وتبدأ ليلة ثلاث وعشرين إذا كان الشهر تسعة وعشرين يومًا.', 'فضل ليلة القَدْر والحث على تحريها.
من حكمة الله ورحمته أخفى هذه الليلة لِيَجِدَّ الناس في العبادة، طلبًا لها، فيَكثُر ثوابُهم.
ليلة القَدْر في العشر الأواخر من رمضان، وفي السبع الأواخر منه أرجى.
ليلة القدر هي إحدى ليالي العشر الأواخر من رمضان، وهي الليلة التي أنزل الله عز وجل فيها القرآن على النبي صلى الله عليه وسلم، وجعل هذه الليلة خيرًا من ألف شهر في بركتها، وعظيم قدرها، وأثر العمل الصالح فيها.
سميت (ليلة القدْر) بسكون الدال بذلك، إما من الشرف فيُقال: فلان عظيم القدر، فتكون إضافة الليلة من باب إضافة الشيء إلى صفته، أي الليلة الشريفة، يعني أنها عظيمة القدر شرفًا وفخامة ومكانة إلى آخره، ﴿ إِنَّا أَنْزَلْنَاهُ فِي لَيْلَةٍ مُبَارَكَةٍ ﴾ [الدخان: 3]، وإما من التقدير: فتكون إضافتها إليه من إضافة الظرف إلى ما يحتويه، أي هذه الليلة التي يكون فيها تقدير ما يجري في السنة، ﴿ فِيهَا يُفْرَقُ كُلُّ أَمْرٍ حَكِيمٍ ﴾ [الدخان: 4].', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4545', false),
(21191, 2, 209, 1191, 'hadith', 'عن عائشة رضي الله عنها، قالت: كان رسول الله صلى الله عليه وسلم يجاور في العشر الأواخر من رمضان، ويقول: «تحروا ليلة القدر في العشر الأواخر من رمضان».', 'The Messenger of Allah (ﷺ) used to seclude himself (in the mosque) during the last ten nights of Ramadan. He would say, "Search for Lailat-ul-Qadr (Night of Decree) in the last ten nights of Ramadan.".', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 1191', 'Riyad as-Salihin 1191', 'ریاض الصالحین 1191', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21192, 2, 209, 1192, 'hadith', 'وعنها، رضي الله عنها، أن رسول الله صلى الله عليه وسلم قال: «تحروا ليلة القدر في الوتر من العشر الأواخر من رمضان».', 'The Messenger of Allah (ﷺ) used to observe I''tikaf in the last ten days of Ramadan and say, "Seek Lailat-ul-Qadr (Night of Decree) in the odd nights out of the last ten nights of Ramadan.".', null, '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 1192', 'Riyad as-Salihin 1192', 'ریاض الصالحین 1192', 'رواه البخاري', 'حَثَّ النبيُّ صلى الله عليه وسلم على الاجتهاد في التماس وتَحرِّي وطلب ليلة القدر بالإكثار من العمل الصالح، وهي أرجى أن تكون في الليالي الوترية من العشر الأواخر من رمضان كل عام، وهي: الحادية والعشرون، والثالثة والعشرون، والخامسة والعشرون، والسابعة والعشرون، والتاسعة والعشرون.', 'فضل ليلة القَدْر والحثّ على تَحَرِّيها.
من حكمة الله ورحمته أخفى هذه الليلة لِيَجِدَّ الناس في العبادة، طلبًا لها، فيَكثُر ثوابُهم.
ليلة القَدْر في العشر الأواخر من رمضان، وفي الأوتار منه أرجى.
ليلة القدر هي إحدى ليالي العشر الأواخر من رمضان، وهي الليلة التي أنزل الله عز وجل فيها القرآن على النبي صلى الله عليه وسلم، وجعل هذه الليلة خيرًا من ألف شهر في بركتها، وعظيم قدرها، وأثر العمل الصالح فيها.
سميت (ليلة القدْر) بسكون الدال بذلك، إما من الشرف، فيُقال: فلان عظيم القدر، فتكون إضافة الليلة من باب إضافة الشيء إلى صفته، أي الليلة الشريفة، يعني أنها عظيمة القدر شرفًا وفخامة ومكانة إلى آخره، ﴿ إِنَّا أَنْزَلْنَاهُ فِي لَيْلَةٍ مُبَارَكَةٍ ﴾ [الدخان: 3]، وإما من التقدير: فتكون إضافتها إليه من إضافة الظرف إلى ما يحتويه، أي هذه الليلة التي يكون فيها تقدير ما يجري في السنة، ﴿ فِيهَا يُفْرَقُ كُلُّ أَمْرٍ حَكِيمٍ ﴾ [الدخان: 4].', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4540', false),
(21193, 2, 209, 1193, 'hadith', 'وعنها رضي الله عنها، قالت: كان رسول الله صلى الله عليه وسلم : «إذا دخل العشر الأواخر من رمضان، أحيا الليلة، وأيقظ أهله، وجد وشد المئزر».', 'When the last ten nights (of Ramadan) would begin, the Messenger of Allah (ﷺ) would keep awake at night (for prayer and devotion), awaken his family and prepare himself to be more diligent in worship..', null, '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 1193', 'Riyad as-Salihin 1193', 'ریاض الصالحین 1193', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21194, 2, 209, 1194, 'hadith', 'وعنها قالت: كان رسول الله صلى الله عليه وسلم ، يجتهد في رمضان ما لا يجتهد في غيره، وفي العشر الأواخر منه، ما لا يجتهد في غيره".', 'The Messenger of Allah (ﷺ) used to strive more in worship during Ramadan than he strove in any other time of the year; and he would devote himself more (in the worship of Allah) in the last ten nights of Ramadan than he strove in earlier part of the month..', null, '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 1194', 'Riyad as-Salihin 1194', 'ریاض الصالحین 1194', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21195, 2, 209, 1195, 'hadith', 'وعنها قالت: قلت: يا رسول الله أرأيت إن علمت أي ليلة القدر ما أقول فيها؟ قال: «قولي: اللهم إنك عفو تحب العفو فاعفُ عني».', 'I asked: "O Messenger of Allah! If I realize Lailat-ul-Qadr (Night of Decree), what should I supplicate in it?" He (ﷺ) replied, "You should supplicate: Allahumma innaka ''afuwwun, tuhibbul-''afwa, fa''fu ''anni (O Allah, You are Most Forgiving, and You love forgiveness; so forgive me).".', null, '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 1195', 'Riyad as-Salihin 1195', 'ریاض الصالحین 1195', 'رواه الترمذي وقال حديث حسن صحيح', null, null, null, 'sunnah.com', null, false, null, false),
(21196, 2, 209, 1196, 'hadith', 'عن أبي هريرة رضي الله عنه، أن رسول الله صلى الله عليه وسلم قال: «لولا أن أشق على أمتي - أو على الناس- لأمرتهم بالسواك مع كل صلاة».', 'The Messenger of Allah (ﷺ) said, "Had I not thought it difficult for my Ummah, I would have commanded them to use the Miswak (tooth-stick) before every Salat.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1196', 'Riyad as-Salihin 1196', 'ریاض الصالحین 1196', 'متفق عليه', 'بيّن النبي صلى الله عليه وسلم في هذا الحديث أنه لولا ما خشيَه من لُحوق الجهد والمشقة والشدة بأمته وأتباعه الذين آمنوا به: لأمرهم أمر إلزام وفرض بأن يستاكوا مع كل وضوء، ولكنه امتنع عن ذلك رحمة بهم وشفقة عليهم، ولم يجعله من الفرائض المتحتمة، وإنما من السنن المستحبة التي يثاب فاعلها ولا يعاقب تاركها.', 'تأكد استحباب السواك مع كلِّ وضوءٍ، وأنَّ ثوابه قريبٌ من ثواب الواجبات.
أنَّ السِّواك عند الوضوء -وعند غيره من العبادات من باب أولى- ليس بواجب، فقد منعه -صلى الله عليه وسلم- من إيجابه على أُمَّته مخافة مشقتهم.
أنَّ الذي منع الأمر بوجوبه هو المشقة، وذلك خشية عدم القيام به، ممّا يترتَّب عليه الإثمُ بتركه.
هذا الحديث العظيم دليلٌ على القاعدة الشرعية، وهي: "درء المفاسد مقدَّمٌ على جلب المصالح"؛ فمفسدة الوقوع بالإثم من ترك الواجب، مَنَعَتْ من مصلحة وجوب السِّواك عند كل وضوء.
هذا الحديث الشريف من أدلَّة القاعدة الكبرى: "المشقَّة تجلب التيسير"؛ فخشية المشقَّة سبب عدم فرضيته.
شفقة النبي -صلى الله عليه وسلم- على أمته, فكثير من العبادات الفاضلة يترك النَّبي -صلى الله عليه وسلم- فعلها مع أمته، أو أَمْرَهُمْ بها، خشيةَ فرضها عليها.
سعة هذه الشريعة وسماحتها، ومسايرتها للحالة البشرية الضعيفة؛ قال تعالى: {يُرِيدُ اللَّهُ أَنْ يُخَفِّفَ عَنْكُمْ} وقال: {وَمَا جَعَلَ عَلَيْكُمْ فِي الدِّينِ مِنْ حَرَجٍ}.
الحكمة في الأمر بالسواك أن يكون المسلم في حالة كمال النظافة؛ لإظهار شرف العبادة, ولئلا يؤذي الملائكة والمصلين.
لم يرد في الحديث موضع الاستياك لكن العلماء ذكروا أنه عند المضمضة لمناسبته.
يدل الحديث على قاعدة أصولية، وهي: أن الأمر المطلق يفيد الوجوب، ووجهه: أنَّه لو كان الأمر يفيد الاستحباب، لما امتنع -صلى الله عليه وسلم- من أمرهم بالسواك؛ ولكن ما يقتضيه الأمر، وما يفهمه الصحابة والعلماء من الأمرِ المجرَّدِ عن قرينة صارفة، هو الوجوب، وهو الذي منعه من أمرهم بالسواك.
أن النبي -صلى الله عليه وسلم- له أن يجتهد في الأحكام, ثم إن أقرَّه الله تعالى فالحكم شرعي بإقرار الله, وإن لم يقرَّه الله -تعالى- ارتفع الحكم.
استحباب إزالة الروائح الكريهة عند الصلاة وعند دخول المساجد.', 'لولا : حرف امتناع لوجود, أي امتناع حصول شيء لوجود شيء يمنع، والمعنى هنا لولا خوف المشقة على أمتي لأمرتهم بالسواك أمرًا لازمًا.
أشُقَّ : أُثقِل عليهم, من المشقة وهي الشدة.
أُمَّتي : جماعتي, والمراد بهم أمة الإجابة, وهم من آمن به واتبعه.
لأمرتهم : لألزمتهم.
بالسواك : باستعمال السواك, وهو اسم للعود الذي يستاك به من الأراك وغيره.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8374', false),
(21197, 2, 209, 1197, 'hadith', 'عن حذيفة رضي الله عنه، قال: كان رسول الله صلى الله عليه وسلم، إذا قام من النوم يشوص فاه بالسواك.', 'Whenever the Messenger of Allah (ﷺ) got up (from sleep), he would rub his teeth with Miswak (tooth-stick)..', 'حذيفة رضي الله عنه', 'Hudaifah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1197', 'Riyad as-Salihin 1197', 'ریاض الصالحین 1197', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21198, 2, 209, 1198, 'hadith', 'عن عائشة رضي الله عنها، قالت: كنا نعد لرسول الله، سواكه وطهوره، فيبعثه الله ما شاء أن يبعثه من الليل، فيتسوك ويتوضأ ويصلي.', 'We used to prepare for the Messenger of Allah (ﷺ) a Miswak (tooth-stick) and the water for making Wudu''. Whenever Allah wished to awaken him from sleep at night, he (ﷺ) would brush his teeth with Miswak, make Wudu'', and perform Salat..', 'عائشة رضي الله عنها', '''Aishah (may Allah be pleased with her)', 'صحيح', 'رياض الصالحين 1198', 'Riyad as-Salihin 1198', 'ریاض الصالحین 1198', 'رواه مسلم', 'تخبر عائشة رضي الله عنها أنها كانت تُهَيِّئ للنبي صلى الله عليه وسلم سِواكه والماء الذي يتوضأ به من الليل، ثم يوقظه الله -تبارك وتعالى- من نومه في أي وقت من الليل، فإذا استيقظ شَرَع في دَلْك أسنانه بالسواك؛ ليُزيل به رائحة الفم التي تحدث عادة بسبب النوم، ثم يتوضأ وضوءه للصلاة، ثم يصلي صلاة الليل.', 'استحباب التسوك قبل الوضوء، وقبل الصلاة، وعند القيام من النوم.
عناية أزواج النبي -صلى الله عليه وسلم- به، وحرصهن على ما يرضي النبي -صلى الله عليه وسلم- من تهيئة ما يلزمه للطاعة والعبادة.
خدمة المرأة لزوجها.
جواز الاستعانة بالآخرين لإعداد الطهور.
استحباب التأهب للعبادة قبل وقتها والاعتناء بها.
أن أرواح العباد بيد الله -تعالى- يُصَرِّفُها كيف شاء، وفي الآية: (فيمسك التي قضى عليها الموت ويرسل الأخرى).
أن النبي -صلى الله عليه وسلم- لم يَكن يُوقظ للصلاة بالليل، بل متى ما أيْقَظَه رَبُّه صلَّى.
أن النوم ناقض للوضوء، وهذا هو الأصل، لكن من خصوصياته -صلى الله عليه وسلم- أنه لا ينتقض وضوؤه بالنوم؛ لقوله -صلى الله عليه وسلم- كما في الصحيحين : "إن عَيْنَيَّ تَنَامان ولا ينام قلبي".وعليه يحمل حديث الباب على الاختيار؛ ولهذا قال الحافظ ابن حجر -رحمه الله-: "كان ربما تَوضأ إذا قام من النوم، وربما لم يتوضأ".', 'نعد : نُهيِّئ.
طهوره : أي: الماء الذي يتطهر به.
يبعثه : يوقظه من نومه.
يتسوك : ينظف فمه وأسنانه بالسواك.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3758', false),
(21199, 2, 209, 1199, 'hadith', 'عن أنس رضي الله عنه، قال: قال رسول الله صلى الله عليه وسلم : «أكثرت عليكم في السواك».', 'The Messenger of Allah (ﷺ) said, "I stress upon you to use Miswak (tooth- stick).".', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1199', 'Riyad as-Salihin 1199', 'ریاض الصالحین 1199', 'رواه البخاري', null, null, null, 'sunnah.com', null, false, null, false),
(21200, 2, 209, 1200, 'hadith', 'عن شريح بن هانئ قال: قلت لعائشة، رضي الله عنها: بأي شيء كان يبدأ النبي صلى الله عليه وسلم إذا دخل بيته. قالت: بالسواك.', 'I asked ''Aishah (may Allah be pleased with her): "What was the first thing which the Prophet (ﷺ) would do when he entered his house?" She replied: "He would use Miswak (tooth-stick).".', 'شريح بن هانئ قال: قلت لعائشة رضي الله عنها', 'Shuraih bin Hani (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1200', 'Riyad as-Salihin 1200', 'ریاض الصالحین 1200', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false)
